INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0158db9fe835bca0d1ee','ds-guide-planning','school:tesu','question','When should I stop collecting TESU electives and work on the difficult rows?','Example situation: It feels good to finish inexpensive electives, but I keep avoiding the remaining TESU major courses because they look harder. The total credit count is rising and I am not sure graduation is getting closer. How can I use the plan to pick a more useful next step without losing motivation? I want the progress display to reflect the degree, not just the amount of study I have done.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-accounting/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0158db9fe835bca0d1ee-guide-1','ds-guide-momentum','post:ds-starter-0158db9fe835bca0d1ee',NULL,'Look at the remaining requirement groups rather than the collection total. Once the genuine elective space is filled, another accepted elective may not reduce the degree at all. Identify the next open subject, level, or university requirement that constrains completion. Then choose a manageable supported option for that row. This turns the audit into a decision about useful progress instead of a scoreboard for accumulating the easiest credits.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0158db9fe835bca0d1ee' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0158db9fe835bca0d1ee-guide-2','ds-guide-planning','post:ds-starter-0158db9fe835bca0d1ee',NULL,'Break the demanding course into a smaller next action: review its syllabus, schedule a study block, or complete the first assignment after enrolling. Keep the full requirement visible but make the week''s task concrete. If a course is a poor fit, compare a real alternative for the same row rather than escaping into an unrelated elective. Momentum matters most when it moves the remaining degree work forward.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0158db9fe835bca0d1ee' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-017a6faf646813fcf2d7','ds-guide-planning','course:christianleadersinstitute-plan-the101','question','If Christian Leaders learning is free, what belongs in the degree budget?','Example situation: I’m exploring Christian Leaders courses because the learning material may be accessible without a traditional course tuition charge. I’m unsure what happens when I want an academic record for a receiving college rather than just studying the subject. Which admissions, verification or transcript steps should I include? I want to compare the complete eligible credit route without assuming that free lesson access means every college-record service, required process or receiving-degree expense is also free.','https://degreesteps.com/courses.html?provider=Christian%20Leaders%20Institute',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-017a6faf646813fcf2d7-guide-1','ds-guide-money','post:ds-starter-017a6faf646813fcf2d7',NULL,'Separate learning access from the particular academic-record route. The current directory describes a distinct institution-issued transcript pathway with eligibility and verification requirements. Course access alone should not be priced as a complete university transfer outcome. Use the actual requirements and charges for the record you need, and keep receiving-school applicability separate. That gives you an honest budget without converting a useful free learning resource into an unsupported promise of free degree credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-017a6faf646813fcf2d7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-017a6faf646813fcf2d7-guide-2','ds-guide-transfers','post:ds-starter-017a6faf646813fcf2d7',NULL,'Save the exact source course and identify the supported receiving placement in your chosen degree. Then add any required admission, verification, completion and transcript steps to the checklist. If you are only exploring the learning, keep the course as a saved option. Marking it earned should reflect the source’s actual completion requirements and issued record, while the university’s accepted course and credit amount remain a separate school-specific evaluation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-017a6faf646813fcf2d7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-01d2b11eebcf6e95f75a','ds-guide-planning','school:general','question','I want to teach, but I also want real classroom experience. Can I still accelerate?','Example situation: I am considering becoming an elementary teacher and would prefer to spend time in actual classrooms rather than do everything online. Saving money matters, so I am interested in taking some general education courses elsewhere first. I do not want to accidentally pick an education degree that does not lead toward my intended teaching role. How should the plan handle the classroom preference and the career requirements?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-01d2b11eebcf6e95f75a-guide-1','ds-guide-careers','post:ds-starter-01d2b11eebcf6e95f75a',NULL,'Prepared guide answer: Name the teaching role and the state where you expect to work before choosing an exact program. Use Find a degree to compare format and subject, but distinguish an education-related degree from a program designed for the relevant licensure route. Outside coursework may help with eligible requirements; it does not replace student teaching or other required practical experiences simply because you prefer an accelerated schedule.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-01d2b11eebcf6e95f75a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-01d2b11eebcf6e95f75a-guide-2','ds-guide-campus','post:ds-starter-01d2b11eebcf6e95f75a',NULL,'Prepared guide answer: Keep your preferred classroom experience as a real decision factor rather than an optional extra you will figure out after enrolling. List required placement periods and any travel or work adjustments alongside tuition. You can still compare transfer options for the parts that allow them, while protecting the practical training you want. A useful next action is finding the exact program’s placement structure and fitting it into your work calendar.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-01d2b11eebcf6e95f75a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-026aa8fa03391037a33a','ds-guide-planning','school:tesu','question','Should I choose TESU Finance or Accounting if I already have business credits?','Example situation: I have a mix of business courses and am deciding between Finance and Accounting at TESU. The major names both fit my interests, so I am tempted to pick whichever plan has fewer open rows. What else should I compare? I want to use existing credit efficiently while choosing a degree that makes sense for the work I hope to do afterward.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-finance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-026aa8fa03391037a33a-guide-1','ds-guide-transfers','post:ds-starter-026aa8fa03391037a33a',NULL,'Compare the exact area of study in each degree using the same original transcript. Shared business content can be useful in both, but the specialized requirements, level rules, and any currency constraints still matter. Accounting''s reviewed model includes specific course age rules, so the age of a relevant existing course can change the result. Count remaining applicable coursework rather than just the number of rows with familiar titles.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-026aa8fa03391037a33a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-026aa8fa03391037a33a-guide-2','ds-guide-careers','post:ds-starter-026aa8fa03391037a33a',NULL,'Add a few target job descriptions to the comparison and identify whether they require a particular field or later professional credentials. The standard Accounting degree is distinct from an Accounting/CPA route, and a bachelor degree does not settle state licensing eligibility. If the academic fit is close, choose the field whose remaining work supports your goal; if one route wastes substantial completed work, make that tradeoff visible before deciding.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-026aa8fa03391037a33a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-05ce03431a3ed7c4ff92','ds-guide-planning','course:study-456eece51a238a5d05','question','A spreadsheet says Accounting 101 → 201. Is that a choice or a sequence?','Example situation: I’m reviewing an accounting route and see a spreadsheet cell with an arrow between two source courses. Other rows use the word “or,” so I’m not sure whether the accounting row represents an alternative or a sequence that requires both classes. How should I translate that into a degree plan? I want to understand the real workload and cost before treating a complicated spreadsheet cell as one simple course selection.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-05ce03431a3ed7c4ff92-guide-1','ds-guide-courses','post:ds-starter-05ce03431a3ed7c4ff92',NULL,'Read an arrow as a reason to inspect the published route, not as a reliable one-course choice. It may describe a prerequisite sequence, a two-course requirement, or simply the spreadsheet author’s suggested order. Keep those possibilities distinct. The receiving agreement and source prerequisites should determine whether you need both courses and what each contributes. A required two-course combination cannot be priced or scheduled as though either course alone completes the receiving requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-05ce03431a3ed7c4ff92' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-05ce03431a3ed7c4ff92-guide-2','ds-guide-transfers','post:ds-starter-05ce03431a3ed7c4ff92',NULL,'Represent each original source course as its own task and record when two are genuinely required. If their combined completion produces one receiving award, the plan should keep that relationship explicit and prevent the same source work from being counted elsewhere again. If they are merely alternatives, choose one supported route. Writing the distinction into the requirement row gives you a clearer next step than copying the spreadsheet’s arrow into a personal checklist.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-05ce03431a3ed7c4ff92' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-064923cf56245646e50b','ds-guide-planning','school:liberty','question','Why can a one credit provider course appear beside a larger requirement?','Example situation: I noticed that a provider page, a recommendation record, and a receiving requirement can show different credit quantities. I was about to assume the largest number was what I would earn. How should I read an outside option in my Liberty plan without confusing the provider course, its original recommended credit, and the amount a university might award for it?','https://degreesteps.com/degree-plans/liberty-history-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-064923cf56245646e50b-guide-1','ds-guide-courses','post:ds-starter-064923cf56245646e50b',NULL,'Keep the original course quantity and any receiving award as separate fields. One reviewed example is UPI Environmental Science: its original recommendation is one semester credit. A larger marketing quantity or destination requirement does not change that source record. A course option needs its own exact receiving evidence before the plan can use a different award; a title match or provider partnership is not enough.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-064923cf56245646e50b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-064923cf56245646e50b-guide-2','ds-guide-planning','post:ds-starter-064923cf56245646e50b',NULL,'Open the evidence for the actual requirement and look for the source identity, version, original quantity, and proposed destination award. If the destination placement is conditional, it should remain visibly conditional and should not inflate completed progress. You can save a candidate while comparing alternatives, but do not purchase it on the assumption that a larger row label guarantees a larger amount of transferable credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-064923cf56245646e50b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-067064e24768d7f557ab','ds-guide-planning','school:tesu','question','How should I add international coursework when the grading and credit systems are different?','Example situation: I’m comparing U.S. degrees with coursework from another country and do not want to lose the original academic details. The transcript may use a different grading scale, language or unit system from the receiving school. Should I translate the numbers into familiar U.S. values before adding them? I would like to understand what belongs in the course collection and what depends on an evaluation, rather than guessing a conversion that makes the degree plan look more complete than it is.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-067064e24768d7f557ab-guide-1','ds-guide-courses','post:ds-starter-067064e24768d7f557ab',NULL,'Preserve the original institution, course descriptions, results and unit labels in your source documents. Do not invent a U.S. letter grade or semester-credit value. If a record form cannot represent the original unit system, leave that field unknown and retain the original detail in your notes or source record. The receiving institution’s required evaluation and document rules determine how that work can be considered for the particular degree and admission route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-067064e24768d7f557ab' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-067064e24768d7f557ab-guide-2','ds-guide-transfers','post:ds-starter-067064e24768d7f557ab',NULL,'Keep an evaluated receiving award separate from the original coursework when it becomes available. Record any required translation, official-document delivery or evaluation task in the checklist before relying on a completion date. Avoid sending private academic records to an unrelated service simply because it offers a quick estimate. A useful degree comparison preserves what is known, identifies the institution’s actual process and counts only the supported award toward the chosen program’s requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-067064e24768d7f557ab' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-06ca69f0aa0765918dbe','ds-guide-planning','school:liberty','question','What should my first week look like if I am starting Liberty planning from zero?','Example situation: I have no college credits and am excited to start, but the full Liberty worksheet makes the project feel enormous. I do not need every decision made tonight. What are the first few things I should do so I end the week with a real direction, a manageable first course, and a budget instead of another folder of research links?','https://degreesteps.com/degree-plans/liberty-human-services-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-06ca69f0aa0765918dbe-guide-1','ds-guide-momentum','post:ds-starter-06ca69f0aa0765918dbe',NULL,'First choose the exact degree and online or residential format. Next look at the first open requirement with a supported outside option that matches your study preferences. Compare its workload, assessment style, and complete price before committing. Saving one suitable course is useful progress; buying several memberships before you know your available hours creates decisions and bills before you have built a study routine.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-06ca69f0aa0765918dbe' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-06ca69f0aa0765918dbe-guide-2','ds-guide-money','post:ds-starter-06ca69f0aa0765918dbe',NULL,'Set a small weekly study block and a clear next action for that course. Keep the rest of the worksheet as a map, rather than a demand to start everything at once. At the end of the week, review whether the workload fits and adjust the next course accordingly. A plan becomes easier to follow when the next step is specific and the longer route remains visible without competing for attention.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-06ca69f0aa0765918dbe' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-07c7506bb7182ee7ab05','ds-guide-planning','course:sophia-a27611acd8861d68d6','question','Should I start English Composition I first or leave it until later?','Example situation: I’m planning to use a subscription for several general education courses, and English Composition I is on my list. I can study most evenings, but I don’t know how written assignments fit into a short membership. Would starting writing first help me use the rest of the month better? I want a sensible order that includes time for feedback, rather than assuming every class finishes as soon as I submit the last assignment.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-07c7506bb7182ee7ab05-guide-1','ds-guide-courses','post:ds-starter-07c7506bb7182ee7ab05',NULL,'Put the writing course near the beginning of your proposed schedule, then read its assignment requirements before starting the subscription. A writing course can include work that must be reviewed after submission. Keep another eligible course ready so a feedback wait does not become a complete study break. Your available evenings are a planning assumption; the course’s published requirements and actual feedback determine when you can finish and request its record.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-07c7506bb7182ee7ab05' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-07c7506bb7182ee7ab05-guide-2','ds-guide-transfers','post:ds-starter-07c7506bb7182ee7ab05',NULL,'Open the composition requirement in your degree plan and keep the exact Sophia option attached to that row. Check whether the degree needs a first composition course, a second composition course, or a specific writing sequence. Saving both writing courses is useful for comparison, but only the applicable completed course should satisfy each requirement. A course still awaiting final completion remains in progress, even when you have submitted all your own work.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-07c7506bb7182ee7ab05' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0808e4bd9e9a4f709305','ds-guide-careers','course:straighterline-f425ab67b8358b9828','question','Will a transfer-friendly anatomy lab also satisfy a health-program prerequisite?','Example situation: I’m exploring a health-related career and would like to complete affordable science courses before enrolling. An anatomy lab appears in the source library, but a professional program may have separate admission and laboratory requirements. How should I keep those requirements straight? I’m interested in the quickest appropriate route, but I would rather know early if a course counts toward a general degree requirement without satisfying the prerequisite for the professional program I eventually want.','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0808e4bd9e9a4f709305-guide-1','ds-guide-courses','post:ds-starter-0808e4bd9e9a4f709305',NULL,'Start with the exact professional program and admission route, including its location and laboratory conditions. A college can accept a source course as general degree credit while applying a different rule to a health-program prerequisite. Keep those decisions separate in the plan. The lab’s title, delivery format, original credits and the receiving program’s published requirement should be considered together before you select an outside science course for that specific purpose.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0808e4bd9e9a4f709305' AND p.user_id='ds-guide-careers' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0808e4bd9e9a4f709305-guide-2','ds-guide-careers','post:ds-starter-0808e4bd9e9a4f709305',NULL,'Use the degree worksheet for the academic placement and add any separate admission requirement to your checklist. That makes it easier to see whether the next task is an outside course, a required format of laboratory work, an application step or a later clinical requirement. Avoid building a promised licensed-career pathway from general education matches alone. A useful accelerated plan preserves the program’s professional conditions while finding legitimate flexibility around them.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0808e4bd9e9a4f709305' AND p.user_id='ds-guide-careers' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-08c4312ea546fdc3d53d','ds-guide-money','school:general','question','My employer reimburses tuition after I pass. How should I plan the cash I need first?','Example situation: My workplace offers education reimbursement, but payment comes after the course is finished and the paperwork is approved. I can cover some costs upfront, not an entire year of tuition. I also do not know whether the benefit includes alternative course providers or only university courses. How should I compare a lower-cost transfer route while keeping the reimbursement timing and eligibility separate from my actual spending?','https://degreesteps.com/guides/finish-faster-without-wasting-credit/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-08c4312ea546fdc3d53d-guide-1','ds-guide-money','post:ds-starter-08c4312ea546fdc3d53d',NULL,'Prepared guide answer: Build a cost view with two amounts: what you must pay when each course begins and what a documented employer benefit may later reimburse. Keep provider coursework and university tuition separate because the benefit may treat them differently. The degree plan can identify applicable courses, but it should not label a purchase as reimbursable just because it helps the degree. Use the employer’s written terms for that second calculation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-08c4312ea546fdc3d53d' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-08c4312ea546fdc3d53d-guide-2','ds-guide-planning','post:ds-starter-08c4312ea546fdc3d53d',NULL,'Prepared guide answer: Check which receipts, completion records, grades, deadlines, and program approvals the benefit requires, then make those document tasks part of your course sequence. You may prefer a smaller first purchase even when a larger bundle has a lower average price. Compare the amount of cash tied up while waiting for reimbursement. A good route should fit both the final net cost and the money available to get started.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-08c4312ea546fdc3d53d' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-098bf394ffe72c14e92e','ds-guide-planning','course:sophia-f8b8499ba6644b45ca','question','How do I plan a writing course when my school has a transcript deadline?','Example situation: I want to use English Composition II before a planned college start date. The course is self-paced, which sounds flexible, but the school will need the completed record by a deadline. How much of my schedule should I treat as study time, and what other steps belong in the plan? I’d rather build a realistic buffer now than discover that submitting my final paper and delivering an official transcript are different events.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-098bf394ffe72c14e92e-guide-1','ds-guide-courses','post:ds-starter-098bf394ffe72c14e92e',NULL,'Work backward from the receiving school’s actual document deadline. Your schedule needs space for reading and writing, assessment review, any permitted revisions, final course completion and transcript processing. Self-paced describes when you can work; it does not eliminate those separate steps. Add the deadline and transcript task to your checklist, then give yourself a buffer instead of treating your intended paper-submission date as the date the school receives credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-098bf394ffe72c14e92e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-098bf394ffe72c14e92e-guide-2','ds-guide-transfers','post:ds-starter-098bf394ffe72c14e92e',NULL,'Keep the course marked in progress while completion is still pending. Once the provider issues the final result, record the actual completion date and arrange the required official record. The receiving school’s evaluation is another status, separate from your personal course completion. That separation helps when a deadline changes: you can see whether the remaining action is coursework, a transcript request, or the college’s review rather than repeating work unnecessarily.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-098bf394ffe72c14e92e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0a79d2ece5335064ab39','ds-guide-planning','school:umpi','question','Can YourPace still make sense if I cannot study every evening?','Example situation: I work full time, care for family, and usually have a few dependable study blocks each week. Self paced study appeals to me, but I worry that session pricing only rewards people who can study constantly. How should I compare UMPI with other routes? I need a plan that respects my schedule rather than making me feel behind before I even start the first course.','https://www.umpi.edu/yourpace/tuition/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0a79d2ece5335064ab39-guide-1','ds-guide-momentum','post:ds-starter-0a79d2ece5335064ab39',NULL,'Begin with the hours you can reliably protect, not an exceptional week when everything goes right. The reviewed YourPace price is per eight week undergraduate session, so your pace affects how many sessions you may need. That makes workload fit an important cost input. Self paced is flexibility in how you move through work; it is not evidence that the work takes no time or that all courses will feel equally easy.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0a79d2ece5335064ab39' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0a79d2ece5335064ab39-guide-2','ds-guide-money','post:ds-starter-0a79d2ece5335064ab39',NULL,'Use a realistic and a slower budget scenario, then compare them with the remaining coursework in other degrees. You can also separate outside preparation from paid university sessions where exact supported placements permit it. Avoid opening multiple provider subscriptions simply to feel faster. A route is useful when you can keep studying consistently and afford its likely timeline, even if another person could complete the same work much more quickly.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0a79d2ece5335064ab39' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0a95d2b21d89a468ae76','ds-guide-planning','course:sophia-aa6e9b4ed492b94e36','question','Do I need the anatomy lecture, the lab, or both?','Example situation: I’m looking at health-related degrees and noticed that Anatomy and Physiology I and its lab are separate courses. One program lists a science requirement, while another specifically mentions laboratory work. How should I decide what to save and take? I don’t want to assume the lab is automatically included in the lecture, or complete an extra course because two schools describe the same general subject differently in their degree requirements.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0a95d2b21d89a468ae76-guide-1','ds-guide-courses','post:ds-starter-0a95d2b21d89a468ae76',NULL,'Open the exact science requirement and read whether it requires a lecture, a laboratory, or a combined award. Save the lecture and lab as separate source courses when they have separate identities. Then examine how the receiving program allocates those courses. A one-credit laboratory should retain its own quantity; it does not become a three-credit science course simply because the plan groups the subject under one heading.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0a95d2b21d89a468ae76' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0a95d2b21d89a468ae76-guide-2','ds-guide-transfers','post:ds-starter-0a95d2b21d89a468ae76',NULL,'For a health or licensed career, keep the program’s laboratory and admission conditions visible alongside the degree requirement. An accepted general education science course may not satisfy a professional program’s prerequisite or laboratory format. Use the plan’s source evidence to distinguish those decisions before purchasing. If the program needs both components, your checklist should show two source tasks and the combined receiving result only where that allocation is supported.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0a95d2b21d89a468ae76' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0ab65ffbb3808641280c','ds-guide-planning','school:umpi','question','How do I compare UMPI and TESU without treating credits and sessions as the same thing?','Example situation: UMPI and TESU both sound like flexible completion options, but their prices and degree structures are presented differently. I have an existing course collection and want to know which route uses it best. How can I compare them without assuming a session price is the whole degree cost or choosing whichever school shows the largest headline transfer limit on a marketing page?','https://www.umpi.edu/yourpace/tuition/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0ab65ffbb3808641280c-guide-1','ds-guide-money','post:ds-starter-0ab65ffbb3808641280c',NULL,'Use the same original courses as the input, then evaluate each exact degree under its own rules. Compare remaining named requirements, source limits, university work, and any level constraints before comparing price. UMPI''s reviewed rate is per eight week undergraduate session; TESU''s standard reviewed pricing uses a different structure. Those billing units cannot be compared directly as though they purchase an identical amount of remaining work.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0ab65ffbb3808641280c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0ab65ffbb3808641280c-guide-2','ds-guide-planning','post:ds-starter-0ab65ffbb3808641280c',NULL,'Build realistic cost ranges after the academic comparison, with your study schedule attached to the session estimate. Keep each model''s evidence status visible: neither school currently has a fully ready published DegreeSteps template. A speculative basket should not outrank a supported route because it produces a smaller number. The useful comparison explains which facts are established and which research must be completed before a student can safely act.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0ab65ffbb3808641280c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-0f397f489b0317a33737','ds-guide-planning','course:study-3ed4b0b932825b2134','question','Which Study.com membership actually supports transferable college credit?','Example situation: I’m interested in using Intro to Business and several other Study.com courses for a degree. The site has different products and membership names, and some search results discuss tutoring or test preparation. How should I make sure I am budgeting for a credit-bearing option? I don’t want to choose the lowest advertised membership price and later find that it covers learning material without the assessments or records required for college credit.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0f397f489b0317a33737-guide-1','ds-guide-courses','post:ds-starter-0f397f489b0317a33737',NULL,'Use the college-credit product terms attached to the course choice, rather than a general learning or test-prep promotion. The current reviewed assessment policy names College Saver and College Saver Pro; their included course and exam allowances still matter when comparing costs. Match the exact product to the courses you intend to complete, then keep any extra assessment or transcript charges separate from the subscription price in your budget.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0f397f489b0317a33737' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-0f397f489b0317a33737-guide-2','ds-guide-money','post:ds-starter-0f397f489b0317a33737',NULL,'Build a small list of the courses your degree can actually use before choosing a membership. Include the planned number of credit-bearing assessments and a realistic study schedule. That makes the product comparison concrete and reduces the chance of paying for an unsuitable tier. Course access, successful completion and acceptance by the receiving university remain separate steps, so a membership purchase should not increase the earned-credit total in your plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-0f397f489b0317a33737' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-12a64ae52e033cffcfbd','ds-guide-planning','school:general','question','How should I plan around caregiving that can change without warning?','Example situation: I help care for a parent, and appointments or medical problems can interrupt an otherwise good week. I want to return to college without signing up for a schedule that turns every family emergency into a crisis. I already have some general education courses from years ago. How would I use those courses and choose a next step with less financial pressure?','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-12a64ae52e033cffcfbd-guide-1','ds-guide-transfers','post:ds-starter-12a64ae52e033cffcfbd',NULL,'Prepared guide answer: Bring the earlier courses into My courses first using a transcript or the spreadsheet template. Review the imported rows before adding them, then compare degrees against the same records. That can identify work you may not need to repeat. Next, separate courses with flexible access from university requirements with fixed timing, so the part that needs a calendar commitment is clear before you pay.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-12a64ae52e033cffcfbd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-12a64ae52e033cffcfbd-guide-2','ds-guide-money','post:ds-starter-12a64ae52e033cffcfbd',NULL,'Prepared guide answer: Compare what happens financially if a course takes twice as long as you hope. A low monthly price can still be expensive during a long interruption, while a course purchase may have its own access or completion rules. Keep your course records and notes updated in your account, and pause new purchases when family demands rise instead of opening several memberships at once.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-12a64ae52e033cffcfbd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1462a002744334bde564','ds-guide-planning','course:study-3ed4b0b932825b2134','question','Do lesson completion badges count as finished college-credit courses?','Example situation: I’m using course material to explore a subject before deciding whether to pursue credit. The platform shows lesson progress and completion markers, which makes it tempting to mark the course finished in my degree plan. What should count as the actual completion point for a credit-bearing course? I want my personal progress to be encouraging without confusing watched lessons, a platform certificate, an eligible final result and credit awarded by the receiving college.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1462a002744334bde564-guide-1','ds-guide-courses','post:ds-starter-1462a002744334bde564',NULL,'Use the provider’s credit-bearing completion requirements as the boundary for the original course record. Watching lessons or finishing a practice activity can be useful progress without completing the course for transfer purposes. The applicable product, required assessments and issued result matter. Keep the course in progress until that source completion exists, and retain the provider record that identifies the course, original credits, units and actual completion date.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1462a002744334bde564' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1462a002744334bde564-guide-2','ds-guide-transfers','post:ds-starter-1462a002744334bde564',NULL,'After source completion, keep the receiving college’s evaluation separate. You can finish a legitimate outside course before a university has applied it to your degree. That distinction lets the plan show real work completed without claiming an award too early. If you were using a learning-only product, use the course details to identify the actual credit-bearing route before budgeting additional work, rather than assuming a progress badge already represents transferable academic credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1462a002744334bde564' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1773d1cf4da1d6b7e307','ds-guide-planning','school:liberty','question','How do I avoid choosing the wrong science course or missing a lab?','Example situation: I see science courses with similar names but different credit amounts. Some include a lab and others do not. I want to fill a Liberty science requirement with outside coursework, but I do not understand whether a larger credit number always makes one course a better choice. What should I compare before adding one of these courses to my degree plan?','https://degreesteps.com/degree-plans/liberty-history-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1773d1cf4da1d6b7e307-guide-1','ds-guide-courses','post:ds-starter-1773d1cf4da1d6b7e307',NULL,'Read the exact requirement and the exact receiving match together. A lecture, a laboratory, and a combined course are different academic records, even if the provider places them next to each other in a catalog. Check the original course credits, the receiving award, and whether the requirement calls for a lab. Do not add a second course merely to make the credit totals look more convincing.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1773d1cf4da1d6b7e307' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1773d1cf4da1d6b7e307-guide-2','ds-guide-planning','post:ds-starter-1773d1cf4da1d6b7e307',NULL,'Choose the option that satisfies the named row with the least unnecessary work for your situation. Where an agreement requires a sequence or a pair of courses, keep that bundle intact rather than treating either half as enough. Save the source version with your choice so a later catalog change does not erase why you selected it. Extra credits help only if the degree has a legitimate place for them.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1773d1cf4da1d6b7e307' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-197cabd3ec17a4fe6074','ds-guide-military','school:general','question','What does a self-paced plan need to account for during a deployment?','Example situation: I may deploy next year and could have unreliable internet or limited quiet space. I want to start working toward a degree now, but a plan that depends on uninterrupted video sessions or scheduled proctored exams may not work later. I can study independently and would like to keep moving when possible. How should I choose the first courses and avoid paying through a period when I cannot participate?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-197cabd3ec17a4fe6074-guide-1','ds-guide-courses','post:ds-starter-197cabd3ec17a4fe6074',NULL,'Prepared guide answer: Use the course library to inspect the actual assessment format and provider conditions before choosing your next course. Self-paced does not automatically mean offline access, no scheduled exam, or unlimited access without payments. Build a short sequence that fits the conditions you know now, then identify which later courses need live connectivity. Save the course choices without marking them earned or opening every provider membership at once.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-197cabd3ec17a4fe6074' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-197cabd3ec17a4fe6074-guide-2','ds-guide-military','post:ds-starter-197cabd3ec17a4fe6074',NULL,'Prepared guide answer: Before deployment, keep your original course records and plan in your account and note any transcript or enrollment deadlines. Compare access duration and recurring billing against the period you may be unavailable. For a course with required remote assessment, identify the technology and scheduling requirements early. Military status and education benefits can affect other decisions, but they do not eliminate a provider’s published assessment requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-197cabd3ec17a4fe6074' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1a69b1463f5c3c6b65e6','ds-guide-planning','school:umpi','question','Should a continuing UMPI student switch to the newest general education plan?','Example situation: I started UMPI earlier but paused my studies, and now I am returning. The newer general education description looks different from the plan I remember. Should I automatically switch to the latest version because it is what appears on the website? I want to compare the real remaining work under my own situation instead of assuming a newer curriculum is always easier or harder.','https://www.umpi.edu/academics/general-education-curriculum/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a69b1463f5c3c6b65e6-guide-1','ds-guide-transfers','post:ds-starter-1a69b1463f5c3c6b65e6',NULL,'Preserve the catalog tied to your admission record before changing the worksheet. The reviewed UMPI general education page distinguishes continuing students, who retain incoming catalog requirements, from newly accepted students entering the new curriculum. That means the latest public overview is not automatically your governing plan. Keep your existing degree audit and the original coursework together so the comparison starts from the situation that actually applies to you.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a69b1463f5c3c6b65e6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a69b1463f5c3c6b65e6-guide-2','ds-guide-planning','post:ds-starter-1a69b1463f5c3c6b65e6',NULL,'If a catalog change is genuinely available, compare it as a separate scenario with its own rules and remaining work. A course that helps one version may land differently in the other, and a smaller looking category list does not by itself prove faster completion. Retain the historical plan until the choice is made. This prevents a redesign or a new website page from silently rewriting the student''s academic starting point.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a69b1463f5c3c6b65e6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1a888ad9cd91dab58c3c','ds-guide-planning','school:general','question','Can I compare degrees while my overseas transcripts are being evaluated?','Example situation: I completed university courses outside the United States and am considering an online bachelor’s program here. I have English translations, but I do not yet have a credential evaluation. I would like to start exploring without assuming that the credit numbers or course names mean the same thing in both countries. Is there a useful way to build a provisional plan while I gather the right documents?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a888ad9cd91dab58c3c-guide-1','ds-guide-transfers','post:ds-starter-1a888ad9cd91dab58c3c',NULL,'Prepared guide answer: You can begin with a clearly provisional inventory and retain the original institution, course title, grading system, units, and dates. Do not convert unfamiliar units into semester credits just to fill the template. Keep any translated record separate from an official evaluation. Use Find a degree to explore suitable outcomes now, while leaving specific receiving placements unresolved until the actual documentation supports them.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a888ad9cd91dab58c3c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a888ad9cd91dab58c3c-guide-2','ds-guide-money','post:ds-starter-1a888ad9cd91dab58c3c',NULL,'Prepared guide answer: Before buying new coursework, identify which large requirement blocks could be affected by the evaluation, such as writing, mathematics, or your former major. Avoid paying to repeat a subject merely because its English title looks different. Keep translation, evaluation, and transcript-delivery costs in your planning budget. A useful early decision is choosing two serious targets and organizing the documents each will use, not guessing a full credit award.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a888ad9cd91dab58c3c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1a8fd7e89fe01fad1da8','ds-guide-planning','school:umpi','question','Can any accepted course fill the sixty two electives in a UMPI BLS option?','Example situation: The UMPI Liberal Studies description includes a large elective block, which sounds ideal for the mixed credits I already have. Does that mean every accepted course can be added there without further rules? I would like to use the flexibility well, but I do not want a large elective number to hide duplicate content, level requirements, or rules about which source of credit is allowed.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a8fd7e89fe01fad1da8-guide-1','ds-guide-transfers','post:ds-starter-1a8fd7e89fe01fad1da8',NULL,'The reviewed Accounting and Project Management BLS descriptions identify sixty two elective credits, but that number is a degree structure, not a universal permission for every source. Duplicate content, applicable level requirements, university work, and the scope of alternative credit still need their governing rules. Keep original college credit separate from ACE or NCCRS recommended coursework rather than treating them as one undifferentiated pile of transferable hours.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a8fd7e89fe01fad1da8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a8fd7e89fe01fad1da8-guide-2','ds-guide-courses','post:ds-starter-1a8fd7e89fe01fad1da8',NULL,'For existing work, preserve all original records and audit what is actually useful before choosing more electives. For new courses, start with a requirement and a supported receiving placement instead of filling the apparent space with whatever is cheapest. The current UMPI course map remains a research gap in DegreeSteps, so the platform should not label an arbitrary collection of sixty two credits as an established elective basket.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a8fd7e89fe01fad1da8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1a9add0602e7011f385a','ds-guide-planning','course:study-5e9814e1aa513f4980','question','Does a 300-level source course automatically satisfy an upper-level requirement?','Example situation: I’m trying to plan major requirements and notice courses with numbers such as 305 or 306 in their titles. It would be convenient if those automatically counted as upper-level credit at my target school. Is that a safe assumption when selecting a research methods or criminal justice course? I want to know which information actually controls the level, especially if the provider’s naming system differs from the university’s own course numbering.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a9add0602e7011f385a-guide-1','ds-guide-courses','post:ds-starter-1a9add0602e7011f385a',NULL,'Treat the provider’s course number as an identifier, not a universal level rule. The independent credit recommendation describes the source level, and the receiving university determines its own course award and application to the degree. An upper-level source recommendation does not automatically replace an upper-level major requirement at every school. Open the requirement’s evidence and check the actual receiving award before relying on the course to meet an upper-level minimum.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a9add0602e7011f385a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1a9add0602e7011f385a-guide-2','ds-guide-transfers','post:ds-starter-1a9add0602e7011f385a',NULL,'Review the degree’s major and overall upper-level rules separately. A course could meet one threshold while failing to satisfy a specific major requirement, or it could be allocated as an elective. Keep the selected source course attached to the supported row and watch how the degree totals change. This approach helps you identify remaining university work early, instead of discovering near graduation that a collection of advanced-sounding titles does not meet the published requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1a9add0602e7011f385a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1c2445ca66679e264f0c','ds-guide-planning','school:tesu','question','Can I explore TESU before finding all my old transcripts?','Example situation: I am interested in TESU, but my previous colleges span several years and I do not have all the transcripts ready. Filling every course manually feels like a barrier. Can I start with an approximate picture and refine it later? I want a useful first direction without having an early estimate presented as a completed audit or a promise about what will transfer.','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1c2445ca66679e264f0c-guide-1','ds-guide-momentum','post:ds-starter-1c2445ca66679e264f0c',NULL,'Start with the records you can obtain easily and keep estimates clearly provisional. An uploaded transcript or the filled course spreadsheet can preserve many entries at once, including their original source and credits. Do not invent course codes to make an incomplete import look finished. A rough total can help you explore, but selecting outside replacements requires enough detail to avoid buying courses you have already completed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1c2445ca66679e264f0c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1c2445ca66679e264f0c-guide-2','ds-guide-transfers','post:ds-starter-1c2445ca66679e264f0c',NULL,'Use the early plan to identify the next document and a short list of likely degree fits, not to authorize a large purchase. Once actual records arrive, compare how the requirement groups change and remove redundant candidates. That is a productive sequence: explore first, bring the records together, and commit to courses when the exact open requirements are clear. Missing paperwork need not mean starting the entire journey over.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1c2445ca66679e264f0c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1d316bf223a11cd3debd','ds-guide-planning','school:umpi','question','Can I use an older UMPI general education spreadsheet as a new student?','Example situation: I found a detailed UMPI spreadsheet that many people recommend, but it was built before the latest general education change. I would like to use it as a shortcut instead of studying a catalog. If I am applying now, which parts are still useful? I do not want a familiar looking checklist to make me buy courses that satisfy an older set of rules.','https://www.umpi.edu/academics/general-education-curriculum/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1d316bf223a11cd3debd-guide-1','ds-guide-transfers','post:ds-starter-1d316bf223a11cd3debd',NULL,'The reviewed UMPI general education page says a new curriculum begins September 1, 2026. Newly accepted students for 2026–2027 or later follow that curriculum, while continuing students retain their incoming catalog requirements. An older spreadsheet can reveal possible sources and questions, but it cannot establish current placements for a new student. Keep your admission cohort attached to the plan before carrying over any requirement or course choice.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1d316bf223a11cd3debd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1d316bf223a11cd3debd-guide-2','ds-guide-planning','post:ds-starter-1d316bf223a11cd3debd',NULL,'Separate the old sheet into requirement claims and course leads. The current official overview supports forty general education credits across eight outcomes; it does not itself publish the exact transfer placement list or overlap rules. DegreeSteps has not turned that missing detail into a finished UMPI template. Preserve useful completed courses, but keep proposed purchases out of the committed basket until the current requirement placement is established.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1d316bf223a11cd3debd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-1de2f82ee6d570cffe67','ds-guide-planning','course:studycom-plan-sdcm0255','question','Why can a physics course with a lab show different source credits and degree units?','Example situation: I’m looking at a physics course with a lab while comparing a traditional credit-hour program and a competency-based program. The source course and the receiving degree do not always display the same kind of units. Does that mean one listing is wrong, or could the school apply the course differently? I want the course to satisfy the right science requirement without editing my original transcript values just to make the numbers look consistent.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1de2f82ee6d570cffe67-guide-1','ds-guide-courses','post:ds-starter-1de2f82ee6d570cffe67',NULL,'Keep the source course’s original quantity and unit system unchanged. The receiving school’s award is a separate fact and may use semester credits, quarter credits or competency units. A documented receiving award can differ from the source quantity without changing what the provider issued. The plan needs to retain both sides and show the actual science requirement being satisfied, including any laboratory component that the program specifically requires.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1de2f82ee6d570cffe67' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-1de2f82ee6d570cffe67-guide-2','ds-guide-transfers','post:ds-starter-1de2f82ee6d570cffe67',NULL,'Check whether the route uses one source course with an integrated lab or two separately completed source courses. That affects the tasks, records and possible duplicate checks. You should not create an extra lab completion merely because a receiving plan has a laboratory heading. When comparing schools, read the supported allocation for each exact degree; matching quantities alone cannot establish equivalence or satisfy a professional program’s laboratory prerequisite.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-1de2f82ee6d570cffe67' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-21e058ddc0efa7f04b67','ds-guide-planning','school:general','question','What happens to a course that has a P instead of a letter grade?','Example situation: I completed several courses during a term when my college allowed pass or fail grading. They show P on my transcript, while other courses show regular letters. I am considering two schools and do not want to label the P courses as a C just to make a form accept them. How should I enter these records, and what should I watch when comparing degree plans?','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-21e058ddc0efa7f04b67-guide-1','ds-guide-transfers','post:ds-starter-21e058ddc0efa7f04b67',NULL,'Prepared guide answer: Upload the transcript or keep P in the template exactly as the source record shows it. A pass is not permission to invent a numerical score or a letter grade. In the import preview, check the original course, credits, units, and status together. Then use the same collection for both degree comparisons so differences come from the receiving rules rather than from edited source facts.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-21e058ddc0efa7f04b67' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-21e058ddc0efa7f04b67-guide-2','ds-guide-courses','post:ds-starter-21e058ddc0efa7f04b67',NULL,'Prepared guide answer: Pay attention to requirements that have a specific minimum grade, particularly prerequisite or major courses. A pass may need different treatment from a documented letter grade, depending on the receiving rule. Keep any original grading explanation with your records and focus follow-up on the particular requirement affected. That is more useful than assuming every P transfers equally or discarding all pass-graded learning in advance.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-21e058ddc0efa7f04b67' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-21fd338783fc7b1e998f','ds-guide-planning','school:wgu','question','Should I finish my outside courses before choosing a WGU start date?','Example situation: I am eager to start WGU, but I still have a few outside courses in progress. Can I enroll now and transfer those courses later as I finish them? I do not want a start date decision to remove a useful low cost option. I need a sequence that includes completion and transcript steps, rather than just a list of courses to take.','https://degreesteps.com/degree-plans/wgu-cybersecurity-and-information-assurance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-21fd338783fc7b1e998f-guide-1','ds-guide-transfers','post:ds-starter-21fd338783fc7b1e998f',NULL,'The reviewed WGU planning rules require outside transfer work to be handled before the initial term. Do not assume you can begin the program and add a new provider course afterward to replace a remaining requirement. Keep course completion, sending each required official record, transfer evaluation, and the start date as separate milestones. A course marked finished in your collection is not the same as a completed university evaluation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-21fd338783fc7b1e998f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-21fd338783fc7b1e998f-guide-2','ds-guide-momentum','post:ds-starter-21fd338783fc7b1e998f',NULL,'Work backward from your intended start and allow a realistic paperwork interval, using the actual admissions process for the deadline. If finishing one useful outside course changes the comparison, evaluate that before committing to the start rather than hoping for a later adjustment. Your next action might be finishing the active course or arranging its transcript, not opening another membership. The sequence should protect a genuine saving without creating an avoidable last minute rush.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-21fd338783fc7b1e998f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-220b59d6e2ea18051623','ds-guide-planning','school:tesu','question','Can I use the standard TESU estimate if I have military benefits?','Example situation: I am a military learner considering TESU and have both training records and some civilian college credit. The standard price comparison is useful, but I do not know whether it reflects my rates or benefit rules. What should stay the same in my academic plan, and what needs a separate funding scenario so I do not confuse transfer acceptance with financial eligibility?','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-220b59d6e2ea18051623-guide-1','ds-guide-military','post:ds-starter-220b59d6e2ea18051623',NULL,'Keep the academic audit rooted in the same original records and exact degree requirements. Military training credit, civilian college coursework, and alternative provider coursework retain their own sources; none should be counted twice. Then add a separate financial scenario for any military rate or education benefit. The reviewed standard out of state, nonmilitary tuition binding is not a quote for that different population or a benefits eligibility decision.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-220b59d6e2ea18051623' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-220b59d6e2ea18051623-guide-2','ds-guide-money','post:ds-starter-220b59d6e2ea18051623',NULL,'Use the audit to identify the courses you still need before choosing how to fund them. A cheap outside option might be sensible out of pocket, while another course may have a documented benefit route. The right sequence depends on your actual conditions and timing. Keeping funding assumptions separate makes the comparison clearer and avoids spending benefits on coursework that your existing training or college record may already cover.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-220b59d6e2ea18051623' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-23589f31a55a1b7dc0c0','ds-guide-planning','school:tesu','question','How should failed, withdrawn or repeated courses appear in my imported records?','Example situation: My transcript includes more than completed courses: there are attempted courses, withdrawals and a later repeat of one subject. When building a degree plan, how should I bring that history in without counting every row as earned credit? I want an accurate collection that preserves the official record while showing only applicable completed work toward the degree. I’m also unsure whether a repeated class should create another requirement completion or a different evaluation of the same learning.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-23589f31a55a1b7dc0c0-guide-1','ds-guide-courses','post:ds-starter-23589f31a55a1b7dc0c0',NULL,'Use the original transcript’s result and earned-credit information for each course. Attempted hours do not automatically represent completed credit, and a withdrawal is not a finished course merely because it appears on the transcript. Review those rows during import before adding them to the collection. Keep repeated attempts distinguishable with their dates and results so the source history is preserved while the plan evaluates which completed learning can actually be used.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-23589f31a55a1b7dc0c0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-23589f31a55a1b7dc0c0-guide-2','ds-guide-transfers','post:ds-starter-23589f31a55a1b7dc0c0',NULL,'The receiving college’s repeat and transfer rules determine the academic treatment; avoid manufacturing a replacement grade or counting the same course award twice. Your degree allocation should identify the record it uses and keep other attempts visible as history where needed. GPA calculations and admission decisions can also follow rules separate from degree-credit application. Keeping the source record and receiving evaluation distinct lets you correct an import without erasing the original evidence or overstating progress.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-23589f31a55a1b7dc0c0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-262730e962e125e327ad','ds-guide-planning','school:umpi','question','How should military training and benefits appear in a YourPace comparison?','Example situation: I have military training records and am considering a session based degree because my schedule changes often. I also have some education benefits available. How do I compare UMPI without assuming that training credits count as ordinary college classes or that a benefit automatically pays for every outside provider? I want an academic plan and a funding plan that fit together without being confused.','https://www.umpi.edu/yourpace/tuition/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-262730e962e125e327ad-guide-1','ds-guide-military','post:ds-starter-262730e962e125e327ad',NULL,'Start by preserving the training transcript and any original college records as separate sources. Their evaluation can affect what coursework remains, but a broad transfer allowance does not establish each award. Keep alternative provider courses distinct as well. The reviewed UMPI source scope still has unresolved applicability questions, so the plan should not turn a military record or a partner course into automatic completed rows without exact evidence.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-262730e962e125e327ad' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-262730e962e125e327ad-guide-2','ds-guide-money','post:ds-starter-262730e962e125e327ad',NULL,'Then compare the billing schedule with your documented benefit conditions and likely study time. A program''s academic acceptance of credit is different from funding eligibility, payment timing, and the effect of a changing workload. Keep an out of pocket scenario beside any funded one so the decision remains understandable. This can reveal whether session pricing fits your circumstances without promising benefit coverage or a completion time the available records do not establish.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-262730e962e125e327ad' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-272f9b3de3699234e1ef','ds-guide-campus','school:general','question','Can I prioritize sports and student life without losing the savings from transfer courses?','Example situation: I want to attend games, join clubs, and feel part of a recognizable campus. At the same time, I do not want to pay university tuition for every general education course if eligible alternatives could help. I am not a recruited athlete and am asking about ordinary student life. How should I choose a school without pretending that the most transfer-friendly degree automatically gives the experience I want?','https://degreesteps.com/campuses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-272f9b3de3699234e1ef-guide-1','ds-guide-campus','post:ds-starter-272f9b3de3699234e1ef',NULL,'Prepared guide answer: Use Find a campus to make a shortlist based on the environment you actually want, then evaluate exact degrees within those schools. Keep student-life goals separate from academic transfer claims: a campus reputation does not establish how your courses apply. The goal is to identify a degree that combines a worthwhile campus experience with documented outside coursework, rather than starting from a generic maximum-credit percentage.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-272f9b3de3699234e1ef' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-272f9b3de3699234e1ef-guide-2','ds-guide-money','post:ds-starter-272f9b3de3699234e1ef',NULL,'Prepared guide answer: Consider how much time you want on campus and what that time would cost, including living, travel, and activities. A one-year finish may be attractive financially while providing less time for clubs or internships than you hoped. You can choose a different balance. Keep the remaining university course sequence visible so the academic route and the campus experience are planned together instead of competing surprises.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-272f9b3de3699234e1ef' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-287258be06e57633a22f','ds-guide-planning','school:general','question','Can I upload records from three colleges without sorting everything by hand?','Example situation: I attended a community college, transferred to a state university, and later took two online courses somewhere else. My newest transcript includes transfer totals from the earlier schools, so I am worried that uploading everything will count the same work twice. I do not want to type dozens of rows manually. What is the cleanest way to get these records into one usable collection?','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-287258be06e57633a22f-guide-1','ds-guide-transfers','post:ds-starter-287258be06e57633a22f',NULL,'Prepared guide answer: Use the upload flow in My courses and bring the original records from each institution. Review the extracted rows together before applying the import. A transfer summary on a later transcript is not a new original course, and the original course’s units should remain intact. If the preview repeats the same learning, resolve that duplicate in the review rather than treating each transcript appearance as additional credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-287258be06e57633a22f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-287258be06e57633a22f-guide-2','ds-guide-planning','post:ds-starter-287258be06e57633a22f',NULL,'Prepared guide answer: Keep the files labeled by issuing school and use original course codes whenever they are available. You can upload in stages, beginning with the clearest transcript, then review the next file against what is already in My courses. After the collection is organized, compare degree options using that same inventory. Changing schools in the planner should change applicability, not erase where your learning originally came from.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-287258be06e57633a22f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-29788fb747d1f4433f34','ds-guide-campus','school:tesu','question','Which transcript do I need for college courses taken during high school?','Example situation: I’m collecting records for a degree plan and have dual-enrollment classes that appear on my high school transcript. A college may also have issued a separate academic record for those classes. Which source should I use when adding the courses? I want to preserve the actual college course identity, units and grade instead of relying on a high school label that might not contain the details needed for transfer evaluation or comparison across different degree programs.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-29788fb747d1f4433f34-guide-1','ds-guide-courses','post:ds-starter-29788fb747d1f4433f34',NULL,'Use the issuing college’s course record when that is the original source of the academic credit. Keep the institution name, college course code, actual grade, credits, unit system and completion date. The high school transcript can provide useful context, but it may not replace the official college record required by the receiving institution. In an import preview, check the issuer on those rows so the high school is not accidentally recorded as the college-credit provider.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-29788fb747d1f4433f34' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-29788fb747d1f4433f34-guide-2','ds-guide-campus','post:ds-starter-29788fb747d1f4433f34',NULL,'Keep admission status separate from course credit. Taking college classes during high school does not by itself answer every receiving institution’s freshman-versus-transfer admission question or scholarship rule. Add the appropriate application decisions to your checklist while using the real original courses for academic matching. If two records describe the same dual-enrollment course, retain their evidence without creating two earned completions. Your degree allocation should reflect the source learning once.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-29788fb747d1f4433f34' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-2b7f00013c0bd9310cb2','ds-guide-planning','school:liberty','question','If I switch from online to campus, can I keep using the same course list?','Example situation: I started with an online Liberty criminal justice plan because it looked affordable. I am now considering moving to campus for part of the degree. Do I need to rebuild everything, or can the courses I saved travel with me? I want to understand which decisions can stay and which need a fresh comparison before I commit money to the move.','https://degreesteps.com/degree-plans/liberty-criminal-justice-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2b7f00013c0bd9310cb2-guide-1','ds-guide-transfers','post:ds-starter-2b7f00013c0bd9310cb2',NULL,'Keep the original course collection, then compare it against the separate residential criminal justice worksheet. The same institution and major name do not establish identical course applicability, residency obligations, or delivery requirements. Courses already completed should stay in your records; the new audit decides where they fit. Saved candidates can be retained for comparison without being treated as completed credits in either route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2b7f00013c0bd9310cb2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2b7f00013c0bd9310cb2-guide-2','ds-guide-campus','post:ds-starter-2b7f00013c0bd9310cb2',NULL,'Review the difference in remaining requirements before calculating the move. Then add housing, meals, travel, and the campus schedule to the financial comparison. A lower tuition estimate does not describe your full cost of living on campus. This gives you a practical choice: which academic work still applies, what the campus experience adds, and the next course that helps the route you actually choose.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2b7f00013c0bd9310cb2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-2e120050f4e4e59aad5f','ds-guide-planning','school:general','question','Can I use the same transfer strategy for an MBA that I used for my bachelor’s?','Example situation: I am interested in an MBA after working for several years. Low-cost transfer courses made undergraduate study look much more achievable, so I hoped graduate planning might work the same way. I also see competency-based MBA options and do not know how to compare them with regular online programs. What changes when the goal is a master’s degree rather than completing a bachelor’s?','https://degreesteps.com/blog/graduate-acceleration-is-different/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2e120050f4e4e59aad5f-guide-1','ds-guide-careers','post:ds-starter-2e120050f4e4e59aad5f',NULL,'Prepared guide answer: Graduate planning needs a separate set of rules. Begin with the exact MBA’s admission requirements, curriculum, assessment format, and published pricing, rather than carrying undergraduate ACE or transfer allowances into it. A competency-based graduate format may change how you demonstrate learning or pay for a period of study, but it does not establish that undergraduate outside courses replace graduate requirements. Use the graduate planning guide to separate these decisions.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2e120050f4e4e59aad5f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2e120050f4e4e59aad5f-guide-2','ds-guide-money','post:ds-starter-2e120050f4e4e59aad5f',NULL,'Prepared guide answer: Compare fit with your career goal, the university work you must actually complete, support, and the cost of a realistic number of billed periods. Experience can help you engage with business material, but does not guarantee a rapid finish. If a complete route for the exact MBA is not available, use its official program link in Build from a degree link so research starts from the right graduate requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2e120050f4e4e59aad5f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-2e47ed546815feea7d12','ds-guide-money','school:general','question','I found courses on three providers. Do I need all three subscriptions at once?','Example situation: I saved a mix of courses from Sophia, Study.com, and StraighterLine because different requirements seem to fit different providers. Looking at the monthly charges together is intimidating. I would like to use the strongest options without paying for memberships I am not actively using. How can I decide what to take first and know when it makes sense to move to another provider?','https://degreesteps.com/plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2e47ed546815feea7d12-guide-1','ds-guide-planning','post:ds-starter-2e47ed546815feea7d12',NULL,'Prepared guide answer: Use My plan’s suggested course order as a starting point for grouping ready work from the same provider. Keep prerequisites and any course already in progress in view. You do not have to activate every source represented in the worksheet at once. The plan can contain future options while you pay for the provider you are actually using, subject to its current access and billing terms.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2e47ed546815feea7d12' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2e47ed546815feea7d12-guide-2','ds-guide-money','post:ds-starter-2e47ed546815feea7d12',NULL,'Prepared guide answer: Before changing providers, review any unfinished assignments, grading or revision needs, cancellation timing, and transcript steps. Avoid treating a nearly finished course as done simply to fit a billing cycle. A membership group is a spending strategy, not proof that the courses have the same difficulty or timing. Revisit the order when your work schedule changes, while preserving completed courses and your actual progress in the collection.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2e47ed546815feea7d12' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-2ed2bb80ad7fe9b0c7c8','ds-guide-planning','school:general','question','If I switch from business to psychology, how much of my work can I keep?','Example situation: I began saving courses for a business degree, but I am now more interested in psychology. A few courses are already finished, and several are only ideas I saved for later. I do not want the new plan to erase my work or assume everything fits just because it carries college credit. What should I compare before deciding whether changing direction is worth the extra coursework?','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2ed2bb80ad7fe9b0c7c8-guide-1','ds-guide-planning','post:ds-starter-2ed2bb80ad7fe9b0c7c8',NULL,'Prepared guide answer: Keep your original learning in My courses and compare the two degrees using that same inventory. In Compare degrees, look at which requirements each completed course fills, which courses become electives, and what remains unused. Saved ideas are different from finished work. The meaningful comparison is the university work and applicable outside courses still needed for each degree, rather than the largest accepted-credit headline.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2ed2bb80ad7fe9b0c7c8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2ed2bb80ad7fe9b0c7c8-guide-2','ds-guide-careers','post:ds-starter-2ed2bb80ad7fe9b0c7c8',NULL,'Prepared guide answer: Look especially at prerequisite chains and the upper-level major work. A change can reuse general education while introducing specialized courses that cannot be replaced by your business selections. Pause purchases for unstarted major courses until you decide. You can keep those ideas in the collection without committing to them, then choose the route whose remaining work supports the career or graduate study you actually want.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2ed2bb80ad7fe9b0c7c8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-2ff0ac74d73792261011','ds-guide-campus','course:mapped-3dfda84242db87d053ba','question','Does taking an ASU course settle a campus degree’s residency requirement?','Example situation: I’m considering an on-campus degree and might use a Universal Learner course while planning. Because the original course comes through ASU, I’m wondering how to think about institutional residency or transfer status in a later degree. Should I assume the course counts as university coursework everywhere, or does the receiving program still apply its own rules? I want to compare campus options accurately without confusing the source institution with the college that eventually awards the degree.','https://degreesteps.com/courses.html?provider=ASU%20Universal%20Learner',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2ff0ac74d73792261011-guide-1','ds-guide-courses','post:ds-starter-2ff0ac74d73792261011',NULL,'Keep the source institution and receiving institution separate. The course’s original issuer is an important fact, but the degree-awarding program controls its own residency, enrollment and transfer rules. A course taken through another institution does not automatically satisfy that program’s required institutional coursework. Even when the source and target share a university name, use the exact program’s rules for the particular offering and route rather than assuming a general residency result.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2ff0ac74d73792261011' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-2ff0ac74d73792261011-guide-2','ds-guide-campus','post:ds-starter-2ff0ac74d73792261011',NULL,'Select the actual campus degree, then examine how the course is applied and which requirements remain at the degree-awarding institution. Include admission timing, enrollment status and the campus experience you want as separate planning considerations. This keeps the comparison useful for a student who wants substantial outside credit and a real residential program. The original course record should remain unchanged while each degree applies its own supported evaluation and institutional-work requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-2ff0ac74d73792261011' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-30703a31c67e44534779','ds-guide-planning','course:saylor-plan-saya0020','question','If Saylor learning is free, what do I need to earn college credit?','Example situation: I’m looking at Introduction to Business and like the idea of studying without an expensive subscription. I’m confused about the difference between accessing lessons, completing the regular activities and meeting the requirements for a college-credit recommendation. What should I identify before choosing this route? I want to compare the actual credit-bearing process and assessment conditions, rather than assuming that free learning material means every completion document is an official transferable college-credit record.','https://degreesteps.com/courses.html?provider=Saylor',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-30703a31c67e44534779-guide-1','ds-guide-courses','post:ds-starter-30703a31c67e44534779',NULL,'Locate the credit-bearing route for the exact Saylor course and distinguish it from practice or general completion activities. The reviewed policy describes a monitored credit final; a practice result does not substitute for that final. Include any current assessment charges, identity requirements and record-delivery steps in your plan. Free access to learning material can be valuable, but the source’s credit recommendation depends on the applicable completion and assessment requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-30703a31c67e44534779' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-30703a31c67e44534779-guide-2','ds-guide-money','post:ds-starter-30703a31c67e44534779',NULL,'Then examine how the selected receiving degree uses that exact source course. A legitimate credit-bearing result still needs the supported university award and degree placement. Keep the course in My courses, select it only for an applicable row, and leave its status unfinished until the provider’s credit-bearing requirements are complete. This lets you benefit from low-cost preparation while keeping the degree progress based on actual original records and supported allocations.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-30703a31c67e44534779' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-323a755ac6d4cc9bf575','ds-guide-military','school:general','question','Can I choose a degree that survives another military move?','Example situation: I am a military spouse and expect to move again before finishing a degree. I would like a program that fits our location changes, but I also care about local support and might want a licensed career later. I have college courses from two previous duty stations. How can I build around those records and avoid choosing a program that only works while we live in one state?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-323a755ac6d4cc9bf575-guide-1','ds-guide-planning','post:ds-starter-323a755ac6d4cc9bf575',NULL,'Prepared guide answer: Import the original college records into My courses, then compare programs by delivery format and the career outcome you want. Location flexibility is important, but an online label does not resolve every placement, residency, or professional requirement. If the degree leads toward a licensed role, keep the intended practice location visible. Your spouse’s service context does not automatically turn your own record into military training credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-323a755ac6d4cc9bf575' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-323a755ac6d4cc9bf575-guide-2','ds-guide-military','post:ds-starter-323a755ac6d4cc9bf575',NULL,'Prepared guide answer: Choose a route with a clear plan for the university work that remains after transfer. If a program includes practical placements or in-person assessments, note where and when they happen before relying on relocation flexibility. Keep each institution’s original course facts intact so a future move does not require rebuilding your inventory. A useful comparison is how each route handles your likely next location, not just your current address.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-323a755ac6d4cc9bf575' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3294f9b14b1685e56622','ds-guide-planning','school:liberty','question','An older Liberty spreadsheet looks easier. Which version should I use?','Example situation: I found a shared Liberty spreadsheet with fewer required courses than the current plan. It looks helpful, but I cannot tell whether it applies to a new student or someone admitted years ago. Can I use the cheaper looking version as my starting point? I want to learn from community plans without accidentally building around requirements that do not govern my degree.','https://degreesteps.com/degree-plans/liberty-criminal-justice-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3294f9b14b1685e56622-guide-1','ds-guide-transfers','post:ds-starter-3294f9b14b1685e56622',NULL,'Use the catalog and program version that actually applies to your admission situation. An older spreadsheet is a lead for finding course options, not evidence that its requirements still govern a new student. Compare the degree title, format, concentration, and effective catalog first. Then carry forward only the outside matches supported for the exact current requirements, keeping their source versions and dates intact.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3294f9b14b1685e56622' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3294f9b14b1685e56622-guide-2','ds-guide-planning','post:ds-starter-3294f9b14b1685e56622',NULL,'If you are already enrolled under an earlier catalog, preserve that fact rather than automatically switching to the newest public plan. The useful comparison is between the rules you can actually use, including any conditions on changing catalogs. Community spreadsheets can reveal good questions and overlooked sources, but the plan should explain which version it represents so a simpler looking historical route does not become an expensive detour.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3294f9b14b1685e56622' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-32c8b1b392630bcf5309','ds-guide-planning','school:tesu','question','How should I compare IB credit when schools use different exam rules?','Example situation: I’m exploring degrees with International Baccalaureate coursework in my background. The course names sound familiar, but I understand the exam subject, level and score can matter when a college evaluates credit. What should I preserve in my records before comparing schools? I want to avoid treating every course called history or mathematics as the same award, especially when one institution might apply an exam to general education and another might have a different policy for that level.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-32c8b1b392630bcf5309-guide-1','ds-guide-courses','post:ds-starter-32c8b1b392630bcf5309',NULL,'Keep the exact IB subject, examination level, score and date from the official record. Higher Level and Standard Level are distinct details, and the receiving school’s published policy determines the relevant threshold and award. Do not replace those original facts with a guessed generic course grade or credit amount. If you already have a college evaluation, retain it as that institution’s result and keep the underlying exam record available for another school’s review.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-32c8b1b392630bcf5309' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-32c8b1b392630bcf5309-guide-2','ds-guide-transfers','post:ds-starter-32c8b1b392630bcf5309',NULL,'Compare the resulting award with the actual degree requirements before selecting additional outside coursework. A policy that grants credit does not necessarily establish a major prerequisite, laboratory condition or every general education placement you hoped to fill. Keep unsupported possibilities outside the completed total while identifying the remaining supported route. That gives you a clearer view of what to take next and reduces unnecessary repeats without assuming identical exam treatment across institutions.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-32c8b1b392630bcf5309' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-370976ffd3d90e116c47','ds-guide-planning','school:general','question','My newest transcript says 45 transfer credits. Why is that not enough detail?','Example situation: I finished courses at two community colleges, then moved to a university that lists them as one transfer total. I have the university transcript and hoped that its 45-credit summary would be enough to build my next degree. I do not want to request more documents unnecessarily. What useful information is missing from that total, and how can I avoid counting the same courses twice?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-370976ffd3d90e116c47-guide-1','ds-guide-transfers','post:ds-starter-370976ffd3d90e116c47',NULL,'Prepared guide answer: A summary tells you that a previous school accepted some learning, but not which original courses, grades, dates, and units a new degree can use. Import original course records when you can. A receiving-school award should remain a separate evaluation, rather than becoming a new original course. This preserves the information needed to compare another university without treating the previous transfer total as universally applicable credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-370976ffd3d90e116c47' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-370976ffd3d90e116c47-guide-2','ds-guide-planning','post:ds-starter-370976ffd3d90e116c47',NULL,'Prepared guide answer: Start by finding the oldest original transcript for each course, then review duplicates in My courses before using the collection in a plan. You can keep the later university’s evaluation as context, but do not add its total on top of the source courses. That way, the comparison reflects the learning you actually completed instead of producing a larger number every time a course appears on another transcript.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-370976ffd3d90e116c47' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-37142962c51e1442403e','ds-guide-planning','course:dsst-plan-dant0066','question','Can a DSST exam satisfy an upper-level requirement at one college but not another?','Example situation: I’m considering Organizational Behavior and see discussions about exams being used for upper-level requirements. My possible colleges have different course numbers and degree structures, so I’m hesitant to transfer that assumption from one school to another. How should I compare the exam’s original recommendation with each school’s award? I want to see whether the exam fills a required course, an elective or an advanced-credit minimum without inventing a universal upper-level classification for it.','https://degreesteps.com/courses.html?provider=DSST',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-37142962c51e1442403e-guide-1','ds-guide-courses','post:ds-starter-37142962c51e1442403e',NULL,'Keep the exact exam recommendation and the receiving-school award distinct. The school controls how an accepted examination applies to its own course catalog and degree requirements. A statement about upper-level use at one institution is not an award for another institution. Open each degree’s supported exam placement and inspect the resulting course and level, rather than using the source name or an online report as a universal level rule.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-37142962c51e1442403e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-37142962c51e1442403e-guide-2','ds-guide-transfers','post:ds-starter-37142962c51e1442403e',NULL,'Compare the remaining major and upper-level requirements after the exam is allocated. A course award may be useful even when it does not satisfy every advanced-credit condition you hoped to meet. Preserve the original exam score and date so a second plan can evaluate the same evidence. Your goal is a valid complete degree route, which may include both low-cost exam credit and specific university coursework needed for the remaining requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-37142962c51e1442403e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3726d0a46bedbb04d5a5','ds-guide-planning','course:christianleadersinstitute-plan-the210','question','How should I read accreditation and candidate-status language on a course source?','Example situation: I’m comparing religious-studies course sources and see different phrases about accreditation, candidacy and credit recommendations. They seem easy to blur together, especially when the receiving school has its own evaluation process. What should I pay attention to before treating a course as an institutional transfer option? I want the plan to describe the actual source status and record route accurately, without upgrading candidate status into full accreditation or assuming that a recommendation is itself college accreditation.','https://degreesteps.com/courses.html?provider=Christian%20Leaders%20Institute',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3726d0a46bedbb04d5a5-guide-1','ds-guide-courses','post:ds-starter-3726d0a46bedbb04d5a5',NULL,'Read the status attached to the actual issuing institution and the date of that evidence. The current Christian Leaders directory entry identifies candidate or pre-accreditation status; it should not be described as full regional accreditation. ACE and NCCRS, where applicable to a source, recommend credit for learning rather than accredit a university. Keep these categories separate so the source description accurately explains what kind of record is available for the receiving school to evaluate.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3726d0a46bedbb04d5a5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3726d0a46bedbb04d5a5-guide-2','ds-guide-transfers','post:ds-starter-3726d0a46bedbb04d5a5',NULL,'Then use the receiving institution’s exact published award or evaluation for your chosen degree. A source can have a particular documented transfer route without that result becoming a general guarantee at other colleges. Keep the issuer, original course and record pathway with your selection. This supports a clear degree plan while avoiding a misleading provider-wide badge that suggests every course, transcript type or school is covered by the same academic acceptance.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3726d0a46bedbb04d5a5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3a3592ef0dae6def9ecd','ds-guide-planning','school:general','question','My promotion requires a bachelor’s, not a particular major. How should I choose?','Example situation: My employer has said a bachelor’s degree would make me eligible to apply for a management role, but they did not name a subject. I have years of work experience and about a year of old college coursework. I want a sensible, affordable route without choosing a degree solely because someone online called it easy. What should I compare when the immediate goal is a credential for work?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3a3592ef0dae6def9ecd-guide-1','ds-guide-planning','post:ds-starter-3a3592ef0dae6def9ecd',NULL,'Prepared guide answer: Use Find a degree to compare routes that fit your work goals, study preferences, and existing courses. Bring the original college records into My courses so the comparison reflects what you have actually finished. Then look at remaining university requirements, total cost assumptions, and scheduling. A degree with a generous transfer allowance can still require specialized work that changes its practical fit for you.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3a3592ef0dae6def9ecd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3a3592ef0dae6def9ecd-guide-2','ds-guide-careers','post:ds-starter-3a3592ef0dae6def9ecd',NULL,'Prepared guide answer: Get the employer’s requirement in writing before narrowing the choice: degree level, recognized institution, any subject limits, and the timing of the promotion cycle. That is a concrete employment requirement, not a transfer-credit question. Choose a route you could explain in an interview and sustain alongside your job. Work experience may improve readiness, but credit for experience needs its own supported evaluation route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3a3592ef0dae6def9ecd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3aa5bd48025fadfb3712','ds-guide-planning','school:general','question','Do I need a particular bachelor’s major if my long-term goal is law school?','Example situation: I want to become a lawyer eventually, but I am starting with a limited budget and no college courses. I have heard conflicting advice about majoring in criminal justice, political science, or something completely different. I would like an accelerated bachelor’s route while keeping law school options open. What should I treat as an actual admission requirement, and what is just a suggested path?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3aa5bd48025fadfb3712-guide-1','ds-guide-careers','post:ds-starter-3aa5bd48025fadfb3712',NULL,'Prepared guide answer: Begin with a bachelor’s degree you can complete well and connect it to specific law schools you might consider. Record their published admission requirements separately from the undergraduate degree requirements. A major title is not evidence that a route meets every future admission or licensing condition. In Find a degree, compare subject fit and remaining work alongside cost, rather than assuming a degree labeled prelaw is mandatory.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3aa5bd48025fadfb3712' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3aa5bd48025fadfb3712-guide-2','ds-guide-courses','post:ds-starter-3aa5bd48025fadfb3712',NULL,'Prepared guide answer: Writing, reading, and sustained academic performance are practical preparation goals you can consider when choosing courses, even where a particular major is not prescribed. Keep law-school admission, the bachelor’s degree, and later professional licensing as separate stages. Build the undergraduate plan around documented course placements, then keep a short next-stage checklist. That makes acceleration a purposeful choice without pretending that finishing a degree guarantees entry into the profession.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3aa5bd48025fadfb3712' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3b18629e4b702577024e','ds-guide-planning','course:sophia-2572898d05a607b7c4','question','Should I choose Business Law because it is self-paced or because it fills my business core?','Example situation: I’m choosing business courses for a flexible bachelor’s plan and would prefer to avoid scheduled classes. Business Law appears in the course library, but I’m not sure whether it would replace a required business course or only count as an elective. What should I compare before choosing it over a similar option elsewhere? I want the learning format to fit my life while still making the strongest progress toward the actual degree.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3b18629e4b702577024e-guide-1','ds-guide-courses','post:ds-starter-3b18629e4b702577024e',NULL,'Start with the requirement that creates the most useful placement. A source course that fills a required business-core row can be more valuable to your current plan than one that fits only an elective. After locating the supported placement, compare pace, assessment format and eligible costs among its alternatives. A self-paced label describes the offering; the receiving-course evidence determines where that completed learning can be applied in the degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3b18629e4b702577024e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3b18629e4b702577024e-guide-2','ds-guide-transfers','post:ds-starter-3b18629e4b702577024e',NULL,'Check the minimum passing conditions shown for both the source and the receiving school. Passing a provider’s course and meeting a particular college’s transfer threshold are separate requirements. Keep the current course identity and effective dates with your selected option, especially if you might start later. Your plan should show that precise choice in the business row, leaving other saved alternatives available for comparison instead of treating them as additional completed requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3b18629e4b702577024e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3bef6280c219a0493f02','ds-guide-planning','school:wgu','question','Can I filter outside courses by no proctor without assuming WGU works the same way?','Example situation: I prefer self paced outside courses without proctored exams and want to use that preference when building a WGU route. Does that mean I should avoid every program with exams, or can I make sensible choices for the transfer portion? I need a plan that respects my study preferences while being honest about the assessments in the university coursework that remains.','https://degreesteps.com/degree-plans/wgu-communications/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3bef6280c219a0493f02-guide-1','ds-guide-courses','post:ds-starter-3bef6280c219a0493f02',NULL,'Keep the outside course preferences separate from the destination degree''s assessment obligations. Self paced is not a synonym for no proctor, and providers can differ by course. A reviewed UPI course, for instance, can be self paced and still require a remotely proctored final. Use exact course assessment evidence where available, and do not label the whole WGU degree based on the format of one outside option.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3bef6280c219a0493f02' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3bef6280c219a0493f02-guide-2','ds-guide-momentum','post:ds-starter-3bef6280c219a0493f02',NULL,'Choose compatible outside matches first, then review the remaining university work as its own decision. If a required assessment format is difficult for you, identify that early and explore legitimate support or a better fitting route rather than hiding it behind transfer savings. Your preferences can improve the basket even when they cannot remove every assessment tradeoff. The goal is a degree plan you can follow, not a label that sounds reassuring.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3bef6280c219a0493f02' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3d3a29bcf8984b63d6cf','ds-guide-military','school:general','question','I have military education. Do I start with JST, CCAF, or my college transcript?','Example situation: I served in the military and also took some college courses during that time. I have seen people mention JST and CCAF, but I am not sure which record applies to my service or whether I need more than one document. I want to compare bachelor’s options without treating every training recommendation as already awarded college credit. What should my first collection of records look like?','https://degreesteps.com/guides/military-credit-jst-ccaf/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3d3a29bcf8984b63d6cf-guide-1','ds-guide-military','post:ds-starter-3d3a29bcf8984b63d6cf',NULL,'Prepared guide answer: Begin with the record appropriate to your service and education, plus original transcripts for separate college coursework. The military-credit guide distinguishes JST recommendations from Air University and CCAF transcript records. Keep the issuing organization, dates, and units intact when organizing the collection. A recommended training credit and an institutional course award are different facts, so neither should be relabeled just to make the degree total larger.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3d3a29bcf8984b63d6cf' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3d3a29bcf8984b63d6cf-guide-2','ds-guide-transfers','post:ds-starter-3d3a29bcf8984b63d6cf',NULL,'Prepared guide answer: After the records are organized, compare exact degree requirements rather than expecting one automatic military credit total at every school. Training may help with particular requirements or electives, while major and residency rules still shape the remaining work. Keep benefit eligibility on a separate checklist from academic applicability. Your next step is a clean record inventory that can be reused across comparisons, not manually entering a guessed service-credit number.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3d3a29bcf8984b63d6cf' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3d403cb4d4564256047c','ds-guide-planning','course:sophia-98ef0b7336b70b93f8','question','My degree offers a math choice. Should I pick statistics or algebra?','Example situation: I’m considering a business degree and a social science degree, and both mention math in different ways. Statistics sounds more useful for the jobs I’m exploring, but algebra might keep more future programs open. If I only want to pay for one course now, how should I compare the options? I’d like to see which requirement each course fills before choosing, rather than treating all three-credit math courses as interchangeable.','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3d403cb4d4564256047c-guide-1','ds-guide-courses','post:ds-starter-3d403cb4d4564256047c',NULL,'Save the statistics course and the algebra course, then compare them against the actual degrees you are considering. Look for a named match, an allowed math-choice block, or an elective placement. Those results can differ even at the same school. If one course satisfies a required row in both degrees, it may preserve more options. Use your career interest as another preference after you understand the supported academic placements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3d403cb4d4564256047c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3d403cb4d4564256047c-guide-2','ds-guide-transfers','post:ds-starter-3d403cb4d4564256047c',NULL,'Keep a short note explaining why you selected your first math course. If you later change majors, the original course stays in your collection and its applicability is recalculated for the new plan. A statistics course that fills an elective in one degree has not disappeared, but it may not replace that degree’s algebra requirement. Comparing those consequences now is more useful than choosing solely from a general difficulty ranking.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3d403cb4d4564256047c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3e251c4d321a8ee7d945','ds-guide-planning','school:general','question','Can I prioritize courses without remote proctoring and still compare worthwhile degrees?','Example situation: I am uncomfortable installing monitoring software on my personal computer and would prefer coursework without remote proctored exams. I am happy to complete writing, projects, or other assessments, so I am not looking for credit without doing the work. How should I use that preference in a degree plan without assuming that self-paced courses, every provider, or the university itself will all have the same assessment rules?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3e251c4d321a8ee7d945-guide-1','ds-guide-courses','post:ds-starter-3e251c4d321a8ee7d945',NULL,'Prepared guide answer: Use the course library’s assessment information alongside provider, subject, and pace. Self-paced and unproctored describe different things, and a provider may use different assessment formats for different courses. Save options that fit your preference, then compare their actual degree use. The receiving university’s own coursework remains a separate part of the route, so avoiding proctoring in transfer courses does not establish the assessment format of the entire degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3e251c4d321a8ee7d945' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3e251c4d321a8ee7d945-guide-2','ds-guide-planning','post:ds-starter-3e251c4d321a8ee7d945',NULL,'Prepared guide answer: Before buying a course, look at its specific assessment conditions rather than relying on a general provider label or a forum memory. Writing-based options may involve substantial assignments, grading time, and revisions. Keep those demands in your time comparison. If a particular requirement has no supported unproctored option, leave that tradeoff visible and compare another eligible course or degree route instead of pretending the requirement disappears.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3e251c4d321a8ee7d945' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-3e66e8689d6f829e470c','ds-guide-planning','school:general','question','What if I want a bachelor’s degree but genuinely do not know my major?','Example situation: I left high school expecting to work, and I am now ready to consider college. I do not have a dream major or a particular university in mind. Cost, flexibility, and a degree employers recognize matter more to me than a specialized subject right now. I worry that choosing the wrong major will lead to wasted courses. How do I begin without pretending I have a career plan?','https://degreesteps.com/start.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3e66e8689d6f829e470c-guide-1','ds-guide-planning','post:ds-starter-3e66e8689d6f829e470c',NULL,'Prepared guide answer: The guided setup lets you begin from your goals instead of requiring a school choice first. Describe the study format and tradeoffs that matter to you, then compare a few available degree plans. Look at what each degree prepares you for and what university work remains. A general goal is useful information, but it should not cause every degree title to be treated as equally suitable.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3e66e8689d6f829e470c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-3e66e8689d6f829e470c-guide-2','ds-guide-courses','post:ds-starter-3e66e8689d6f829e470c',NULL,'Prepared guide answer: Before buying a broad set of courses, choose one or two plausible targets and see which requirements genuinely overlap. Start with a course that has documented use in those routes and matches your interests or existing strengths. Keep room to change your mind. You can explore the course library without marking anything earned or committing to a full membership schedule before the degree choice becomes clearer.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-3e66e8689d6f829e470c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-41844506b9fdbc8ab222','ds-guide-planning','school:tesu','question','Do older accounting credits need different treatment from my general education?','Example situation: I completed accounting courses years ago and am thinking about finishing a TESU accounting bachelor degree. Some of my general education credits are old too. Should I treat the entire transcript as expired, or do the time limits depend on the requirement? I need a practical way to separate useful existing work from subjects that might need a current replacement.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-accounting/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-41844506b9fdbc8ab222-guide-1','ds-guide-transfers','post:ds-starter-41844506b9fdbc8ab222',NULL,'Do not discard the whole transcript because of its age. The reviewed accounting model identifies a specific currency rule for the accounting area: a ten year window with up to nine older credits within the eighteen credit area. It separately identifies a five year business capstone rule. Those constraints apply to their named groups; they are not a blanket expiration rule for every course on your record.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-41844506b9fdbc8ab222' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-41844506b9fdbc8ab222-guide-2','ds-guide-careers','post:ds-starter-41844506b9fdbc8ab222',NULL,'Keep completion dates alongside original course codes when importing your records. Audit general education and the accounting area separately, then prioritize current replacements only where the actual rule requires them. This makes the next conversation precise and avoids repeating useful work unnecessarily. Also keep the standard accounting degree distinct from the Accounting/CPA option; a degree title alone does not establish eligibility for a particular state''s professional licensing requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-41844506b9fdbc8ab222' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-424beb702102fb7132f5','ds-guide-planning','school:tesu','question','Can I leave the TESU university requirements until the very end?','Example situation: I want to complete as much inexpensive outside work as possible before paying university tuition. Is it safe to assume the remaining TESU courses can all be taken together at the end? I am especially unsure about the Cornerstone and capstone. I need a sequence that preserves the savings without creating a final term I cannot actually complete as planned.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-accounting/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-424beb702102fb7132f5-guide-1','ds-guide-planning','post:ds-starter-424beb702102fb7132f5',NULL,'Keep university only rows visible from the beginning. The reviewed models retain SOS-1100 Cornerstone and the capstone as institution coursework, rather than substituting an outside course with a similar subject. Their presence is one reason the institutional minimum cannot describe the entire schedule by itself. A course list also needs the applicable sequence and eligibility conditions before it can become a realistic final term plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-424beb702102fb7132f5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-424beb702102fb7132f5-guide-2','ds-guide-money','post:ds-starter-424beb702102fb7132f5',NULL,'Plan backward from the remaining university work, then fit outside courses into the time before those obligations. If a required step has to happen earlier, it belongs on the checklist now instead of becoming a surprise at the end. Use a feasible term load in the tuition range. A final term that looks cheap only because it ignores sequencing can delay completion and cost more than the planned saving.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-424beb702102fb7132f5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-42bedeead4fd49bcef22','ds-guide-planning','school:wgu','question','Do older technology courses count the same as recent WGU transfer options?','Example situation: I completed technology courses several years ago and am returning to college after working in the field. Some of that knowledge is still useful, but I know technology changes quickly. How should the plan handle course age? I do not want to assume my entire transcript is obsolete, or count an old technical course as accepted simply because its title resembles a current WGU requirement.','https://degreesteps.com/degree-plans/wgu-cybersecurity-and-information-assurance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-42bedeead4fd49bcef22-guide-1','ds-guide-transfers','post:ds-starter-42bedeead4fd49bcef22',NULL,'Retain completion dates and the exact original course identity. The reviewed WGU technology transfer material includes course specific recency requirements, so the relevant subject and receiving rule matter. A five year rule where stated should not be generalized to every course in the degree. General education, current certifications, and particular technical courses need their own applicable evidence rather than one blanket decision about the age of the entire transcript.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-42bedeead4fd49bcef22' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-42bedeead4fd49bcef22-guide-2','ds-guide-planning','post:ds-starter-42bedeead4fd49bcef22',NULL,'Audit what remains useful before choosing replacement study. A technical subject may need current coursework while another original course still has a valid place. Keep the career value of your experience separate from the academic award; the plan can respect both without assuming they are identical. If a replacement is needed, compare exact supported current options for that requirement instead of automatically repeating the same subject through the first provider you recognize.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-42bedeead4fd49bcef22' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-431477762a6192ab5712','ds-guide-planning','school:liberty','question','Which courses make sense before I choose a Liberty major?','Example situation: I know I want Liberty, but I am deciding between business and criminal justice. I would like to start inexpensive courses while I think about careers. Which classes should go first so I do not fill my saved list with electives that only work for one degree? I would rather make steady progress than commit to the wrong major too early.','https://degreesteps.com/degree-plans/liberty-business-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-431477762a6192ab5712-guide-1','ds-guide-transfers','post:ds-starter-431477762a6192ab5712',NULL,'Compare the two exact degree worksheets before choosing a provider. Look for a remaining requirement that appears in both plans and has a supported outside match in each. English or another general education subject is a good place to look, but the subject name alone is not evidence of a shared match. Keep the destination requirement and course version attached to each candidate.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-431477762a6192ab5712' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-431477762a6192ab5712-guide-2','ds-guide-careers','post:ds-starter-431477762a6192ab5712',NULL,'Make a small first basket rather than buying a year of courses. Choose the overlap you can explain clearly, then leave major electives until your direction is firmer. A useful comparison shows what changes when you switch: courses still used, courses that become electives, and courses left outside the degree. That is more useful than chasing the largest possible transfer count today.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-431477762a6192ab5712' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-44ca819144e71f145bce','ds-guide-planning','school:liberty','question','Can an outside Bible course satisfy a Liberty religion requirement?','Example situation: I’m considering a Liberty degree and would like to understand the outside options for religion requirements. A Bible course sounds relevant, but different degree plans may require a particular survey, theology or other religious-studies course. How should I compare a Christian Leaders option with the exact Liberty row? I want to find legitimate transfer opportunities without assuming that every Christian course satisfies every religion requirement simply because the subjects share a broad religious theme.','https://degreesteps.com/courses.html?provider=Christian%20Leaders%20Institute',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-44ca819144e71f145bce-guide-1','ds-guide-courses','post:ds-starter-44ca819144e71f145bce',NULL,'Match the specific original course to the exact receiving award and degree requirement. Old Testament survey, theology and evangelism are different subjects even when they come from the same provider. Use the named option supported in the selected Liberty program and delivery format. A general statement that religious courses may transfer does not establish a replacement for an unrelated required course, and source completion requirements remain part of the route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-44ca819144e71f145bce' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-44ca819144e71f145bce-guide-2','ds-guide-transfers','post:ds-starter-44ca819144e71f145bce',NULL,'Keep the course’s actual issuer and transcript pathway visible alongside the placement. That helps distinguish a legitimate institution-issued record from informal learning or a general completion certificate. The plan should show the outside choice only in the supported row and keep any university-only requirements intact. If you switch majors or change from online to residential study, review the allocation again while retaining the same original source record and completion details.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-44ca819144e71f145bce' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-44ec8742341ed1e06608','ds-guide-campus','school:general','question','Could taking outside courses make a local campus degree practical for someone who works?','Example situation: I live near a university and would enjoy attending in person, but I work during the day and cannot afford several years of full-time commuting. I have some old general education credits and could study online for other eligible courses. How should I compare a campus route with an online degree without assuming that choosing transfer courses also solves the campus course schedule?','https://degreesteps.com/campuses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-44ec8742341ed1e06608-guide-1','ds-guide-campus','post:ds-starter-44ec8742341ed1e06608',NULL,'Prepared guide answer: Use Find a campus to identify schools that fit your location, then connect that shortlist to exact degree requirements. Bring your existing records into My courses and inspect supported outside-course options for the chosen program. Keep the university schedule as a separate part of the plan. Transfer credits can reduce remaining requirements, but they do not create evening sections or remove an in-person requirement automatically.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-44ec8742341ed1e06608' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-44ec8742341ed1e06608-guide-2','ds-guide-planning','post:ds-starter-44ec8742341ed1e06608',NULL,'Prepared guide answer: Compare travel time, parking, required days on campus, and the sequence of courses still taught by the university. A route with fewer remaining credits can still take longer if a needed class is offered infrequently or conflicts with work. Your best first step is identifying the remaining campus commitments that would affect your job, then choosing outside courses that have a documented place in that degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-44ec8742341ed1e06608' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-482fb22cd1842bc46010','ds-guide-planning','school:wgu','question','Should I choose the WGU provider with the most matches?','Example situation: I see useful WGU courses from Study.com, Sophia, StraighterLine, and Saylor. It would be convenient to use just one provider, but I worry that I might miss faster or less expensive options elsewhere. Should I choose the provider with the biggest list of matches, or mix them? I need a plan that makes the practical tradeoffs clear without making me manage four memberships at once.','https://degreesteps.com/degree-plans/wgu-supply-chain-and-operations-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-482fb22cd1842bc46010-guide-1','ds-guide-courses','post:ds-starter-482fb22cd1842bc46010',NULL,'Start with your open requirements and compare the exact supported options attached to them. A large provider catalog is not the same as the best basket for this degree. Consider assessment format, workload, source version, original credits, and total billing cost. Mixing sources can be useful when each course fills a distinct requirement, but the combined plan must still respect duplication rules and the degree''s transfer and university coursework constraints.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-482fb22cd1842bc46010' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-482fb22cd1842bc46010-guide-2','ds-guide-money','post:ds-starter-482fb22cd1842bc46010',NULL,'Group the selected courses into a manageable sequence before paying. One provider first and another later may fit your budget better than simultaneous subscriptions, while a course bundle or required sequence needs to remain intact. Keep unselected alternatives available without treating them as purchases. The best result is a small, understandable basket that finishes real requirements, with the reason for each provider choice visible in the plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-482fb22cd1842bc46010' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-48e764599e6e53af9155','ds-guide-planning','school:tesu','question','If I pass an outside course, can a university still require a different result?','Example situation: I’m comparing outside courses and notice that a provider’s passing rule and a college’s transfer-grade language may not be identical. How should I plan around that difference? I want to finish efficiently, but I don’t want to assume that a passing source result automatically meets every school or major’s standard. I’m also unsure how to record an original score or grade without changing it to match the receiving degree’s preferred threshold.','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-48e764599e6e53af9155-guide-1','ds-guide-courses','post:ds-starter-48e764599e6e53af9155',NULL,'Preserve the actual result issued by the source. Its passing condition establishes source completion, while the receiving school can apply a separate supported threshold or program condition. The degree matcher should evaluate both instead of upgrading a grade or score. Read the exact source and receiving evidence associated with your selected option, including any professional, major-specific or course-recency requirement that affects whether that completed learning can be applied.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-48e764599e6e53af9155' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-48e764599e6e53af9155-guide-2','ds-guide-transfers','post:ds-starter-48e764599e6e53af9155',NULL,'If your result does not meet a receiving condition, keep the completed course in your history and compare legitimate alternatives for the open requirement. A different degree might apply a different published policy, but that does not change the original grade. Review the remaining courses, cost and time for each supported route before deciding on a repeat or replacement. This turns a disappointing mismatch into a concrete planning choice without concealing the academic record.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-48e764599e6e53af9155' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-497aa0f19d0c4d35bf3d','ds-guide-planning','school:general','question','Can I build a degree around school pickup instead of a fixed class schedule?','Example situation: I have two children in elementary school and a dependable study window from nine until noon on three weekdays. Evening classes would mean paying for childcare, which could erase the savings. I am starting without college courses and do not know my major yet. How would I compare a flexible online route with a nearby college without committing to an unrealistic full-time schedule?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-497aa0f19d0c4d35bf3d-guide-1','ds-guide-planning','post:ds-starter-497aa0f19d0c4d35bf3d',NULL,'Prepared guide answer: Open Find a degree and begin with your goal and preferred study format. Compare self-paced options with programs that have scheduled terms, then open a plan and look at the actual work remaining at the university. Self-paced outside courses can help with your mornings, but they do not make every later university course flexible. Keep that difference visible before choosing a school.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-497aa0f19d0c4d35bf3d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-497aa0f19d0c4d35bf3d-guide-2','ds-guide-momentum','post:ds-starter-497aa0f19d0c4d35bf3d',NULL,'Prepared guide answer: Plan your first month around the hours you already have, rather than the fastest completion story you have seen. One course can show whether assignments, grading, and interruptions fit those mornings. Keep a backup week for school holidays or illness. The useful milestone is finishing a manageable first course that fits your chosen degree, while keeping childcare costs inside your real budget.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-497aa0f19d0c4d35bf3d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-49d97a887e118f8671aa','ds-guide-planning','school:general','question','I work nights at a hospital. Can an online plan really fit that?','Example situation: I work three overnight shifts a week at a hospital, then need recovery time before I can think clearly. I would like a business or health administration degree, not a clinical license. Live daytime classes are difficult, but I can often study on days off. How can I compare programs without accidentally choosing something with required meetings, clinical work, or frequent timed exams?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-49d97a887e118f8671aa-guide-1','ds-guide-planning','post:ds-starter-49d97a887e118f8671aa',NULL,'Prepared guide answer: Begin in Find a degree with online study and the field you are considering. Use pace and assessment information to narrow the choices, then inspect the degree plan’s university work as carefully as its transfer courses. A health administration degree and a clinical health qualification have different purposes. Pick the exact outcome first so an appealing title does not pull you into unrelated requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-49d97a887e118f8671aa' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-49d97a887e118f8671aa-guide-2','ds-guide-careers','post:ds-starter-49d97a887e118f8671aa',NULL,'Prepared guide answer: Place demanding writing or exams on rested days instead of treating hours after a shift as normal study time. Compare a realistic number of courses per paid period, including time for feedback and revisions. Your hospital job may provide useful context for assignments, but experience does not automatically award credit. Keep employment knowledge, completed courses, and proposed coursework as separate parts of the plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-49d97a887e118f8671aa' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-4ee7b84c3f99c60b39e9','ds-guide-planning','school:wgu','question','Does prior WGU coursework automatically satisfy active program residency when I return?','Example situation: I previously studied at WGU and am thinking about returning in a different degree. I want to preserve useful completed work, but I am unsure whether those old WGU courses count as transfer, current program work, or both. How should I compare the new route? I do not want to start over unnecessarily or assume that the university name on the record satisfies every remaining institutional rule.','https://degreesteps.com/degree-plans/wgu-business-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-4ee7b84c3f99c60b39e9-guide-1','ds-guide-transfers','post:ds-starter-4ee7b84c3f99c60b39e9',NULL,'Preserve the original WGU record and evaluate its use in the new exact program. The reviewed residency rule focuses on credit earned within the active program; prior WGU coursework is not automatically counted as current program residency. Any handbook defined exception needs its own applicability. That is different from deciding whether a prior course can satisfy a named academic requirement, so the plan should not collapse those two questions into one label.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-4ee7b84c3f99c60b39e9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-4ee7b84c3f99c60b39e9-guide-2','ds-guide-planning','post:ds-starter-4ee7b84c3f99c60b39e9',NULL,'Compare the remaining requirements and institution obligations after the prior record is evaluated under the applicable rules. Do not mark older coursework as newly completed active program study just to make the residency percentage work. Keep any required capstone separate where the current curriculum requires it. This gives a returning student credit for legitimate prior work while preserving a realistic view of what must still be completed in the chosen program.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-4ee7b84c3f99c60b39e9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-4eeff85cab24ea1ee37c','ds-guide-planning','school:general','question','Can I share my degree plan with the community without posting my transcript?','Example situation: I would like feedback on the outside courses I chose and might turn the plan into a useful starting point for someone else. My private course collection includes older transcripts and notes that I do not want to publish. I also do not want another student to assume my proposed choices are official approvals. What belongs in a shared plan, and what should stay in my account?','https://degreesteps.com/community.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-4eeff85cab24ea1ee37c-guide-1','ds-guide-planning','post:ds-starter-4eeff85cab24ea1ee37c',NULL,'Prepared guide answer: Share the proposed degree structure, course choices, exact school and catalog, and the specific question you want help with. Keep personal transcripts, student numbers, addresses, identity documents, private notes, and other people’s records out of the discussion. A reusable plan can explain which requirement a course is intended to satisfy without publishing your original file. Clearly label proposed choices separately from an individual receiving-school evaluation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-4eeff85cab24ea1ee37c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-4eeff85cab24ea1ee37c-guide-2','ds-guide-transfers','post:ds-starter-4eeff85cab24ea1ee37c',NULL,'Prepared guide answer: Ask for feedback on a concrete decision, such as two documented alternatives for one requirement or the sequence of remaining university courses. Include relevant public source links and explain when the plan was reviewed. Community experience can reveal useful gaps, but another student’s outcome does not automatically establish your award. Keeping the public template separate from private records makes the conversation more useful and protects the next person from copying assumptions blindly.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-4eeff85cab24ea1ee37c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-5006ef986626fbd111b7','ds-guide-planning','school:liberty','question','What happens to my Liberty courses if I decide on another university?','Example situation: I like Liberty but am also considering a different university with a self paced program. I have saved a group of outside courses and may finish some before making the final school choice. How can I compare the alternatives without losing track of what I already did? I want the courses to remain my records even if the recommended degree changes.','https://degreesteps.com/degree-plans/liberty-psychology-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5006ef986626fbd111b7-guide-1','ds-guide-transfers','post:ds-starter-5006ef986626fbd111b7',NULL,'Treat your course collection as the input and each exact degree worksheet as a separate destination. Preserve completed source courses with their original identifiers and credits, then compare where each degree can use them. A Liberty match does not travel automatically to another university. The comparison should expose unused courses and different requirement placements rather than implying that every saved option works everywhere.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5006ef986626fbd111b7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5006ef986626fbd111b7-guide-2','ds-guide-money','post:ds-starter-5006ef986626fbd111b7',NULL,'While the school decision is open, prioritize a course only when it has supported applicability in the serious alternatives you are comparing. For already completed work, focus on how much remaining coursework each degree requires, not just how many credits it accepts. Include institutional coursework and the billing model in the cost comparison. That is how you protect your effort without letting one earlier choice control the entire degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5006ef986626fbd111b7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-509e24c62492338a4091','ds-guide-planning','school:general','question','A self-paced doctorate sounds appealing. What should I compare beyond the tuition?','Example situation: I have a master’s degree and am considering a professional doctorate while continuing to work. Subscription pricing and flexible pacing sound useful, but I do not want to underestimate the research or choose something that does not fit my intended role. What should a degree comparison include when the biggest work may be a project or dissertation rather than a list of transferable undergraduate courses?','https://degreesteps.com/blog/graduate-acceleration-is-different/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-509e24c62492338a4091-guide-1','ds-guide-careers','post:ds-starter-509e24c62492338a4091',NULL,'Prepared guide answer: Start with the exact doctorate and the outcome you want from it. Identify admission prerequisites, the required research or final project, available supervision, assessment expectations, and the institution’s published pricing structure. Undergraduate transfer strategies should not be assumed to apply. A short advertised tuition period is not a promise about how long research will take, so keep academic milestones separate from a simple subscription-price calculation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-509e24c62492338a4091' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-509e24c62492338a4091-guide-2','ds-guide-money','post:ds-starter-509e24c62492338a4091',NULL,'Prepared guide answer: Compare how much guidance, feedback, library access, and other required support the program includes. Look at the cost if the final project takes additional billed periods, and consider whether the degree fits your employer or future academic goal. Use the official program link for a focused plan request. Your next action should resolve a meaningful research or admission question, not just identify the lowest monthly price.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-509e24c62492338a4091' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-514427be9f4dc2e71d80','ds-guide-careers','course:mapped-f41e3f4a4f9b304bff57','question','Can a practical Excel course help my career without replacing the exact business requirement?','Example situation: I’m considering Advanced Excel in Business because spreadsheet skills would help in the work I want to do. My degree also lists business technology requirements, but I’m not sure whether this course would satisfy one directly or count elsewhere. How should I balance useful skills with efficient degree progress? I’d like to see the actual academic placement and the remaining requirements without assuming that a relevant career skill automatically matches a particular university course or major requirement.','https://degreesteps.com/courses.html?provider=ASU%20Universal%20Learner',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-514427be9f4dc2e71d80-guide-1','ds-guide-courses','post:ds-starter-514427be9f4dc2e71d80',NULL,'Use the course’s supported receiving award to establish its degree placement, then evaluate its skills value as another benefit. A practical spreadsheet course may be useful professionally even when it does not replace a specific required business course. Keep the source level and the receiving classification separate, especially when comparing advanced-credit conditions. The plan should show the actual applicable row and any remaining university work so the career benefit does not hide an academic gap.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-514427be9f4dc2e71d80' AND p.user_id='ds-guide-careers' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-514427be9f4dc2e71d80-guide-2','ds-guide-careers','post:ds-starter-514427be9f4dc2e71d80',NULL,'Compare another relevant degree if you are still exploring. One program may use the course more directly, while another may allocate it within an elective block or leave it unused. Those outcomes help you decide whether to prioritize the course now, keep it saved for later, or choose another supported option first. Retain your notes about the skill goal so a later plan change considers both the academic route and the work you want to pursue.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-514427be9f4dc2e71d80' AND p.user_id='ds-guide-careers' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-529bc76fd96241dfef2d','ds-guide-planning','school:tesu','question','TESU lists UPI as an approved provider. Does that settle every course choice?','Example situation: I’m looking at UPI courses for a TESU degree and found UPI in the university’s approved provider directory. That seems encouraging, but I’m not sure how far the approval reaches. Does it establish the exact TESU course for every UPI offering, or do the individual course mappings still matter? I want to use the approval correctly while understanding which requirements the current plan can actually fill with the particular courses I am considering.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-529bc76fd96241dfef2d-guide-1','ds-guide-courses','post:ds-starter-529bc76fd96241dfef2d',NULL,'Provider approval and a receiving-course award are different facts. TESU’s directory establishes UPI’s provider status; it does not itself supply a complete table of course equivalencies. UPI’s TESU material distinguishes provider-recommended matches from claims described as university-verified. DegreeSteps needs the actual receiving evidence and the current degree requirement before treating either as a complete executable placement. The directory is useful context, not a blanket substitute for those course and degree facts.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-529bc76fd96241dfef2d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-529bc76fd96241dfef2d-guide-2','ds-guide-transfers','post:ds-starter-529bc76fd96241dfef2d',NULL,'Use the specific requirement row to make your course decision. Look for the original source identity, recommendation period, supported receiving course and any remaining conditions for that placement. A source option that is still conditional should remain described that way while research is completed. The same approved provider can offer useful courses that apply differently across majors, so your plan should optimize the supported placements rather than importing every catalog course into every degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-529bc76fd96241dfef2d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-53f2da56f73d28a27172','ds-guide-planning','school:general','question','Can low-cost online prerequisites shorten a nursing path without changing clinical requirements?','Example situation: I work as a care assistant and am considering nursing. I am attracted to inexpensive online science courses, but I am concerned about lab requirements and whether they would fit the nursing program I eventually choose. I cannot leave my job for a vague promise of a faster degree. How should I compare prerequisite savings while keeping admissions, clinical schedules, and the professional qualification in view?','https://degreesteps.com/request-plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-53f2da56f73d28a27172-guide-1','ds-guide-careers','post:ds-starter-53f2da56f73d28a27172',NULL,'Prepared guide answer: Start with the exact nursing program and intended professional outcome, then identify its required prerequisite courses and laboratory components. Build from a degree link can keep the research focused on that program rather than a generic science list. A lecture course, a lab, and a combined course are different records. A provider’s science category alone does not establish that it satisfies a nursing prerequisite or admission rule.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-53f2da56f73d28a27172' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-53f2da56f73d28a27172-guide-2','ds-guide-courses','post:ds-starter-53f2da56f73d28a27172',NULL,'Prepared guide answer: Place clinical schedules and any required in-person work on the same decision list as tuition and transfer credits. Those commitments may determine whether the program fits your job even when outside prerequisites are affordable. Keep the original course and lab details in My courses, and compare supported placements before buying a bundle. The goal is a workable nursing pathway, not merely collecting the largest number of low-cost science credits.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-53f2da56f73d28a27172' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-559caec8a39847ff4571','ds-guide-planning','course:mapped-aace83caff18b90ff4cd','question','Would taking the same introductory subject from two providers give me six credits?','Example situation: I’m comparing introductory psychology options and might save more than one provider’s course while deciding. If each listing describes three credits, does completing both give me six credits toward a degree? I understand there may be different lessons and assessments, but the courses could still become the same university requirement. I want to keep alternatives in my library without accidentally building a plan that counts the same introductory learning twice.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-559caec8a39847ff4571-guide-1','ds-guide-courses','post:ds-starter-559caec8a39847ff4571',NULL,'Save alternatives freely, then select the source you intend to use for the relevant requirement. The planner must check both the original course identity and the receiving award. Two different providers can lead to the same university course, in which case the second course may duplicate that credit. The credit shown on a source listing is not an instruction to add both amounts to the degree’s completed total.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-559caec8a39847ff4571' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-559caec8a39847ff4571-guide-2','ds-guide-transfers','post:ds-starter-559caec8a39847ff4571',NULL,'If you have already completed both courses, keep both original records instead of deleting history to make the plan look cleaner. The degree allocation should show which record is used and which remains unused or overlapping. That gives you an honest audit and protects your records when considering another program. A different degree might apply the learning differently, but a duplicate cannot be forced into an unrelated elective simply to increase progress.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-559caec8a39847ff4571' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-55b25fc60e7bb8ecf682','ds-guide-planning','course:saylor-plan-saya0005','question','How should I plan if an assessment needs another attempt?','Example situation: I’m considering an exam-based route for Microeconomics and want a realistic schedule. My first draft assumes I pass every required assessment on the first try, which may be too optimistic if I’m returning to school after a break. How should I account for another attempt without making the plan feel impossible? I’d like to see what happens to membership costs, transcript timing and the next eligible course if an assessment takes longer than I expect.','https://degreesteps.com/courses.html?provider=Saylor',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-55b25fc60e7bb8ecf682-guide-1','ds-guide-courses','post:ds-starter-55b25fc60e7bb8ecf682',NULL,'Keep the academic requirement and a realistic scheduling buffer separate. Read the exact course’s current retake conditions, attempt limits, waiting periods and any assessment charges before depending on a particular calendar date. Do not convert a general self-paced label into an assumption that another attempt is immediately available. Your plan can show other eligible work during a delay, provided that the unfinished course is not a prerequisite for that work.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-55b25fc60e7bb8ecf682' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-55b25fc60e7bb8ecf682-guide-2','ds-guide-momentum','post:ds-starter-55b25fc60e7bb8ecf682',NULL,'Use a second timing scenario rather than marking a course failed in advance. For example, compare your intended study schedule with a scenario that includes another permitted assessment attempt. Keep the additional time and charges as assumptions unless the provider’s terms establish them. If the course remains incomplete, leave it in progress and keep the receiving requirement open. A transparent buffer is more useful than a guaranteed finish date built on perfect first attempts.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-55b25fc60e7bb8ecf682' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-575cb614e2fd7e17e4ad','ds-guide-planning','school:tesu','question','When is an exam a better choice than a self paced course for TESU?','Example situation: I already know some of the introductory material in my TESU plan and have seen CLEP mentioned as an inexpensive shortcut. I also dislike high stakes exams and might prefer coursework. How should I compare those routes fairly? I do not want the plan to assume every student should test out of everything just because a single exam looks fast on a spreadsheet.','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-575cb614e2fd7e17e4ad-guide-1','ds-guide-courses','post:ds-starter-575cb614e2fd7e17e4ad',NULL,'First establish a usable placement for the exact exam or course in your degree. TESU''s current reviewed provider directory shows CLEP as provisional review pending, so a familiar exam name alone is not enough to present a receiving award as established. Where the evidence supports an option, compare the assessment format, preparation you actually need, scheduling, total charges, and your comfort with a single testing event.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-575cb614e2fd7e17e4ad' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-575cb614e2fd7e17e4ad-guide-2','ds-guide-momentum','post:ds-starter-575cb614e2fd7e17e4ad',NULL,'An exam can suit someone who already knows the content, while a course may suit someone who wants time to learn and demonstrate it through several assignments. Neither format is universally faster for the person taking it. Keep the preference in your plan, and do not pay for both routes to the same requirement without a reason. Progress comes from finishing useful work in a format you can sustain.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-575cb614e2fd7e17e4ad' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-589c4f181ae51204c958','ds-guide-planning','course:clep-c5e1b4829165978126','question','How do exam scores fit a plan that asks for course grades?','Example situation: I’m collecting records for a degree plan and notice that college courses usually have letter grades while CLEP results have scores. If a university says it requires a particular transfer grade, should I translate an exam score into a letter grade myself? I want to keep the records accurate while understanding how the school’s exam-credit policy fits alongside its ordinary course-transfer rules. I’m especially concerned about accidentally creating a grade that does not appear on the original report.','https://degreesteps.com/courses.html?provider=CLEP',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-589c4f181ae51204c958-guide-1','ds-guide-courses','post:ds-starter-589c4f181ae51204c958',NULL,'Keep an exam score as a score, with the exact exam identity and date. Do not invent a letter grade to make the record resemble a traditional course. The receiving school’s published exam-credit policy supplies the relevant threshold and award, which can differ from its ordinary transfer-course grade rule. Your original report and the resulting institutional evaluation should remain separate facts in the plan so each can be checked in the correct context.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-589c4f181ae51204c958' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-589c4f181ae51204c958-guide-2','ds-guide-transfers','post:ds-starter-589c4f181ae51204c958',NULL,'If the receiving college has already awarded course credit for the exam, add that evaluated award for the specific college while preserving the underlying score report. Another school may apply a different policy, and an exam award does not automatically carry the same GPA treatment as a graded course. Use the actual evaluation to understand degree progress and any remaining requirements rather than manufacturing a grade or assuming the award applies identically everywhere.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-589c4f181ae51204c958' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-58e610b38ae53526a09b','ds-guide-planning','school:umpi','question','Can a broad UMPI plan stay useful if my career goal changes?','Example situation: I am interested in a broad degree now, but my career plans may become more specific after I start studying. I want to avoid wasting courses if I later choose another minor or university. How should I organize a UMPI exploration so I can change direction intelligently? I do not want every new idea to make the work I have already completed feel like a mistake.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-58e610b38ae53526a09b-guide-1','ds-guide-careers','post:ds-starter-58e610b38ae53526a09b',NULL,'Keep the original course collection independent from the destination degree. A completed course remains part of your record even if a new plan uses it differently or not at all. Compare each exact program separately, preserving its source and requirement rules. A broad degree title can offer flexibility, but it does not establish that every future minor, major, or professional pathway can use the same basket without changes.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-58e610b38ae53526a09b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-58e610b38ae53526a09b-guide-2','ds-guide-planning','post:ds-starter-58e610b38ae53526a09b',NULL,'While your direction is open, look for supported overlap among the serious alternatives rather than buying courses for every possible future. For UMPI, the unresolved current map means that overlap still needs exact receiving evidence before it becomes a recommendation. As your goal sharpens, compare the additional work and the value of the new destination. A deliberate change can be worthwhile; the plan should make its consequences clear rather than penalize exploration.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-58e610b38ae53526a09b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-59424da4751266782e13','ds-guide-planning','school:wgu','question','Can an old WGU provider recommendation still justify taking the current course?','Example situation: A spreadsheet lists a provider course that matched WGU last year, but the course page now has a different version or description. The title is nearly identical, so I am tempted to assume the transfer advice still applies. How should the platform handle that change? I want to use community knowledge without relying on a historical recommendation for a different course offering.','https://degreesteps.com/degree-plans/wgu-public-health/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-59424da4751266782e13-guide-1','ds-guide-courses','post:ds-starter-59424da4751266782e13',NULL,'Attach the source version and effective recommendation dates to the course identity. An older award can be a valuable research lead, but it does not automatically establish today''s course or the current program placement. The receiving agreement also has its own version and catalog context. Both sides need to align; a familiar title cannot replace the exact source identity and the applicable destination evidence when either has changed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-59424da4751266782e13' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-59424da4751266782e13-guide-2','ds-guide-planning','post:ds-starter-59424da4751266782e13',NULL,'For completed work, preserve what you actually took and when, rather than updating the record to the latest course version. For a new purchase, use the current supported option in the exact program worksheet. If the match is historical or contradictory, keep it out of the established basket while the research is completed. This prevents a quiet version change from turning a reasonable looking choice into work the plan cannot justify.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-59424da4751266782e13' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-5afd784d69ea29928a48','ds-guide-planning','school:tesu','question','Should I budget around an Edison Accelerate or residency waiver scenario?','Example situation: I have read posts about ways to finish TESU with less university coursework than a standard plan shows. The stories sound appealing, but I cannot tell which enrollment arrangements they describe. Should I build my budget around one of those scenarios? I would prefer to understand the standard route first, then see any special arrangement as a separate option with its actual conditions.','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5afd784d69ea29928a48-guide-1','ds-guide-money','post:ds-starter-5afd784d69ea29928a48',NULL,'Begin with the exact standard rules used by the model rather than importing someone else''s enrollment arrangement. The reviewed TESU estimates use a standard fifteen credit institutional minimum and standard out of state, nonmilitary rates. Edison Accelerate, military or corporate arrangements, and other waiver scenarios are not silently selected. A different arrangement needs its own applicability and cost evidence before it can replace the baseline in your comparison.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5afd784d69ea29928a48' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5afd784d69ea29928a48-guide-2','ds-guide-planning','post:ds-starter-5afd784d69ea29928a48',NULL,'Compare a special arrangement as a second scenario once its terms are documented for your situation. Keep every named degree requirement intact and price the actual remaining university work under that scenario. This shows whether the arrangement changes your result instead of merely lowering a residency number on paper. A baseline you can understand makes it easier to evaluate a legitimate exception without depending on a forum anecdote.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5afd784d69ea29928a48' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-5ce60de2508b4ef3fee3','ds-guide-planning','school:umpi','question','Should I keep adding courses to my collection while waiting on a UMPI map?','Example situation: I enjoy the course library and keep finding subjects I could finish cheaply. UMPI is one of my preferred destinations, but I know a complete current map is not available in DegreeSteps yet. How can I keep making progress without treating every saved course as a good purchase? I want the collection to be helpful rather than become another long list I feel pressured to complete.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5ce60de2508b4ef3fee3-guide-1','ds-guide-momentum','post:ds-starter-5ce60de2508b4ef3fee3',NULL,'Saving a course is a way to remember an option, not a commitment to buy it or a claim that it fits every degree. Keep completed work, active study, and possible future courses distinct. For new spending, favor a supported requirement in a route you would genuinely accept, especially while UMPI specific placements remain unresolved. A course that is interesting but academically unplaced should remain a candidate rather than a graduation assumption.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5ce60de2508b4ef3fee3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5ce60de2508b4ef3fee3-guide-2','ds-guide-courses','post:ds-starter-5ce60de2508b4ef3fee3',NULL,'Choose one useful next action from the collection and leave the rest available for comparison. You might finish a course already underway, organize a transcript, or compare an established route while the missing map is researched. Do not keep subscriptions open merely because the saved list is long. The collection works best when it preserves your options and makes decisions easier, rather than turning exploration into a second unfinished curriculum.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5ce60de2508b4ef3fee3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-5d68750f5d551189ebbc','ds-guide-planning','school:wgu','question','Does a WGU health related degree qualify me for a clinical role?','Example situation: I want to work in healthcare, but I am still learning the difference between administration, health science, public health, and clinical training. Several WGU routes look interesting and flexible. How can I compare them without assuming every health related degree leads to the same jobs? I want an accelerated plan that fits a real goal, rather than a quick degree whose professional scope I misunderstood.','https://degreesteps.com/degree-plans/wgu-healthcare-administration/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5d68750f5d551189ebbc-guide-1','ds-guide-careers','post:ds-starter-5d68750f5d551189ebbc',NULL,'Start with the work you want to do, especially whether it requires a clinical license or a particular accredited professional program. The published Healthcare Administration, Health Science, and Public Health routes are distinct degrees with their own requirements. Their names do not establish eligibility for the same roles. A course transfer match can reduce bachelor coursework; it does not independently establish professional licensure or admission to a later clinical program.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5d68750f5d551189ebbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-5d68750f5d551189ebbc-guide-2','ds-guide-planning','post:ds-starter-5d68750f5d551189ebbc',NULL,'Bring a few job descriptions or further study prerequisites into the comparison. Then use the same existing records to see how much useful work remains in each relevant degree. This makes speed meaningful because the destination is right. Avoid picking the smallest course count first and hoping the career fit follows. The useful next step may be clarifying the role before purchasing any specialized outside course.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-5d68750f5d551189ebbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6057faefc6e50c6e4254','ds-guide-planning','school:umpi','question','Is the old UMPI Management minor the same as a current management program?','Example situation: A community plan refers to a UMPI Liberal Studies degree with a Management minor. On current pages I see different management related names, and I am not sure whether they represent the same degree. I do not want to lose a promising route, but I also do not want the platform to quietly swap my goal for another program simply because the names sound close.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6057faefc6e50c6e4254-guide-1','ds-guide-transfers','post:ds-starter-6057faefc6e50c6e4254',NULL,'Keep the exact historical goal intact. The reviewed record found older references to that Management minor and a current page that omits the exact option; it did not establish whether a particular student can still use it. Another program with Management and Leadership in the name is not automatically the same route. Current availability and the applicable curriculum need their own source before a substitution becomes a plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6057faefc6e50c6e4254' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6057faefc6e50c6e4254-guide-2','ds-guide-planning','post:ds-starter-6057faefc6e50c6e4254',NULL,'Compare genuinely current alternatives as separate choices, with their own degree titles and requirements, instead of renaming the old spreadsheet. If you already have an admission record tied to the older program, retain that document and catalog identity. If you are a new applicant, use the currently advertised options as research candidates. This protects the work you have done without inventing continuity or declaring a program discontinued without evidence.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6057faefc6e50c6e4254' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6176d76cc47b28c7ac46','ds-guide-planning','school:liberty','question','Can I use outside courses and still have a campus experience?','Example situation: I want the campus experience at Liberty, including student organizations and attending games, but paying university tuition for every introductory class feels out of reach. How should I compare a residential transfer plan with the online version? I want a clear course list that separates what I can finish before arriving from what I would actually need to take at Liberty.','https://degreesteps.com/degree-plans/liberty-business-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6176d76cc47b28c7ac46-guide-1','ds-guide-transfers','post:ds-starter-6176d76cc47b28c7ac46',NULL,'Start with the residential degree, not an online plan with a different delivery label. The published residential business and criminal justice routes have their own requirement rows. Put your existing coursework into that exact worksheet, then look at the outside options for the remaining rows. A course being accepted somewhere at Liberty does not automatically satisfy the requirement in your chosen residential major.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6176d76cc47b28c7ac46' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6176d76cc47b28c7ac46-guide-2','ds-guide-campus','post:ds-starter-6176d76cc47b28c7ac46',NULL,'Build a second budget for being on campus: housing, meals, transportation, and the semesters you expect to attend. Transfer savings in the course plan describe coursework; they do not make those living costs disappear. This lets you choose the experience deliberately. Keep the campus activities you value in your goal, rather than treating an online route as the only way to save.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6176d76cc47b28c7ac46' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-61bdd7a9b2e4bee0ac11','ds-guide-planning','course:upi-study-upis-0016','question','Should I compare UPI’s standalone course price with an eligible membership?','Example situation: I’m interested in several UPI business courses and see a standalone purchase amount alongside membership offers. The membership eligibility and transcript charges may make the comparison more complicated than dividing a monthly price by a hoped-for number of courses. How should I choose a purchasing route? I want to compare a realistic plan for the courses my degree can actually use, with my available study time and the relevant fees kept visible from the start.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-61bdd7a9b2e4bee0ac11-guide-1','ds-guide-money','post:ds-starter-61bdd7a9b2e4bee0ac11',NULL,'Use the exact standalone course purchase as one supported scenario, then evaluate any membership only if you qualify for that offer. The reviewed standalone UPI quotes are course-specific, while membership prices can depend on eligibility and product terms. Include the expected study period and transcript charges separately. An eligible membership may cost less, but the planner should not select the cheapest advertised membership for a student whose qualification for it has not been established.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-61bdd7a9b2e4bee0ac11' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-61bdd7a9b2e4bee0ac11-guide-2','ds-guide-transfers','post:ds-starter-61bdd7a9b2e4bee0ac11',NULL,'Keep the academic course choices stable while comparing purchase scenarios. Your degree needs the same supported learning whether you buy a course individually or use an eligible subscription. That helps prevent a shopping bundle from being mistaken for an academic credit bundle. Choose the purchasing route after counting the actual applicable courses, then keep renewals, taxes and transcript assumptions clear so the displayed saving is a scenario rather than a promised final bill.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-61bdd7a9b2e4bee0ac11' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-62ce6828e05f8327307f','ds-guide-planning','school:tesu','question','What should I keep for AP credit before choosing a college?','Example situation: I’m planning college courses while waiting to decide on a school, and AP exam results may change what I need. Should I enter a fixed number of credits for each exam now, or keep the scores until a college’s policy is applied? I want to avoid paying for an outside course that overlaps an exam award, but I also don’t want to assume that every university gives the same amount or accepts the same score for the same degree requirement.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-62ce6828e05f8327307f-guide-1','ds-guide-courses','post:ds-starter-62ce6828e05f8327307f',NULL,'Keep the official exam identity, score and date as the original evidence. The receiving college’s published AP policy supplies its score threshold and course award, so a general claim that an exam is worth a particular number of credits is not enough. If one school has already evaluated your scores, preserve that award for that school rather than treating its credit amount as the original result at every institution you later consider.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-62ce6828e05f8327307f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-62ce6828e05f8327307f-guide-2','ds-guide-transfers','post:ds-starter-62ce6828e05f8327307f',NULL,'Before purchasing another introductory course, compare its receiving placement with any supported AP award in the selected degree. The plan should identify overlapping requirements and keep you from counting the same award twice. Retain the official score report and add any document-delivery step to your checklist. This helps you choose the remaining coursework intelligently while preserving the difference between a possible exam award, an issued institutional evaluation and actual completed degree requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-62ce6828e05f8327307f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-63f9e45c82ffd012b2c2','ds-guide-planning','course:upi-study-upis-0020','question','Can upper-level source accounting become a lower-level university course?','Example situation: I’m comparing Managerial Accounting options and see an upper-division recommendation on the source side. My receiving degree may list a lower-numbered accounting course for a similar topic. Is that a contradiction, or can the university award the credit differently? I want to avoid assuming that an upper-level source recommendation automatically increases the upper-level total in every degree, especially when I’m trying to satisfy both an accounting requirement and a minimum amount of advanced coursework.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-63f9e45c82ffd012b2c2-guide-1','ds-guide-courses','post:ds-starter-63f9e45c82ffd012b2c2',NULL,'Those are separate classifications. The source recommendation describes the original learning, while the receiving institution determines its own course award and level. The reviewed UPI Managerial Accounting source has an upper-division ACE recommendation, but the degree’s upper-level total must follow the supported receiving allocation. Preserve both facts. Do not use the source’s level to replace a lower-level receiving classification or to satisfy an unrelated advanced accounting requirement automatically.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-63f9e45c82ffd012b2c2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-63f9e45c82ffd012b2c2-guide-2','ds-guide-transfers','post:ds-starter-63f9e45c82ffd012b2c2',NULL,'When comparing accounting routes, look at the exact required receiving courses and the remaining upper-level minimum together. One supported source option may satisfy a named introductory requirement while leaving advanced requirements open. Another may have a different documented placement. Your source record should stay unchanged when you compare degrees; the allocation is what changes. This prevents a plan from appearing complete simply because several outside course descriptions use advanced or upper-level language.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-63f9e45c82ffd012b2c2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-641d3f70c9dfda6299d8','ds-guide-planning','school:umpi','question','Why should I not assume UMPI accepts ninety Sophia credits?','Example situation: I have seen very confident posts about transferring a large block of alternative courses to UMPI. Other sources mention a smaller prior learning limit. I do not want to become an expert in policy wording, but I also do not want to pay for a basket built on the wrong assumption. How should this uncertainty affect the courses I choose while considering YourPace?','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-641d3f70c9dfda6299d8-guide-1','ds-guide-transfers','post:ds-starter-641d3f70c9dfda6299d8',NULL,'Keep the overall transfer allowance separate from the rules governing particular credit sources. The reviewed record contains unresolved scope differences between older credit for prior learning evidence and current YourPace transfer language. It does not establish a universal ninety credit ACE allowance, or a resolved current YourPace specific thirty credit ACE rule. DegreeSteps should not turn either interpretation into an authoritative purchase recommendation without the governing evidence.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-641d3f70c9dfda6299d8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-641d3f70c9dfda6299d8-guide-2','ds-guide-planning','post:ds-starter-641d3f70c9dfda6299d8',NULL,'Your existing courses still belong in your collection; an unresolved policy scope is not a finding that they are rejected. For new spending, favor courses with an established use in the other serious degree options you are comparing rather than building a large UMPI specific basket on an assumption. The missing research belongs with DegreeSteps. It should be resolved and reflected in the map before a route is presented as ready.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-641d3f70c9dfda6299d8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-64591929bd0d2ac7129b','ds-guide-planning','school:general','question','How do I check that a lower-cost degree still fits an employer or future school?','Example situation: I am attracted to a flexible degree route, but I do not want cost savings to create problems when I apply for a job or graduate school. Provider websites use words like recommended, accredited, and transferable in ways that seem different. How can I understand the institution and degree I am choosing without treating every course provider’s recommendation as the same kind of recognition?','https://degreesteps.com/guides/ace-nccrs-and-accreditation/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64591929bd0d2ac7129b-guide-1','ds-guide-careers','post:ds-starter-64591929bd0d2ac7129b',NULL,'Prepared guide answer: Use the accreditation and credit-recommendation guide to separate three questions: the institution awarding your degree, the basis for an outside course’s credit recommendation, and the receiving program’s use of that learning. ACE and NCCRS recommendations are not the same as institutional accreditation. Compare the actual degree and institution against the published requirements of the employer, graduate program, or professional route that matters to you.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64591929bd0d2ac7129b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64591929bd0d2ac7129b-guide-2','ds-guide-transfers','post:ds-starter-64591929bd0d2ac7129b',NULL,'Prepared guide answer: Keep the receiving degree at the center of the comparison and use original course records to explain how you plan to get there. A familiar teaching brand, a provider partner logo, or an impressive accepted-credit total does not answer every recognition question. Identify the specific next-stage requirement that could affect your choice, then keep its source with the plan. That produces a clearer decision than collecting broad reassurance about accreditation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64591929bd0d2ac7129b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-64b2901dd2c7c7450479','ds-guide-planning','school:liberty','question','I marked a course finished by mistake. Does that change my transfer plan?','Example situation: I accidentally marked an outside course finished while exploring my Liberty worksheet. I have not enrolled in that course, let alone passed it. How should I correct my plan so the progress display is honest? I also want to understand what finished means compared with the university accepting a transcript, because those feel like two different milestones in the journey.','https://degreesteps.com/degree-plans/liberty-criminal-justice-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64b2901dd2c7c7450479-guide-1','ds-guide-momentum','post:ds-starter-64b2901dd2c7c7450479',NULL,'Change the course back to the status that matches reality: saved for a possibility, or in progress only after you have started. Your plan should let you revise a status without losing the selected course or its original identity. A completion marker records your work; it does not create an official Liberty award or replace the transcript needed for evaluation. Keep those two facts separate in the worksheet.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64b2901dd2c7c7450479' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64b2901dd2c7c7450479-guide-2','ds-guide-transfers','post:ds-starter-64b2901dd2c7c7450479',NULL,'After correcting the status, check the overall progress display and the next action for that course. If you completed real coursework, keep the evidence and arrange the appropriate transcript instead of just turning the row green. If you only selected a candidate, your next action is to compare or begin it. Accurate progress makes the checklist useful and prevents a mistaken click from hiding unfinished work.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64b2901dd2c7c7450479' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-64ba552a1739ef52087f','ds-guide-planning','course:clep-7f636e63b275888a7e','question','Can the same CLEP language score produce different credit amounts at different schools?','Example situation: I’m considering a CLEP language exam because I already know some Spanish. I see examples of students receiving different amounts of credit, and I don’t want to budget my degree around somebody else’s score result. How should I compare the possible awards before choosing a school or exam? I want to understand the exact score thresholds and degree application without assuming that one language test always supplies the same number of credits everywhere.','https://degreesteps.com/courses.html?provider=CLEP',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64ba552a1739ef52087f-guide-1','ds-guide-courses','post:ds-starter-64ba552a1739ef52087f',NULL,'Compare the receiving school’s published score thresholds and course awards for that exact exam. A score can correspond to different credit amounts or course combinations at different institutions. The official score report remains your original result; the university’s award is the receiving side. Keep the score and test identity intact, and let each degree comparison apply the supported policy rather than copying another student’s reported number of language credits.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64ba552a1739ef52087f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-64ba552a1739ef52087f-guide-2','ds-guide-transfers','post:ds-starter-64ba552a1739ef52087f',NULL,'Then check whether those language awards actually fill open requirements in your intended degree. A generous exam award is less useful if it duplicates completed language work or falls outside an allowed block. Consider any score-report fees, exam conditions and relevant deadlines as part of the route. This lets you compare the exam against other supported options while keeping a possible award separate from credit you have already earned and had applied.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-64ba552a1739ef52087f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6792783086cf389c1b4a','ds-guide-planning','school:tesu','question','Why does a provider promotion not automatically reduce my TESU estimate?','Example situation: I found an advertised discount for a course provider and expected my TESU plan price to drop immediately. The offer may apply only to a particular plan or first billing period. How should I use it in a real budget? I want discounts to help, but I do not want an estimate that assumes I qualify or finish everything before a promotional period ends.','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6792783086cf389c1b4a-guide-1','ds-guide-money','post:ds-starter-6792783086cf389c1b4a',NULL,'Keep the academic choice and the promotion separate. A valid receiving match does not establish offer eligibility, and a discount does not make an unsupported course transferable. Compare the selected provider plan with the offer''s stated audience, duration, renewal price, and exclusions. DegreeSteps currently distinguishes official public offers from an exclusive negotiated code; it should not imply that an ordinary public promotion is a special student entitlement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6792783086cf389c1b4a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6792783086cf389c1b4a-guide-2','ds-guide-courses','post:ds-starter-6792783086cf389c1b4a',NULL,'Use the standard complete course cost as the baseline, then show an eligible offer as a transparent adjustment to your own budget. If the work spans more billing periods than the discount covers, include the later periods at their applicable price. Keep transcript and exam charges where required. That gives the promotion a useful role without letting a temporary headline disguise the actual cost of finishing your selected courses.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6792783086cf389c1b4a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-67ecf61be0a2f24e1c46','ds-guide-planning','course:clep-a76a7cca6f6096155c','question','Does a CLEP voucher make the whole exam route free?','Example situation: I’m exploring a CLEP route and have heard that preparation programs may offer exam vouchers. That could make the route more affordable, but I’m not sure which steps or charges are included. How should I budget before relying on a voucher? I want to understand eligibility, scheduling and any separate fees while still checking that the exam satisfies a real requirement in my degree rather than choosing it only because an advertised test cost might be covered.','https://degreesteps.com/courses.html?provider=CLEP',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-67ecf61be0a2f24e1c46-guide-1','ds-guide-money','post:ds-starter-67ecf61be0a2f24e1c46',NULL,'Treat the voucher as a separate funding benefit with its own current eligibility and issuance requirements. A preparation program’s existence does not establish that you have already received a usable voucher or that every associated charge is covered. Check the applicable exam, testing arrangement, possible administrative charges and score-delivery needs. In the plan, keep the normal route and any verified voucher benefit distinguishable so an unissued benefit does not become a guaranteed zero-dollar cost.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-67ecf61be0a2f24e1c46' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-67ecf61be0a2f24e1c46-guide-2','ds-guide-transfers','post:ds-starter-67ecf61be0a2f24e1c46',NULL,'Choose the exam only after checking its supported receiving award and application to your degree. Then add the preparation, voucher request, scheduling and score-report steps to your checklist as needed. This makes the funding process executable without confusing it with academic credit. A voucher can reduce a charge for an eligible student, while the actual exam result and the receiving school’s policy still determine whether the degree requirement is satisfied.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-67ecf61be0a2f24e1c46' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-69794955dbb5125b65db','ds-guide-planning','school:general','question','My shifts change every month. Should I avoid programs with fixed terms?','Example situation: I work at a manufacturing plant with a rotating schedule that includes occasional mandatory overtime. I can usually study, but not at the same hour every day. I like the idea of self-paced courses and worry that a fixed term would punish me during a busy month. Is the right answer always competency-based study, or are there other ways to make this work?','https://degreesteps.com/guides/finish-faster-without-wasting-credit/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-69794955dbb5125b65db-guide-1','ds-guide-planning','post:ds-starter-69794955dbb5125b65db',NULL,'Prepared guide answer: Use Find a degree to compare pace and billing separately. Competency-based describes how learning is assessed; it does not promise unlimited flexibility, no deadlines, or a low price for every student. A term-based program with asynchronous classes might also fit rotating shifts. Open each route and identify the actual assignments, university sequence, and payment period before treating one format as the obvious winner.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-69794955dbb5125b65db' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-69794955dbb5125b65db-guide-2','ds-guide-momentum','post:ds-starter-69794955dbb5125b65db',NULL,'Prepared guide answer: Build around the overtime month as well as the quiet month. A subscription keeps charging while you are busy, so compare fewer courses completed in a paid period with the price of an individual course. Start with one course whose requirements are clear. When your shift pattern becomes easier, you can increase the pace without rebuilding the degree or losing the records already in My courses.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-69794955dbb5125b65db' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-699e4a3946fcc62bb6cb','ds-guide-planning','school:tesu','question','Why does my TESU estimate include more than the minimum university credits?','Example situation: I thought the TESU plan would leave only the minimum amount of university coursework. The estimate shows more institution courses because some requirements have no selected outside match. Is that extra work a mistake? I want a realistic budget, but I also want to know where additional mapping research could reduce the remaining tuition without quietly removing a degree requirement.','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-699e4a3946fcc62bb6cb-guide-1','ds-guide-transfers','post:ds-starter-699e4a3946fcc62bb6cb',NULL,'The minimum is a floor, not a promise about your remaining course list. A valid plan still needs every named requirement and level rule satisfied. If a requirement currently has only a university option selected, its actual cost belongs in the estimate even when that takes university coursework above the minimum. Pricing the minimum alone would make an incomplete transfer basket look like a finished budget.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-699e4a3946fcc62bb6cb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-699e4a3946fcc62bb6cb-guide-2','ds-guide-money','post:ds-starter-699e4a3946fcc62bb6cb',NULL,'Review those extra university rows one at a time. Where an exact supported outside alternative exists, compare its price and workload; where evidence is incomplete, keep the option conditional instead of deducting the tuition immediately. DegreeSteps has modeled TESU requirements but does not currently publish a fully ready TESU template. That distinction helps keep an attractive estimate from being presented as a complete, established route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-699e4a3946fcc62bb6cb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6a99dae00c530d800588','ds-guide-planning','school:umpi','question','Should I pick Accounting or Project Management for a UMPI Liberal Studies degree?','Example situation: UMPI lists Liberal Studies options with Accounting and Project Management minors, and both sound relevant to my work. I mainly want a practical bachelor degree, but I do not understand how much the minor changes the route. How should I compare them using my existing courses without assuming that a broad Liberal Studies title means the same coursework will satisfy every available minor?','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6a99dae00c530d800588-guide-1','ds-guide-careers','post:ds-starter-6a99dae00c530d800588',NULL,'The current reviewed marketing descriptions identify both as YourPace offerings and describe the same broad structure: 120 credits, including forty general education, eighteen minor core, and sixty two electives. Those totals establish the size of the blocks, not the named courses or individual transfer placements. Compare the specific minor content and your career goal rather than treating the shared overall structure as proof that the two minors are interchangeable.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6a99dae00c530d800588' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6a99dae00c530d800588-guide-2','ds-guide-planning','post:ds-starter-6a99dae00c530d800588',NULL,'Keep your original transcript as one collection, then evaluate each exact minor as its own destination when its current course ledger is available. A completed course might fit the general degree but not the chosen minor. For the decision today, list the work you want to do and the subjects you want to learn. That helps choose a useful destination while DegreeSteps completes the unresolved catalog specific map.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6a99dae00c530d800588' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6aaced9838bb0a28c193','ds-guide-campus','course:clep-1173ea88b04c37373a','question','Can I use CLEP for an on-campus degree without losing the college experience?','Example situation: I want an on-campus degree and the experience of joining a college community, but I’m also interested in finishing some requirements through exams before arriving. How should I judge a CLEP option for that kind of plan? I don’t want to assume that transfer-friendly online examples apply unchanged to a residential program. I’m looking for a route that reduces unnecessary time or cost while preserving the institution’s campus, major and residency requirements for the degree I choose.','https://degreesteps.com/courses.html?provider=CLEP',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6aaced9838bb0a28c193-guide-1','ds-guide-courses','post:ds-starter-6aaced9838bb0a28c193',NULL,'Choose the residential degree and its exact catalog before allocating the exam. A school can apply different requirements across delivery formats or programs, so an online example is not enough to establish the campus award. Review the exam’s named receiving course, any score threshold and the degree’s residency and major conditions. The remaining university work should stay visible so your campus plan reflects the academic experience you actually intend to complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6aaced9838bb0a28c193' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6aaced9838bb0a28c193-guide-2','ds-guide-campus','post:ds-starter-6aaced9838bb0a28c193',NULL,'Consider housing, meal plans, scholarships and enrollment status separately from tuition credits. Reducing required courses does not automatically reduce every campus expense or preserve every aid arrangement unchanged. Add the relevant college decisions to your checklist before committing to a schedule. Comparing the actual remaining campus work and costs can help you decide whether the exam route supports your goals, while keeping school-specific enrollment and student-life choices distinct from the credit match.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6aaced9838bb0a28c193' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6c33ee4d20aa22e77b14','ds-guide-campus','school:general','question','Is transferring a lot of credit enough to make one final year on campus realistic?','Example situation: I would love to complete most eligible courses elsewhere and spend a final year living on campus. I understand that other students have done something like this, but I do not know what would make it work for my exact major. If a school accepts a large transfer total, what else could stop the remaining courses from fitting into one year?','https://degreesteps.com/guides/transfer-credit-for-campus-degrees/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6c33ee4d20aa22e77b14-guide-1','ds-guide-planning','post:ds-starter-6c33ee4d20aa22e77b14',NULL,'Prepared guide answer: Open the exact campus degree plan and look beyond the total transfer allowance. The remaining university courses may have prerequisites, admission steps, minimum residency, or limited offering schedules. A large accepted-credit number does not establish that the requirements left can all be taken together. Use the worksheet to identify the actual university course sequence and any required experience rather than planning from a percentage alone.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6c33ee4d20aa22e77b14' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6c33ee4d20aa22e77b14-guide-2','ds-guide-campus','post:ds-starter-6c33ee4d20aa22e77b14',NULL,'Prepared guide answer: Build the possible campus year around the hardest scheduling constraint first, such as a capstone sequence or a course offered once a year. Then see where the other remaining requirements fit. Keep a longer backup scenario in the cost comparison, including another term of housing if relevant. That approach turns an appealing goal into a testable plan without treating somebody else’s one-year experience as your deadline promise.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6c33ee4d20aa22e77b14' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6c9173a9b3e913ae2cfd','ds-guide-planning','course:sophia-02db8705b8c89561e4','question','Is a foundations math course a substitute for College Algebra?','Example situation: I’m returning to math after a long break and would like an easier starting point. My degree plan mentions College Algebra, while the course library also has introductory and foundations options. Can I use a foundations course to satisfy the same requirement, or should I treat it as preparation? I’m willing to spend extra time rebuilding skills, but I don’t want to purchase a course expecting degree credit it cannot provide.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6c9173a9b3e913ae2cfd-guide-1','ds-guide-courses','post:ds-starter-6c9173a9b3e913ae2cfd',NULL,'Use the degree requirement as your starting point. College Algebra and a foundations course can teach related skills without carrying the same recommendation or receiving award. Open the named algebra option and compare its identity with the plan row. If a foundations course is useful preparation, schedule it as preparation unless the selected degree explicitly supports it. The friendliest title is not enough to establish that it replaces the required math course.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6c9173a9b3e913ae2cfd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6c9173a9b3e913ae2cfd-guide-2','ds-guide-transfers','post:ds-starter-6c9173a9b3e913ae2cfd',NULL,'Separate your learning decision from your credit decision. You can practice algebra before enrolling in the course selected for your degree, while leaving the required row uncompleted. Keep the preparation activity in your notes or checklist, and save the credit-bearing course in My courses. When you finish the actual source course, retain its original course code, completion date and record; those facts support later matching if you change schools.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6c9173a9b3e913ae2cfd' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6d5473352cd9cdeb51b8','ds-guide-planning','school:general','question','Can I start planning if one college is slow to send my transcript?','Example situation: I have one transcript ready, but an older college has not sent the other one yet. I remember taking English, statistics, and several electives there, although I cannot remember the exact codes or grades. I want to make progress this week without entering a bunch of guesses as completed credit. Which parts of planning can I do now, and which purchases should wait for the missing record?','https://degreesteps.com/start.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6d5473352cd9cdeb51b8-guide-1','ds-guide-transfers','post:ds-starter-6d5473352cd9cdeb51b8',NULL,'Prepared guide answer: Import the record you already have, then continue with a provisional plan for the missing school. Keep remembered subjects as notes or future questions rather than turning them into confirmed degree placements. You can still choose a goal, compare study formats, and inspect available plans. The missing transcript changes how certain the credit inventory is; it does not have to stop every planning decision.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6d5473352cd9cdeb51b8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6d5473352cd9cdeb51b8-guide-2','ds-guide-money','post:ds-starter-6d5473352cd9cdeb51b8',NULL,'Prepared guide answer: Hold off on buying replacement English or statistics courses until you know whether the earlier work applies. Instead, compare the university coursework left across two likely degrees and organize the next document request. A small amount of waiting can prevent paying twice for the same requirement. When the record arrives, import and review it, then update the existing plan rather than rebuilding your course collection.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6d5473352cd9cdeb51b8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6e3d0b5d916c1229dd5c','ds-guide-planning','school:wgu','question','What happens to saved courses if I switch WGU degrees?','Example situation: I started building a WGU business plan, but Project Management and Supply Chain now look more relevant to my work. I have not taken all the courses I saved, and I may change my mind again. Can I compare these routes without starting from scratch? I want to see what still applies, what becomes unused, and which next course keeps the most sensible options open.','https://degreesteps.com/degree-plans/wgu-project-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6e3d0b5d916c1229dd5c-guide-1','ds-guide-transfers','post:ds-starter-6e3d0b5d916c1229dd5c',NULL,'Keep the original course collection and run separate exact degree comparisons. Completed work stays completed in your records, while each degree decides where it can legitimately apply. A saved candidate is still a possibility rather than earned credit. Shared subject names do not establish identical receiving matches, so the comparison should use the actual program agreement and requirement, not simply copy the old plan''s green rows into the new one.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6e3d0b5d916c1229dd5c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6e3d0b5d916c1229dd5c-guide-2','ds-guide-careers','post:ds-starter-6e3d0b5d916c1229dd5c',NULL,'Look at the difference in remaining specialized work, university obligations, and realistic term scenarios. If you are still deciding, favor a supported course that helps the serious alternatives instead of buying all the major specific options at once. A course becoming unused is a meaningful tradeoff, not a reason to conceal it. The comparison should help you choose deliberately and carry forward the original records without making a change feel like failure.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6e3d0b5d916c1229dd5c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6f392598380c66283cbb','ds-guide-military','school:general','question','My military record and college transcript seem to cover the same subject. Can both count?','Example situation: I completed military training in a technical subject and later took a college course with a similar title. I would like to use everything I earned, but I worry that my projected transfer total counts the same learning twice. I am looking at both a technical degree and a broader management degree. How should I keep the records and compare their actual use without losing either one?','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6f392598380c66283cbb-guide-1','ds-guide-transfers','post:ds-starter-6f392598380c66283cbb',NULL,'Prepared guide answer: Keep both original records in the collection with their actual issuers and dates. Similar learning may have different uses in different programs, but that does not mean both awards can satisfy the same requirement or evade a duplicate-learning rule. Compare the degrees using the same inventory, then inspect the actual placements rather than adding a military recommendation total to an institutional transcript total.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6f392598380c66283cbb' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6f392598380c66283cbb-guide-2','ds-guide-military','post:ds-starter-6f392598380c66283cbb',NULL,'Prepared guide answer: Focus on whether each route has room for distinct learning in its general education, major, and elective requirements. A broad management degree might allocate an eligible technical course differently from a technical major, but that must come from its rules and your records. Retaining both originals lets you revisit the question later. Editing one title to make the courses look unrelated would only make the comparison less trustworthy.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6f392598380c66283cbb' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-6f532bcec5536da201c5','ds-guide-money','school:general','question','Will financial aid cover the lower-cost courses in my transfer plan?','Example situation: I may qualify for financial aid at a university and am also interested in taking some requirements through alternative providers. I do not know whether a lower course price means the same funding can be used everywhere. I want to compare the real amount I would pay, rather than assuming that all courses in one degree plan are billed through the university. How should I think about this?','https://degreesteps.com/guides/compare-transfer-credit-sources/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6f532bcec5536da201c5-guide-1','ds-guide-money','post:ds-starter-6f532bcec5536da201c5',NULL,'Prepared guide answer: Separate the provider purchases from the receiving university’s charges in your comparison. A course being useful toward a degree does not establish that your university aid pays for that outside purchase. Use the plan to identify what is taken where, then apply the actual funding terms to each part. Keep the published academic price and the amount left after applicable funding visible as different numbers.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6f532bcec5536da201c5' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-6f532bcec5536da201c5-guide-2','ds-guide-planning','post:ds-starter-6f532bcec5536da201c5',NULL,'Prepared guide answer: Compare a transfer-heavy route with the university route using your real funding situation and expected workload. A lower sticker price can still require more cash upfront, while reducing enrolled university coursework may have other consequences for your schedule or funding. Focus the next question on the exact courses, enrollment period, and benefit involved. Do not enter an unapproved funding amount into the plan simply to make the cheapest-looking route win.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-6f532bcec5536da201c5' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-70cc7d42ef3b4b3a7b03','ds-guide-planning','school:general','question','Can I start planning on my phone if I only have occasional access to a laptop?','Example situation: I use my phone for most things and can borrow a family laptop on weekends. I would like to explore a degree and organize my old courses before buying a computer. I know some course assessments might need more than a phone, but I do not want to assume I need expensive equipment for every step. How should I separate the planning tasks from the technology needed to complete actual courses?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-70cc7d42ef3b4b3a7b03-guide-1','ds-guide-planning','post:ds-starter-70cc7d42ef3b4b3a7b03',NULL,'Prepared guide answer: You can begin by exploring degrees and reviewing your course collection on your phone. If you have a transcript or spreadsheet file, use the upload preview to inspect the rows before adding them. Save the plan to your account so you can reopen it when you have laptop access. Planning access and a provider’s requirements for assignments or assessments are separate questions, so do not assume every course can be completed on a phone.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-70cc7d42ef3b4b3a7b03' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-70cc7d42ef3b4b3a7b03-guide-2','ds-guide-money','post:ds-starter-70cc7d42ef3b4b3a7b03',NULL,'Prepared guide answer: Before purchasing a course, list its required browser, device, software, connectivity, and assessment setup. Compare those needs with when the shared laptop is actually available. Equipment or access costs belong in your practical budget even when the course itself is inexpensive. You can still save future course ideas without buying them now. A useful first step is finding one applicable option whose technology requirements fit the access you already have.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-70cc7d42ef3b4b3a7b03' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-71a7bb2b77b2a01a9251','ds-guide-planning','school:tesu','question','Should I take both courses when a TESU row lists alternatives?','Example situation: A shared TESU spreadsheet lists more than one course beside a requirement. I cannot tell whether those are alternatives, a required sequence, or a bundle that needs both courses. I am worried about buying the wrong combination. How should a clear degree plan represent those choices so I can act on it without translating spreadsheet shorthand or guessing from the total credits?','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-71a7bb2b77b2a01a9251-guide-1','ds-guide-courses','post:ds-starter-71a7bb2b77b2a01a9251',NULL,'An alternative, a sequence, and a bundle need different treatment. If two courses are interchangeable options for the same requirement, you choose one; if the receiving rule requires both, neither should be presented as sufficient by itself. Keep the exact rule, source identity, and receiving quantity visible together. A slash, an OR, or a repeated title in a community spreadsheet is a research lead rather than an executable instruction.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-71a7bb2b77b2a01a9251' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-71a7bb2b77b2a01a9251-guide-2','ds-guide-money','post:ds-starter-71a7bb2b77b2a01a9251',NULL,'Before paying, make the selected basket unambiguous: these specific source courses satisfy this specific requirement under this evidence. Keep unselected alternatives available for comparison without adding them to completed progress or the paid course list. This protects both the credit calculation and the budget. It also makes a later provider change easier, because you can replace an option deliberately without accidentally stacking duplicate coursework onto the same row.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-71a7bb2b77b2a01a9251' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-71ea0772d6f85ef5cb81','ds-guide-planning','school:tesu','question','Does a provider directory tell me every course I can use at TESU?','Example situation: I found different provider labels in TESU''s directory and am not sure what they mean for my course choices. Some courses appear in shared plans even when a provider is still under review. Should I ignore those sources entirely, or assume that familiar names will work? I need a clearer distinction between a provider relationship and an actual match to a degree requirement.','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-71ea0772d6f85ef5cb81-guide-1','ds-guide-transfers','post:ds-starter-71ea0772d6f85ef5cb81',NULL,'Use the directory as one part of the evidence. In the current reviewed record, Study.com is approved, while Sophia, StraighterLine, Saylor, and CLEP show provisional review pending. That pending label alone establishes neither a complete ban nor permission for every course. A provider being listed also does not tell you the exact receiving award or where it satisfies the particular degree you selected.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-71ea0772d6f85ef5cb81' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-71ea0772d6f85ef5cb81-guide-2','ds-guide-planning','post:ds-starter-71ea0772d6f85ef5cb81',NULL,'Work from the requirement toward the course. Look for a current source identity, a supported receiving award, and an applicable placement, retaining any unresolved condition visibly. An old spreadsheet can help locate a lead, but it cannot erase the current directory status or replace exact evidence. This keeps the plan useful across multiple sources without pretending that a partnership badge answers every academic question for a student.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-71ea0772d6f85ef5cb81' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-72ba8630df74f7ca1dc4','ds-guide-planning','school:wgu','question','Can one outside course fill two separate WGU requirements?','Example situation: A provider course covers several topics that appear in different WGU rows. Could it count toward both, or should the plan use it only once? I want to maximize useful credit, but I do not want my progress bar to look nearly finished because the same original course was copied into multiple places. How should the worksheet make the actual remaining work clear?','https://degreesteps.com/degree-plans/wgu-psychology/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-72ba8630df74f7ca1dc4-guide-1','ds-guide-courses','post:ds-starter-72ba8630df74f7ca1dc4',NULL,'Keep a single original course record and enforce the receiving rule for its actual use. Covering related topics does not automatically create two separate awards. The reviewed WGU planning guards prevent one original source course from being reused across separate requirements to inflate coverage. That matters especially when the same provider appears in several agreement rows or a community spreadsheet repeats an option without explaining the limitation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-72ba8630df74f7ca1dc4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-72ba8630df74f7ca1dc4-guide-2','ds-guide-planning','post:ds-starter-72ba8630df74f7ca1dc4',NULL,'Use the course where it produces a legitimate placement, then choose a different supported option for the other requirement if needed. A what if comparison may show the same course in different destinations across separate degree scenarios, but that is different from counting it twice inside one degree. Keeping that distinction visible makes the progress total trustworthy and prevents a later audit from revealing an unexpectedly unfinished subject.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-72ba8630df74f7ca1dc4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-7743d71f274e553caed8','ds-guide-planning','school:tesu','question','When is TESU flat term tuition different from paying per credit?','Example situation: I am comparing TESU with a subscription based program and cannot tell how to budget the final university courses. A per credit calculation and a flat term calculation give different totals. How should I use those prices without assuming I can fit every remaining class into one term? I am paying out of pocket and need a realistic range rather than the lowest theoretical number.','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7743d71f274e553caed8-guide-1','ds-guide-money','post:ds-starter-7743d71f274e553caed8',NULL,'The reviewed standard out of state, nonmilitary rates distinguish two situations: $584 per credit below nine credits, and a $4,652 flat term price for nine to eighteen eligible credits. Those are population specific rates, not a quote for every student. Start with your actual remaining university courses and their feasible schedule, then apply the relevant price structure instead of multiplying only the institutional minimum.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7743d71f274e553caed8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7743d71f274e553caed8-guide-2','ds-guide-momentum','post:ds-starter-7743d71f274e553caed8',NULL,'Add the reviewed application and graduation audit fees to the comparison, and keep provider charges separate. Then check whether work, prerequisites, or course availability make your proposed term load realistic. New Jersey or Pennsylvania tuition, military rates, employer arrangements, and waiver scenarios need their own treatment. A range that reflects a workable schedule helps you decide more than a single low number built on a perfect term.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7743d71f274e553caed8' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-78b51b2bacf267415bde','ds-guide-planning','school:tesu','question','How should I read a UPI option in a TESU plan?','Example situation: UPI has TESU transfer information and some courses look appealing for my budget. If the provider lists a receiving course, can I treat that as ready to use, or is it different from a university published agreement? I want the platform to show more useful sources, but I do not want my estimated degree progress to depend on an approval nobody has actually established.','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-78b51b2bacf267415bde-guide-1','ds-guide-courses','post:ds-starter-78b51b2bacf267415bde',NULL,'The reviewed TESU provider directory identifies University Pathways International, but that directory is not a course equivalency table. The current UPI placements in DegreeSteps are provider published conditional options. They keep their exact original identity, source quantity, and proposed receiving award separate. That is useful information for comparison; it is not the same evidence as a current university published award for the exact requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-78b51b2bacf267415bde' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-78b51b2bacf267415bde-guide-2','ds-guide-money','post:ds-starter-78b51b2bacf267415bde',NULL,'A conditional choice should stay labeled and should not turn into earned credit when saved. Compare it with established alternatives for the same open requirement and include its actual assessment format and price. The reviewed UPI course pages describe remotely proctored finals and standalone purchases, so neither a no proctor assumption nor an unrelated membership price belongs in that comparison. DegreeSteps must resolve the academic placement before calling it established.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-78b51b2bacf267415bde' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-7c7a5d0d25a35e1cf32c','ds-guide-planning','school:general','question','Should I arrange extended time before starting a paid course?','Example situation: I have used extended time for exams in previous education and would like to know how that works when courses come from several providers. I do not want to share personal documentation in a community post, and I am not sure whether approval at one college carries over somewhere else. How should I include the support process in my plan without slowing down every other decision?','https://degreesteps.com/plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7c7a5d0d25a35e1cf32c-guide-1','ds-guide-planning','post:ds-starter-7c7a5d0d25a35e1cf32c',NULL,'Prepared guide answer: Keep personal documentation out of the public discussion and identify the exact provider or university responsible for each assessment. Accommodation processes can differ, so an arrangement at one institution should not be assumed to apply elsewhere. In My plan, make the support request a next-step task before the relevant paid course or timed assessment. You can continue comparing degree requirements while that specific arrangement is being made.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7c7a5d0d25a35e1cf32c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7c7a5d0d25a35e1cf32c-guide-2','ds-guide-courses','post:ds-starter-7c7a5d0d25a35e1cf32c',NULL,'Prepared guide answer: Ask about the actual process, lead time, assessment tool, and what happens if approval arrives after the membership begins. Those details can affect both your schedule and your cost. Choose another already suitable task while waiting, rather than paying for several courses whose assessment arrangements are unsettled. Your degree plan should make room for the support you need without requiring you to publish a diagnosis or explain it to other users.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7c7a5d0d25a35e1cf32c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-7da86fd2ed3adc349292','ds-guide-planning','school:general','question','I want to be a pilot. How do I compare degree costs with flight training?','Example situation: I am interested in an aviation career and keep seeing very different prices for university programs and independent flight schools. I want a college degree, but I do not understand which costs belong to academic coursework and which belong to flight training or credentials. Could outside general education courses help without changing the training I actually need? I want a plan that makes those pieces understandable before I commit.','https://degreesteps.com/request-plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7da86fd2ed3adc349292-guide-1','ds-guide-careers','post:ds-starter-7da86fd2ed3adc349292',NULL,'Prepared guide answer: Keep the degree and flight credentials as related but separate goals. Use the exact aviation program link in Build from a degree link so the research concerns the real program, then separate published academic requirements from flight training, experience, and other professional conditions. A low tuition figure is incomplete if substantial training charges sit outside it. General education transfer possibilities should be mapped to that exact degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7da86fd2ed3adc349292' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7da86fd2ed3adc349292-guide-2','ds-guide-money','post:ds-starter-7da86fd2ed3adc349292',NULL,'Prepared guide answer: Compare the full cost structure before choosing between a university route and separate academic and flight programs. Include required training charges, equipment, travel, and scheduling constraints where the program publishes them. Do not assume an outside course replaces a flight component or that every aviation job has the same degree requirement. Your first useful comparison is what each route actually includes, with unpriced training items kept visible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7da86fd2ed3adc349292' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-7e9c2e12d5d42c38c8df','ds-guide-planning','school:liberty','question','I have old college credits. Should I take Sophia courses before uploading them?','Example situation: I attended college years ago and do not remember every course number. I am tempted to begin a provider membership this week because I finally feel motivated. How should I get moving without paying for classes I already completed? I would like a Liberty plan that uses my old records first and keeps missing paperwork from stopping the whole process.','https://degreesteps.com/degree-plans/liberty-human-services-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7e9c2e12d5d42c38c8df-guide-1','ds-guide-transfers','post:ds-starter-7e9c2e12d5d42c38c8df',NULL,'Collect the records you already have before choosing a first paid course. Upload a transcript or fill the spreadsheet with the original college, course code, title, credits, and completion details. Keep uncertain entries identified as uncertain rather than changing them to a guessed equivalent. A completed course is different from an evaluated Liberty award, but preserving the original record gives the plan something reliable to compare.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7e9c2e12d5d42c38c8df' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-7e9c2e12d5d42c38c8df-guide-2','ds-guide-momentum','post:ds-starter-7e9c2e12d5d42c38c8df',NULL,'While the transcript request is underway, explore courses against requirements your records clearly do not cover. Save candidates without marking them completed. Once your records are available, remove duplicate purchases from the first basket and check what genuinely remains. This keeps the early momentum, but directs it toward a useful course instead of repeating introductory work simply because a provider makes enrollment easy.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-7e9c2e12d5d42c38c8df' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-82bea3bf81f0461318ba','ds-guide-planning','school:general','question','I accidentally marked a course Finished. How do I put it back?','Example situation: I was exploring my plan and marked a course Finished even though I am only halfway through it. The progress display changed, and I am worried that correcting it will delete the course or lose the notes I entered. I want to keep the same course and continue tracking my work accurately. What is the right way to undo that kind of mistake and check that the plan reflects the change?','https://degreesteps.com/courses.html?tab=mine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-82bea3bf81f0461318ba-guide-1','ds-guide-courses','post:ds-starter-82bea3bf81f0461318ba',NULL,'Prepared guide answer: Open My courses, find the record, and use its edit action to change the status from Finished to Taking, or Not started if you have not begun. Review the change and save it. You are correcting your personal progress record, not deleting the course or changing an official transcript. Keep the original provider, course code, and units accurate while making the status correction.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-82bea3bf81f0461318ba' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-82bea3bf81f0461318ba-guide-2','ds-guide-planning','post:ds-starter-82bea3bf81f0461318ba',NULL,'Prepared guide answer: Return to My plan and check the course status and progress display. Finished work should no longer be counted from that personal completion entry after you change it back. Save the updated plan to your account if you want the correction available when you return elsewhere. If the original entry also contained an incorrect grade or date, edit those facts deliberately rather than using deletion as a shortcut.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-82bea3bf81f0461318ba' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-861038d8e838d84fd8d9','ds-guide-planning','school:general','question','I do better with papers than timed exams. How should that affect course choices?','Example situation: I understand material better when I can explain it in writing, but timed exams make me anxious and often do not show my strongest work. I want a degree plan that fits that preference while still being academically useful. I am also conscious that papers can take longer to grade. How do I compare assessment style, speed, and price rather than choosing only the course advertised as easiest?','https://degreesteps.com/guides/compare-transfer-credit-sources/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-861038d8e838d84fd8d9-guide-1','ds-guide-courses','post:ds-starter-861038d8e838d84fd8d9',NULL,'Prepared guide answer: Compare exact course assessments, not only provider names. Use the course library to look for writing, project, or exam information, then check which of those options actually fills a requirement in your plan. A course with no final exam may still require substantial work. Your preference is useful because the cheapest subscription or shortest advertised course is not automatically the best fit for how you demonstrate learning.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-861038d8e838d84fd8d9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-861038d8e838d84fd8d9-guide-2','ds-guide-momentum','post:ds-starter-861038d8e838d84fd8d9',NULL,'Prepared guide answer: Include feedback and revision time when comparing paid months. A writing course that suits you may be more manageable even if its calendar duration is longer than an exam-based option. Keep a realistic workload around your job or family commitments, and avoid starting several writing-heavy courses together without considering the total assignments. If an accommodation is needed, treat that as a separate support step rather than assuming a course label provides it.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-861038d8e838d84fd8d9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8984b333f4c84c16fb26','ds-guide-planning','school:general','question','My plan has only a few courses left. Why might my graduation date still be uncertain?','Example situation: I would like to finish by next summer. After considering transfer credit, the remaining number of courses looks small enough, but I worry that I am overlooking prerequisites or courses offered only in certain terms. I do not need a guaranteed date; I need to know which parts of the schedule could realistically change it. What should I inspect before I tell my employer or family that summer is achievable?','https://degreesteps.com/plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8984b333f4c84c16fb26-guide-1','ds-guide-planning','post:ds-starter-8984b333f4c84c16fb26',NULL,'Prepared guide answer: Look at the actual university sequence in My plan, not only the number of remaining credits. Identify prerequisites, courses that require earlier completed work, capstones, and any required practical experience. Outside-course completion time is only one part of the calendar. A small remaining ledger can still span multiple terms when its requirements cannot be taken together or a needed course is not available at the right time.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8984b333f4c84c16fb26' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8984b333f4c84c16fb26-guide-2','ds-guide-momentum','post:ds-starter-8984b333f4c84c16fb26',NULL,'Prepared guide answer: Build the target date around the slowest required step, then leave a backup scenario for grading, revisions, or a later course offering. Use your checklist to track the next decision that could change the schedule. Keep cost estimates and calendar assumptions labeled separately. You can communicate a working target to your employer while explaining which specific course or enrollment milestone will determine whether that target holds.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8984b333f4c84c16fb26' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-899d55d8b69e95e28e8f','ds-guide-planning','school:general','question','I already work in IT. How do I compare transfer courses, certifications, and competency-based study?','Example situation: I have worked in IT support for years and hold a couple of certifications, but I never finished college. I am considering a competency-based degree and am unsure which learning should be reviewed for transfer versus demonstrated inside the university. I do not want to pay for unrelated courses simply because they are cheap. What should I bring into the comparison before choosing a route?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-899d55d8b69e95e28e8f-guide-1','ds-guide-transfers','post:ds-starter-899d55d8b69e95e28e8f',NULL,'Prepared guide answer: Begin with original college courses and any relevant credential records, including issuer, exact certification, award date, and expiration where applicable. An existing certification, a university assessment, and a certification earned within a degree are different routes. Compare supported uses against the exact program rather than assuming all IT experience produces credit. Keep your work knowledge as useful preparation without converting years of employment into an invented transfer total.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-899d55d8b69e95e28e8f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-899d55d8b69e95e28e8f-guide-2','ds-guide-careers','post:ds-starter-899d55d8b69e95e28e8f',NULL,'Prepared guide answer: Then compare the university competencies still left with the outside courses you would have to purchase. A familiar topic may make an assessment more manageable, but the program’s requirements and support still matter. Avoid buying a certificate that is already included in the degree or one whose receiving use is unsupported. The useful next step is identifying the exact remaining gap, not collecting every credential in a popular spreadsheet.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-899d55d8b69e95e28e8f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8a621dc93b01de1f9c09','ds-guide-planning','school:wgu','question','Can my existing IT certifications replace WGU courses?','Example situation: I already hold an IT certification and would like to use it in a WGU technology degree. Community spreadsheets list many credentials, but the names and versions are confusing. Should I simply add my certification as a completed course? I want the platform to recognize valuable existing work without implying that every credential with a familiar name receives the same award in every program.','https://degreesteps.com/degree-plans/wgu-cybersecurity-and-information-assurance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8a621dc93b01de1f9c09-guide-1','ds-guide-careers','post:ds-starter-8a621dc93b01de1f9c09',NULL,'Preserve the credential as its own record, including the issuer, exact title, version or exam identity, award date, and current status. A credential receiving rule is not yet proof that your particular record satisfies it. DegreeSteps currently retains specific certification leads for research rather than executable credential placements. It should not convert every credential named in a spreadsheet into an automatic WGU award or a completed requirement row.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8a621dc93b01de1f9c09' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8a621dc93b01de1f9c09-guide-2','ds-guide-transfers','post:ds-starter-8a621dc93b01de1f9c09',NULL,'Compare the exact destination program and rule before deciding to earn or renew a credential for transfer. A certification may still be valuable for work even when it does not reduce this degree. For an existing credential, collecting the precise record is the useful next step. For a new purchase, wait for a supported placement and compare the credential''s complete cost and workload with the other legitimate options for that requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8a621dc93b01de1f9c09' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8ae32fcc33a91f7d6b72','ds-guide-planning','course:upi-study-upis-0025','question','Why does UPI Environmental Science show one ACE credit when another description says three?','Example situation: I’m considering Environmental Science and noticed that its credit descriptions can show different amounts. A general catalog description might look like a typical three-credit science course, but the exact ACE record used in DegreeSteps shows one credit. Which amount belongs in my original course collection? I want to understand how ACE, NCCRS and the university’s own award can differ without changing the number just to fill a larger science requirement in my plan.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8ae32fcc33a91f7d6b72-guide-1','ds-guide-courses','post:ds-starter-8ae32fcc33a91f7d6b72',NULL,'For the reviewed ACE route, preserve the one semester credit established by the exact Environmental Science exhibit. The provider also describes a three-credit NCCRS recommendation, which is a separate claim and needs its own independently reviewed evidence. A general course-card default cannot turn the ACE amount into three credits. Keep the recommendation basis visible with the original quantity so the degree matcher evaluates the actual record you intend to obtain.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8ae32fcc33a91f7d6b72' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8ae32fcc33a91f7d6b72-guide-2','ds-guide-transfers','post:ds-starter-8ae32fcc33a91f7d6b72',NULL,'Read the receiving-school award separately. If a university publishes a different receiving quantity, the plan needs to retain that exact award evidence and show how it applies, rather than rewriting the source record. A one-credit source course should not silently complete an unsupported three-credit requirement. If the required allocation is not established, keep the course as a saved option and use a supported alternative for the larger requirement while the research is resolved.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8ae32fcc33a91f7d6b72' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8b07f74524dd689f45c9','ds-guide-planning','school:general','question','Should I finish another transfer course or get my application and transcripts in first?','Example situation: I have a target university start date and a few weeks left before the application deadline. There is also one outside course I could try to finish, but I am not sure whether its final grade and transcript would arrive in time. I do not want to miss the start date just to add a small amount of credit. How should I order these tasks in the plan?','https://degreesteps.com/plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8b07f74524dd689f45c9-guide-1','ds-guide-planning','post:ds-starter-8b07f74524dd689f45c9',NULL,'Prepared guide answer: List the separate dates for admission, transfer-record submission, evaluation, registration, and the course’s assessment and grading steps. A flexible provider schedule does not change a university’s deadlines. In My plan, put the earliest consequential task first and identify which steps depend on completed documents. Finishing a course and having its official result available for the receiving process are different milestones, so leave time for both.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8b07f74524dd689f45c9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8b07f74524dd689f45c9-guide-2','ds-guide-transfers','post:ds-starter-8b07f74524dd689f45c9',NULL,'Prepared guide answer: Compare the value of the additional course with the consequences of delaying the university start. If the timing is tight, keep an alternative scenario that begins without that new transfer award. Do not mark the course finished before assessment or assume an expedited transcript. A practical next action is completing a required application or record request that protects your options, while keeping the optional course decision visible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8b07f74524dd689f45c9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8b72001e7980cf60f4a3','ds-guide-planning','course:straighterline-dc85139a52ba417213','question','What should I plan before pausing a course membership during a busy month?','Example situation: My work schedule may change halfway through the month, so I want to understand how a pause would affect an outside course. I’m considering starting Introduction to Business, but I don’t want my degree plan to assume uninterrupted access or an automatic completion date. Which parts of the provider’s terms should I record, and how should I keep a paused course visible without confusing it with a finished course or losing the progress I have already made?','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8b72001e7980cf60f4a3-guide-1','ds-guide-courses','post:ds-starter-8b72001e7980cf60f4a3',NULL,'Review the current membership and course-access terms before starting, including billing dates, pause or cancellation rules, and any limits on assessment attempts or access after cancellation. Keep those product conditions separate from the academic course record. Your degree plan can retain an in-progress course during a study break, but a proposed completion date should remain your scheduling assumption rather than a guarantee that access or assessment availability continues unchanged.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8b72001e7980cf60f4a3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8b72001e7980cf60f4a3-guide-2','ds-guide-momentum','post:ds-starter-8b72001e7980cf60f4a3',NULL,'Give the course a clear next action for your return, such as the next unfinished module or an assessment you are eligible to attempt. Keep the original provider identity and any actual completed work in your notes. Before restarting a paid period, check the open requirements the course still supports and the time you realistically have available. This turns a pause into an understandable planning decision instead of an accidental duplicate enrollment or hidden recurring cost.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8b72001e7980cf60f4a3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8da57de3b92d9d83ce82','ds-guide-money','school:general','question','I have an old college balance and need my records. Can I still plan?','Example situation: I left a college with an unpaid balance and have not requested a transcript in years. I am unsure what documents I can obtain now and do not want to guess about current transcript-release rules. I would like to explore finishing somewhere else before making another large commitment. What can I do in DegreeSteps while I find out how to get the original academic record?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8da57de3b92d9d83ce82-guide-1','ds-guide-transfers','post:ds-starter-8da57de3b92d9d83ce82',NULL,'Prepared guide answer: You can explore degree goals and start a provisional inventory without marking remembered coursework as confirmed credit. Keep any records you already possess, such as an unofficial transcript, labeled accurately. Ask the original institution for its current transcript-request process and the options that apply to your record. That is a specific document task; the degree plan should not invent a credit award or assume a particular release outcome.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8da57de3b92d9d83ce82' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8da57de3b92d9d83ce82-guide-2','ds-guide-money','post:ds-starter-8da57de3b92d9d83ce82',NULL,'Prepared guide answer: Hold purchases for likely duplicate subjects until you know what the earlier record contains. Use the time to compare format, remaining university costs, and realistic study capacity instead. Keep personal account balances or identifying documents out of public community posts. Once you obtain a usable course record, review the import and compare its actual applicability. Planning provisionally can help you avoid a second expensive commitment while the document question is resolved.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8da57de3b92d9d83ce82' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8e03670d8e8705f32eeb','ds-guide-planning','school:wgu','question','Can outside courses replace the WGU capstone if I have enough transfer credit?','Example situation: I am considering WGU Business Management and trying to understand the university work that must remain. Could enough outside courses replace the capstone or count toward the active program requirement? I want a plan that maximizes sensible transfer without pretending that the minimum WGU coursework is just whatever happens to be left after filling the largest possible outside credit basket.','https://degreesteps.com/degree-plans/wgu-business-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8e03670d8e8705f32eeb-guide-1','ds-guide-transfers','post:ds-starter-8e03670d8e8705f32eeb',NULL,'The reviewed Business Management model preserves the required WGU capstone rather than replacing it with an outside project. Its current residency interpretation requires twenty five percent of the degree''s competency units earned within the active WGU program in addition to the required capstone. Prior WGU coursework or transferred credentials do not automatically become active program residency. The plan needs that rule as well as the overall transfer ceiling.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8e03670d8e8705f32eeb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8e03670d8e8705f32eeb-guide-2','ds-guide-planning','post:ds-starter-8e03670d8e8705f32eeb',NULL,'Keep those university obligations visible while comparing outside options. Reaching the transfer ceiling on paper does not authorize removing a named institution requirement, and each degree must use its own actual curriculum. Price and schedule the remaining WGU work as a complete set, including the capstone where required. This makes the final stage understandable and keeps the optimization aimed at a degree you can actually finish under its governing rules.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8e03670d8e8705f32eeb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-8e7a34894bbd6ebb19c2','ds-guide-planning','course:studycom-plan-sdcm0244','question','English 104, 105 and 204 appear as alternatives. Do I need all of them?','Example situation: I’m reading a shared degree spreadsheet that lists several Study.com English courses beside one composition requirement. I’m unsure whether the row means choose one, complete a sequence, or take enough courses to build a larger credit total. The course numbers do not make the answer obvious. How should DegreeSteps show these choices so I can select a valid composition route without accidentally signing up for multiple alternatives that satisfy the same requirement?','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8e7a34894bbd6ebb19c2-guide-1','ds-guide-courses','post:ds-starter-8e7a34894bbd6ebb19c2',NULL,'Look for an explicit choice within the degree requirement rather than treating every listed course as another task. When an agreement accepts alternative source courses for one receiving composition course, you normally choose the supported option you plan to complete. The actual agreement determines that relationship. A spreadsheet cell containing several names is a research lead until its alternatives, dates and receiving award have been checked against the exact program.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8e7a34894bbd6ebb19c2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-8e7a34894bbd6ebb19c2-guide-2','ds-guide-transfers','post:ds-starter-8e7a34894bbd6ebb19c2',NULL,'Keep the provider’s course identifier with your selection, because English course titles and versions can be similar. DegreeSteps should preserve one composition requirement and show its eligible alternatives inside that row. If the published route instead requires two separate courses, the plan should represent the required sequence or bundle explicitly. The result should make the work clear while preventing several alternative courses from all being counted toward the same receiving award.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-8e7a34894bbd6ebb19c2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-90be680ebeb98e38bd58','ds-guide-planning','course:clep-d6e1052076e8654e82','question','Are College Composition and College Composition Modular interchangeable?','Example situation: I’m comparing CLEP composition exams and their names look similar enough that I could easily choose the wrong one. My target degree has a first writing requirement, and I’m unsure whether an exam with a modular title follows the same essay or receiving-credit rules. What should I look at before selecting an exam? I would like the plan to identify the exact route rather than treating two composition-related exams as interchangeable simply because they appear in the same subject area.','https://degreesteps.com/courses.html?provider=CLEP',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-90be680ebeb98e38bd58-guide-1','ds-guide-courses','post:ds-starter-90be680ebeb98e38bd58',NULL,'Keep the exact exam title and identifier with the plan option. College Composition and College Composition Modular are distinct exams, and the receiving institution’s rule may address their components or additional writing requirements differently. Use the supported award for the actual exam you intend to take. A similar name or the word composition cannot establish that both exams satisfy the same degree requirement with the same score threshold or credit amount.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-90be680ebeb98e38bd58' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-90be680ebeb98e38bd58-guide-2','ds-guide-transfers','post:ds-starter-90be680ebeb98e38bd58',NULL,'Compare the intended exam with the specific composition row before scheduling it. If the route requires another essay, course or evaluation step, keep that step visible in the checklist and cost scenario. Retain the original score report after testing, then record the receiving award separately. That makes a later school comparison much easier, because the new program can evaluate the real exam identity instead of inheriting an overly broad label from the first plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-90be680ebeb98e38bd58' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-964016292b04e8bf39ed','ds-guide-planning','school:umpi','question','Will a UMPI accounting minor qualify me for accounting licensure?','Example situation: The Accounting minor in UMPI Liberal Studies looks like a useful way to focus my bachelor degree. I am also curious about professional accounting roles and may eventually want a credential. Does choosing that minor establish the same preparation as a full accounting major? I want to use an accelerated route where it makes sense without confusing an affordable degree with a separate professional eligibility requirement.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-964016292b04e8bf39ed-guide-1','ds-guide-careers','post:ds-starter-964016292b04e8bf39ed',NULL,'Keep the exact degree and minor name visible in the comparison. A BLS with an Accounting minor is not automatically interchangeable with an Accounting BA, a business accounting program, or a licensing pathway. The reviewed UMPI pages link distinct offerings, and their titles do not establish identical content or professional eligibility. Start with the role you want and identify any formal education requirement as its own constraint.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-964016292b04e8bf39ed' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-964016292b04e8bf39ed-guide-2','ds-guide-planning','post:ds-starter-964016292b04e8bf39ed',NULL,'If your immediate goal is general business work, a minor may be useful in a different way from a license oriented program. If a regulated credential is central, bring the actual jurisdiction''s requirements into the degree comparison before selecting outside courses. That can change which program is appropriate, not merely how quickly you can finish it. A good plan makes that distinction early so speed does not lead you toward the wrong destination.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-964016292b04e8bf39ed' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-96bbbb2326960f900742','ds-guide-planning','school:umpi','question','How should I budget for UMPI when the price is per session?','Example situation: I am comparing UMPI YourPace with a university that charges per credit. A session price looks appealing because I hope to move quickly, but I work full time and cannot predict exactly how many courses I will finish. How should I build a sensible budget that recognizes the possible advantage without assuming I can complete a degree in the shortest advertised amount of time?','https://www.umpi.edu/yourpace/tuition/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-96bbbb2326960f900742-guide-1','ds-guide-money','post:ds-starter-96bbbb2326960f900742',NULL,'The reviewed 2026–2027 YourPace undergraduate rate is $1,800 per eight week session. That is a sourced billing unit, not a guaranteed degree total or a promise about your pace. Compare several feasible session counts using your remaining work and available study time. Include the outside coursework and any other stated charges separately rather than treating one session price as the cost of the entire route.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-96bbbb2326960f900742' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-96bbbb2326960f900742-guide-2','ds-guide-momentum','post:ds-starter-96bbbb2326960f900742',NULL,'Give yourself a slower scenario as well as an ambitious one. If a plan only wins financially when every course goes perfectly, that is useful information before enrolling. Your first actual session can help refine later estimates, but it cannot retroactively make an unrealistic upfront assumption safe. Choose a route that still works for your household if progress is steadier than you hoped, while preserving the upside of accelerating.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-96bbbb2326960f900742' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-98679a5276cf862d9f7c','ds-guide-planning','school:wgu','question','Will a Study.com offer change which WGU courses the plan recommends?','Example situation: I see a Study.com offer while looking at an outside option for WGU. I appreciate discounts, but I do not want a promotion to make the platform recommend a course that is a worse academic or financial fit. Does opening the offer change my selected course or estimate? I want the plan to stay based on my degree requirements and preferences rather than the advertiser.','https://degreesteps.com/degree-plans/wgu-marketing/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-98679a5276cf862d9f7c-guide-1','ds-guide-money','post:ds-starter-98679a5276cf862d9f7c',NULL,'The course match and the offer are separate decisions. Opening the provider offer does not select a course, alter its original credits, mark it completed, or rewrite the plan cost. The reviewed Study offer distinguishes college plans from test preparation and has eligibility conditions. DegreeSteps should show those terms accurately rather than imply that every visitor receives a special negotiated discount or that every advertised offer applies to this coursework.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-98679a5276cf862d9f7c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-98679a5276cf862d9f7c-guide-2','ds-guide-courses','post:ds-starter-98679a5276cf862d9f7c',NULL,'Compare the course on its own merits first: supported requirement placement, assessment, workload, and complete cost. If the offer applies to the plan you actually need, treat it as a possible budget adjustment with the renewal terms visible. Do not choose a duplicate or unsupported course because the promotion looks attractive. A useful offer makes an already sensible route cheaper; it does not establish academic applicability or replace a realistic billing timeline.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-98679a5276cf862d9f7c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-9941640a41a8f08cbdbc','ds-guide-planning','course:upi-study-upis-0003','question','How should I compare UPI’s proctored statistics final with an unproctored alternative?','Example situation: I’m choosing a statistics route and want to compare more than course prices. UPI is self-paced, but I understand that its reviewed non-laboratory courses have a proctored final. Another provider may offer an unproctored route for the same receiving requirement. How should I make that choice? I’m comfortable with independent study, but I want the actual assessment conditions and device needs to be clear before I save an option as my intended next course.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-9941640a41a8f08cbdbc-guide-1','ds-guide-courses','post:ds-starter-9941640a41a8f08cbdbc',NULL,'Keep pace and assessment format as separate preferences. The current UPI assessment review describes an AI-proctored final for the listed non-laboratory courses, including this statistics offering. Self-paced access does not change that exam condition. Compare the exact supported source options for your degree requirement, and use the assessment filters to keep only formats you are willing to complete. The source evidence should explain the classification rather than leaving you to infer it from a provider’s reputation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-9941640a41a8f08cbdbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-9941640a41a8f08cbdbc-guide-2','ds-guide-transfers','post:ds-starter-9941640a41a8f08cbdbc',NULL,'Read identity and equipment conditions for the alternative as well. A reviewed unproctored Study.com credit route still has identity-verification and device requirements, so the comparison should include those practical details. If both options fit the degree, weigh the complete eligible costs and your preferred assessment process. Keep the selected course attached to the requirement, leaving the other saved as an alternative rather than treating two statistics choices as additional degree credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-9941640a41a8f08cbdbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-998bada43e5993903778','ds-guide-planning','school:liberty','question','How do I choose when the cheapest Liberty route is not the fastest?','Example situation: My budget is tight, but I also need to finish a degree soon to qualify for a promotion. I am comparing a lower cost outside course with a more expensive option that seems to fit my schedule better. How should I decide? I do not want a plan that saves a little tuition but adds months because the workload or assessment format is wrong for me.','https://degreesteps.com/degree-plans/liberty-business-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-998bada43e5993903778-guide-1','ds-guide-money','post:ds-starter-998bada43e5993903778',NULL,'First make sure both options satisfy the same open requirement in your exact plan. Then compare total price, expected workload, assessment style, and any sequencing dependency. A cheaper subscription is not cheaper if it stays open unused, and a faster advertised course is not useful if you cannot work at that pace. Put your available weekly hours beside the course choice instead of treating speed as a provider promise.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-998bada43e5993903778' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-998bada43e5993903778-guide-2','ds-guide-momentum','post:ds-starter-998bada43e5993903778',NULL,'Choose the tradeoff deliberately for the requirement that matters next. If one course unlocks later work, timing may outweigh a small price difference; if the work can wait, cost may matter more. Keep the estimate as a range and review it after your first course. The plan should respond to how you actually study, while keeping the remaining university obligations and your promotion deadline visible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-998bada43e5993903778' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-99cf8e0f3ee9fedf1a29','ds-guide-planning','school:tesu','question','Is Liberal Studies automatically the fastest TESU degree for my old credits?','Example situation: I mainly need a recognized bachelor degree for roles that do not specify a major. People often suggest Liberal Studies because it sounds flexible. I have a mixed transcript with business, humanities, and science courses. Should I choose that degree immediately, or compare it with a more specific TESU major? I want to use my existing work rather than guess from the degree name.','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-99cf8e0f3ee9fedf1a29-guide-1','ds-guide-transfers','post:ds-starter-99cf8e0f3ee9fedf1a29',NULL,'Flexibility is worth investigating, but it is not an individual audit. Keep the original courses together and compare how the actual degree structures use them. A broad degree can still have distribution, level, and institution requirements that your transcript does not yet satisfy. A specific major may fit your existing credits unusually well. The best route depends on the remaining requirements, not whether the title sounds flexible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-99cf8e0f3ee9fedf1a29' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-99cf8e0f3ee9fedf1a29-guide-2','ds-guide-careers','post:ds-starter-99cf8e0f3ee9fedf1a29',NULL,'Include your intended job requirements in that comparison. If the employer simply requests a bachelor degree, speed and total remaining cost may dominate; if it requests a field, the major becomes a real constraint. TESU''s modeled options can support that investigation, but they are not currently published as fully ready templates. Use the official curriculum as the reference while DegreeSteps closes the exact outside placement gaps.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-99cf8e0f3ee9fedf1a29' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-99fa905e6ad6bed0bfb4','ds-guide-planning','school:liberty','question','Should I subscribe to several providers at the same time?','Example situation: My Liberty plan shows useful courses from more than one provider. I like having choices, but several monthly memberships could erase the savings if I move slowly. How should I organize the order of the outside courses? I want to avoid paying for subscriptions while waiting on a prerequisite, a transcript, or a final decision about which course fills a requirement.','https://degreesteps.com/degree-plans/liberty-healthcare-administration-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-99fa905e6ad6bed0bfb4-guide-1','ds-guide-money','post:ds-starter-99fa905e6ad6bed0bfb4',NULL,'Group the selected courses by provider and check any prerequisite or assessment sequence before starting the billing clock. Then make a short list of courses you can realistically begin now. A supported transfer match answers where credit may fit; it does not make two overlapping subscriptions a good purchase. Keep any unresolved alternatives outside the paid basket until the exact choice is ready to use.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-99fa905e6ad6bed0bfb4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-99fa905e6ad6bed0bfb4-guide-2','ds-guide-momentum','post:ds-starter-99fa905e6ad6bed0bfb4',NULL,'Build your budget around an achievable pace rather than the advertised minimum time. Finish a useful block, arrange its transcript, and review the next provider before renewing or opening another account. Include exam, transcript, and other stated charges when comparing options. A slightly higher course price can still be sensible if it avoids an unused month of membership or fits the hours you actually have available.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-99fa905e6ad6bed0bfb4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-9f94abd8e99b199cd264','ds-guide-planning','school:tesu','question','Can I transfer 105 credits to TESU using only alternative providers?','Example situation: I see a large overall transfer allowance for TESU and want to use inexpensive alternative courses for almost the whole degree. Does the overall limit mean the same thing as the allowance for ACE recommended coursework? I am trying to choose my first provider courses and do not want to discover late in the plan that two different transfer rules were being combined.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-accounting/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-9f94abd8e99b199cd264-guide-1','ds-guide-transfers','post:ds-starter-9f94abd8e99b199cd264',NULL,'The reviewed TESU models keep those limits separate. In the six modeled routes, the degree total is 120 semester credits, the standard institutional minimum is 15, and the combined alternative credit cap is 90. The larger overall outside credit allowance is not permission to fill that entire amount with alternative coursework. College coursework and alternative sources need to retain their distinct origins in the plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-9f94abd8e99b199cd264' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-9f94abd8e99b199cd264-guide-2','ds-guide-planning','post:ds-starter-9f94abd8e99b199cd264',NULL,'Build the first audit from your actual records, then look at which remaining requirements can use each source type. If alternative coursework reaches its limit, another inexpensive provider elective may add no degree progress. You may still have room for eligible college transfer work, but its applicability needs its own evidence. The useful number is the remaining requirement coverage under both limits, rather than the largest transfer headline.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-9f94abd8e99b199cd264' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a05ac98fd45cb7f26d7f','ds-guide-planning','school:general','question','I have been out of school for twenty years. Where do I even start?','Example situation: I left college when my children were young and have not written an academic paper in a long time. I probably have thirty or forty credits, but I do not know which ones still matter. The idea of finishing is exciting and embarrassing at the same time because I feel behind. What is the smallest useful step before I pick a school or pay for anything?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a05ac98fd45cb7f26d7f-guide-1','ds-guide-transfers','post:ds-starter-a05ac98fd45cb7f26d7f',NULL,'Prepared guide answer: Begin with a course inventory, not a promise about a graduation date. Request records from the colleges you attended and use My courses to review a transcript upload or spreadsheet import. Preserve the original course codes, grades, units, and dates. You can explore while records are arriving, but an approximate credit total should stay an estimate rather than a claim that specific degree requirements are complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a05ac98fd45cb7f26d7f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a05ac98fd45cb7f26d7f-guide-2','ds-guide-momentum','post:ds-starter-a05ac98fd45cb7f26d7f',NULL,'Prepared guide answer: Choose one practical task for this week: locate a transcript account, download the course template, or identify two degrees worth comparing. You do not have to solve the entire degree at once. When considering your first new course, look at its actual writing, exam, and grading requirements. A manageable restart can build confidence while producing useful work, rather than becoming another expensive abandoned enrollment.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a05ac98fd45cb7f26d7f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a22eab5cbc8248c8f94b','ds-guide-planning','school:umpi','question','Why does the original source matter if two courses have the same subject?','Example situation: I have a community college psychology course and am also considering an inexpensive provider psychology course. A friend says credits are credits once a university accepts them. Is that enough for UMPI planning, or does it matter where the course originated? I want the import process to keep the important differences without making me type academic details I do not understand one course at a time.','https://www.umpi.edu/academics/general-education-curriculum/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a22eab5cbc8248c8f94b-guide-1','ds-guide-courses','post:ds-starter-a22eab5cbc8248c8f94b',NULL,'Preserve the issuing source and original course identity. A college course and an ACE or NCCRS recommended provider course can be evaluated under different rules even when their subjects look similar. The record also needs its original credit amount and completion details. A transcript upload or the course spreadsheet is useful because it can keep those facts together without pretending that a subject title determines the award.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a22eab5cbc8248c8f94b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a22eab5cbc8248c8f94b-guide-2','ds-guide-transfers','post:ds-starter-a22eab5cbc8248c8f94b',NULL,'Compare applicability after the records are collected, not while rewriting them into guessed university equivalents. That prevents the audit from losing information needed for source limits, duplication checks, or a later school comparison. If both courses already exist, keep both records but do not count overlapping content twice. If neither is taken yet, choose only after a supported placement shows which open requirement the course would actually advance.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a22eab5cbc8248c8f94b' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a39b98fbf04153740122','ds-guide-planning','school:liberty','question','Can two English courses with different titles still duplicate each other?','Example situation: I completed English composition at a community college and saved a provider course with a different writing title. I assumed different titles meant both would count somewhere in my Liberty plan. How do I avoid repeating content or filling the same requirement twice? I would rather spend my limited study time on a genuinely open row than discover duplication after finishing another course.','https://degreesteps.com/degree-plans/liberty-history-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a39b98fbf04153740122-guide-1','ds-guide-courses','post:ds-starter-a39b98fbf04153740122',NULL,'Compare the receiving awards and requirement placements, not just the source titles. Two courses from different places may lead to the same university equivalent or duplicate content. Keep both original records in your collection if both are completed, but use each course only where the degree rules allow it. A second matching title does not automatically become an extra elective or another completed requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a39b98fbf04153740122' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a39b98fbf04153740122-guide-2','ds-guide-momentum','post:ds-starter-a39b98fbf04153740122',NULL,'Before starting the saved writing course, check whether your completed course already covers that row. If it does, choose a different open requirement with an established match. If the records are incomplete, collect the transcript detail that distinguishes the courses rather than guessing from the name. This small check often saves more time than racing through another inexpensive class simply because it appears in a provider catalog.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a39b98fbf04153740122' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a58327d48eba058d4f94','ds-guide-planning','school:general','question','Would a fast psychology degree help if I eventually want to work as a counselor?','Example situation: I am interested in counseling and would like to start with a psychology bachelor’s degree. I know there may be graduate education and supervised experience later, but I am not clear about the stages. I want to reduce undergraduate costs without confusing a degree title with permission to practice. What should be included in my first degree plan so I keep the longer-term career goal realistic?','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a58327d48eba058d4f94-guide-1','ds-guide-careers','post:ds-starter-a58327d48eba058d4f94',NULL,'Prepared guide answer: Use the bachelor’s comparison to evaluate applicable transfer courses and the university coursework left, then keep the intended counseling role as a separate career pathway. A psychology bachelor’s does not by itself establish professional practice eligibility. Identify the kind of graduate program you may need and the published undergraduate preparation it expects. That helps you compare accelerated options against the next academic stage rather than against a degree title alone.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a58327d48eba058d4f94' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a58327d48eba058d4f94-guide-2','ds-guide-planning','post:ds-starter-a58327d48eba058d4f94',NULL,'Prepared guide answer: Save any specific graduate prerequisites and relevant practical experience goals beside your undergraduate choices. If two bachelor’s plans cost about the same, the one that provides better preparation may be more useful than the one with the highest transfer percentage. Avoid selecting extra courses simply because they sound clinical. Keep licensing, supervised work, and admission requirements tied to the actual role and location you intend to pursue.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a58327d48eba058d4f94' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a65c1d04fec809214e17','ds-guide-planning','school:wgu','question','Will transferring one more WGU course always save tuition?','Example situation: I want to use every sensible outside course before WGU, but I am not sure how to calculate the savings. The university bills by term, so removing one course does not look the same as subtracting a per credit tuition price. How should I decide whether another outside class is worth the time and money when it might not change how many terms I need?','https://degreesteps.com/degree-plans/wgu-marketing/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a65c1d04fec809214e17-guide-1','ds-guide-money','post:ds-starter-a65c1d04fec809214e17',NULL,'Separate reduced workload from reduced billed terms. A supported outside course can remove a WGU requirement, but that does not mechanically subtract a per credit tuition charge from a term based bill. The reviewed pace model uses six month terms, with program specific tuition. Compare feasible term scenarios after applying the outside coursework, rather than assigning every transferred competency unit a guaranteed dollar saving of its own.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a65c1d04fec809214e17' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a65c1d04fec809214e17-guide-2','ds-guide-planning','post:ds-starter-a65c1d04fec809214e17',NULL,'Include the provider''s complete price and the time it delays or helps your start. An extra course may be worthwhile because it makes the remaining workload manageable, even if the term estimate stays the same. It may be less useful if it adds cost without changing your likely schedule. Keep those tradeoffs visible so the plan can maximize useful progress instead of promising a tuition reduction for every additional transfer.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a65c1d04fec809214e17' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-a670de95750f46dd6b59','ds-guide-planning','school:general','question','If I need to pause for a few months, will I have to rebuild my plan later?','Example situation: I am making progress, but a family expense may mean pausing new courses for several months. I do not want to lose my course collection or forget why I chose the current degree. I also know policies and course options could change before I return. How should I leave the plan in a useful state now so restarting is easier and I do not keep paying unnecessarily?','https://degreesteps.com/account.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a670de95750f46dd6b59-guide-1','ds-guide-planning','post:ds-starter-a670de95750f46dd6b59',NULL,'Prepared guide answer: Save the plan in your account and keep the course collection accurate: finished work stays finished, current work stays in progress, and future choices remain unstarted. Record any important next tasks or reasons for choosing the route. Account saving preserves your planning work, while provider memberships have their own billing and access arrangements. Pausing study in a plan should not be assumed to cancel a separate provider subscription.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a670de95750f46dd6b59' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-a670de95750f46dd6b59-guide-2','ds-guide-money','post:ds-starter-a670de95750f46dd6b59',NULL,'Prepared guide answer: Before stepping away, review recurring charges and download any records you are entitled to retain from completed work. When you return, reopen the saved plan and review changes affecting its exact program and courses before buying anything new. Your original completions should remain intact even if the proposed future route changes. The restart task is checking what is different, not recreating your academic history from memory.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-a670de95750f46dd6b59' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-aaea61d1cb41f351cfbb','ds-guide-planning','school:umpi','question','Does self paced mean I can avoid exams in a YourPace route?','Example situation: I learn well through projects and writing, but timed or proctored exams are difficult for me. YourPace sounds promising because it is self paced. Does that label tell me how the courses assess learning? I would like my degree plan to make assessment expectations clear, including any outside courses, instead of discovering late that a course format does not fit how I can study.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-aaea61d1cb41f351cfbb-guide-1','ds-guide-courses','post:ds-starter-aaea61d1cb41f351cfbb',NULL,'Self paced describes a way of moving through coursework; it does not independently establish the assessment format of every course. Keep university assessments and outside provider assessments separate, and use course specific evidence rather than a broad program label. The reviewed UPI alternatives, for example, include remotely proctored finals despite being self paced. An accessible schedule and an acceptable assessment method are two different preferences worth capturing.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-aaea61d1cb41f351cfbb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-aaea61d1cb41f351cfbb-guide-2','ds-guide-momentum','post:ds-starter-aaea61d1cb41f351cfbb',NULL,'Before committing to a paid route, identify the exact assessment tradeoffs that matter to you and any support arrangements you need. Compare workable alternatives for the same requirement where evidence exists. Do not relabel an entire degree as no proctor based on one favorable course description or a community anecdote. The useful outcome is a route you can complete consistently, with the important assessment obligations visible from the beginning.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-aaea61d1cb41f351cfbb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ab2b9b6102f5e183c66c','ds-guide-planning','course:saylor-plan-saya0023','question','Is a low-cost exam route still best if I prefer a different assessment format?','Example situation: I’m comparing marketing courses and want to save money, but assessment format matters to me as well. An exam-based route might have a low direct charge while a subscription provider offers a different experience. How should I make that tradeoff without treating the cheapest listed fee as the only useful answer? I’m especially interested in keeping the course compatible with my degree while choosing a process I can realistically complete alongside work and family commitments.','https://degreesteps.com/courses.html?provider=Saylor',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ab2b9b6102f5e183c66c-guide-1','ds-guide-money','post:ds-starter-ab2b9b6102f5e183c66c',NULL,'Compare only options that satisfy the intended receiving requirement, then consider the complete cost and assessment process for each. Include eligible product charges, study time, required equipment and current exam conditions. Saylor’s reviewed credit route uses monitoring, so it should not appear as an unproctored alternative simply because its lesson access is flexible. The lowest visible fee may be attractive, but the route also needs to fit your stated learning and assessment preferences.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ab2b9b6102f5e183c66c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ab2b9b6102f5e183c66c-guide-2','ds-guide-transfers','post:ds-starter-ab2b9b6102f5e183c66c',NULL,'Set your priorities explicitly and keep the alternatives saved while you compare. A student with a predictable study schedule may evaluate subscription time differently from someone who can study only occasionally. Another student may choose an acceptable assessment format even when its direct price is higher. The plan should make those consequences visible and preserve academic fit, instead of assuming that every student should use the same provider or finish at the same speed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ab2b9b6102f5e183c66c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ac7357d4460f6b7d25fb','ds-guide-planning','school:liberty','question','Can Christian Leaders coursework replace Liberty religion requirements?','Example situation: Some Liberty plans include religion courses even when the major is not ministry. I have seen Christian Leaders mentioned as an inexpensive route and want to understand where it actually helps. Should I complete those courses before other general education classes, and how do I tell the difference between a promising option and a course that is ready to count in my plan?','https://degreesteps.com/degree-plans/liberty-criminal-justice-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ac7357d4460f6b7d25fb-guide-1','ds-guide-transfers','post:ds-starter-ac7357d4460f6b7d25fb',NULL,'Treat Christian Leaders as a specific source with specific receiving matches, not a blanket substitute for every religion row. DegreeSteps keeps those proposed placements conditional where the evidence does not establish an exact current Liberty award. Start by checking the named requirement and the evidence shown for that particular option. A similar course title or a community success report is useful research, not an awarded equivalency.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ac7357d4460f6b7d25fb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ac7357d4460f6b7d25fb-guide-2','ds-guide-courses','post:ds-starter-ac7357d4460f6b7d25fb',NULL,'If your chosen religion row has a supported alternative, compare its complete workload and transcript process with the university course. If the placement remains conditional, keep it separate from your committed course list and continue with established matches elsewhere. That preserves the potential saving without making the rest of your degree depend on an unresolved claim. DegreeSteps should close that research gap before recommending the purchase.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ac7357d4460f6b7d25fb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ada75096eb061ddfa2ae','ds-guide-military','school:general','question','If a school accepts military benefits, does that include every self-paced program it offers?','Example situation: I am a veteran comparing a regular online program with a competency-based option at the same university. The university advertises military support, and the self-paced format looks attractive because I have experience in the subject. I do not want to calculate savings using benefits that may not cover the exact format. How do I keep the academic comparison and the funding comparison from getting mixed together?','https://degreesteps.com/guides/military-credit-jst-ccaf/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ada75096eb061ddfa2ae-guide-1','ds-guide-military','post:ds-starter-ada75096eb061ddfa2ae',NULL,'Prepared guide answer: Treat funding eligibility as a property of the exact program, format, and benefit, rather than of the university name alone. The military guide explains why accelerated formats can have specific exclusions. Compare academic requirements in the degree plan first, then record the relevant funding terms separately. A university’s general military webpage should not be used to mark every competency-based route as benefit-eligible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ada75096eb061ddfa2ae' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ada75096eb061ddfa2ae-guide-2','ds-guide-money','post:ds-starter-ada75096eb061ddfa2ae',NULL,'Prepared guide answer: Build two clear cost scenarios: the published remaining charges and the amount you would owe after benefits that actually apply. Include any required enrollment level and term structure in the decision. Your military learning may also reduce academic requirements, but a credit award and a funding award are separate. That separation keeps a promising self-paced option from looking cheaper simply because two different types of assistance were assumed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ada75096eb061ddfa2ae' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b05fc1e938374840a2a5','ds-guide-military','course:dsst-plan-dant0037','question','How should military exam funding affect my DSST course choices?','Example situation: I’m a military learner considering a DSST Personal Finance exam, and I would like to use any funding benefit I qualify for. I’m unsure how to separate the funding rules from the university’s credit decision. Should I choose funded exams first, or start with the degree requirements? I want to avoid paying unnecessarily while also avoiding a list of low-cost exams that do not advance the program I actually intend to complete.','https://degreesteps.com/courses.html?provider=DSST',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b05fc1e938374840a2a5-guide-1','ds-guide-military','post:ds-starter-b05fc1e938374840a2a5',NULL,'Start with the degree requirements and the exact exam award, then identify the funding route for the exams that fit. Military eligibility, testing arrangements and any attempt restrictions belong in the financial and scheduling part of the plan. They do not establish the receiving school’s course award. Keep your service and testing situation specific; a benefit available to one learner or attempt should not be assumed to cover every person, examination or retake.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b05fc1e938374840a2a5' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b05fc1e938374840a2a5-guide-2','ds-guide-money','post:ds-starter-b05fc1e938374840a2a5',NULL,'Add the benefit check and any required testing steps before the exam task, using the current official program information applicable to you. Retain the actual score report as the original result and attach any university award separately. Funding and credit can then be reviewed independently if your intended degree changes. This helps you use a legitimate benefit where it advances the plan instead of treating every funded test as automatically useful degree credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b05fc1e938374840a2a5' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b1456776210636b8be23','ds-guide-planning','course:upi-study-upis-0004','question','Does an ACE transcript and a provider’s NCCRS record describe the same credit route?','Example situation: I’m planning my transcript requests and see references to ACE records, Credly badges and provider-issued documents associated with NCCRS recommendations. How should I keep those routes straight for a UPI course that may have more than one recommendation? I want the receiving school to get the required original record, but I don’t want to duplicate the same course in my collection or assume that any document carrying a recommendation automatically proves the same credit amount or degree placement.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b1456776210636b8be23-guide-1','ds-guide-courses','post:ds-starter-b1456776210636b8be23',NULL,'Keep one original learning record for the course, with the recommendation route and issued documents identified accurately. ACE and NCCRS are separate recommendation systems; their records, quantities or dates may differ. A badge or recommendation record is not the university’s degree award. Use the transcript route required for the exact provider course and receiving school, then retain the actual document and course facts instead of creating a second completion for another form of evidence.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b1456776210636b8be23' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b1456776210636b8be23-guide-2','ds-guide-transfers','post:ds-starter-b1456776210636b8be23',NULL,'When the college returns an evaluation, attach that result to the receiving context. Preserve which original record supported it, including the recommendation basis and relevant period. If two documents describe the same completed learning, they should help establish its identity rather than generate twice the credits. This is especially important when comparing institutions, because one school’s treatment of a recommendation or transcript format does not automatically control another school’s decision.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b1456776210636b8be23' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b2210d5280fd00cc1783','ds-guide-planning','school:umpi','question','Is UMPI YourPace the right route if I want a traditional campus experience?','Example situation: I like the idea of an affordable accelerated degree, but I also want to meet classmates, attend events, and feel part of a campus. UMPI has a physical university and a YourPace option, which makes the choices sound related. Can I assume the self paced route gives me the same experience? I want to compare delivery formats without losing sight of why I wanted college in the first place.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b2210d5280fd00cc1783-guide-1','ds-guide-campus','post:ds-starter-b2210d5280fd00cc1783',NULL,'Treat the delivery format as part of the goal, not a small label under the university name. The reviewed YourPace offerings describe a particular learning route; they do not establish the schedule, housing, campus access, or course experience of a residential program. A university having a campus does not make every online degree equivalent to attending it. Compare the actual format you would enroll in before transferring any plan assumptions.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b2210d5280fd00cc1783' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b2210d5280fd00cc1783-guide-2','ds-guide-money','post:ds-starter-b2210d5280fd00cc1783',NULL,'List the experiences that matter most, such as scheduled classes, living nearby, clubs, or attending games, then compare programs that actually offer them. Add living and travel costs where relevant. If campus participation is central, a different school or route may be a better fit even with more university coursework. The savings calculation should support that choice, rather than redefine your goal as online study because it is easier to price.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b2210d5280fd00cc1783' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b2eb78221647f6ab6a54','ds-guide-planning','school:umpi','question','Should I finish outside courses before starting a paid YourPace session?','Example situation: I want to start UMPI soon, but I also want to finish any useful lower cost outside courses first. I am trying to avoid using paid session time on work I could have completed elsewhere. How should I decide when to enroll without assuming that every outside course I collect will transfer or that I can add it at any point in the degree?','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b2eb78221647f6ab6a54-guide-1','ds-guide-planning','post:ds-starter-b2eb78221647f6ab6a54',NULL,'Work backward from a clearly supported remaining curriculum and the applicable transfer process. Outside coursework can reduce university work only when its source is eligible and its receiving placement satisfies the exact degree. The current reviewed UMPI record does not yet provide a finished course basket, so a long provider shopping list is not a substitute for that step. Keep proposed options separate from the courses you have actually completed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b2eb78221647f6ab6a54' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b2eb78221647f6ab6a54-guide-2','ds-guide-momentum','post:ds-starter-b2eb78221647f6ab6a54',NULL,'Create a short timeline with the course completion, official record, evaluation, and intended session start as separate events. Do not assume that finishing a provider course on a certain day makes the university award available that same day. This gives the plan a practical sequence without making an unsupported timing promise. Once the exact route is established, you can choose a start that fits both the paperwork and your study capacity.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b2eb78221647f6ab6a54' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b3b6c9ab9ac5d75c9ef3','ds-guide-planning','school:wgu','question','How do I make a WGU acceleration plan that does not depend on studying all day?','Example situation: I like competency based study because I already know parts of the subject, but stories about finishing extremely quickly make me nervous. I have a job and cannot treat school as a full time sprint. Can I still use outside courses and a WGU plan sensibly? I want an encouraging route with milestones, not a race against strangers whose schedules and backgrounds are completely different from mine.','https://degreesteps.com/degree-plans/wgu-user-experience-design/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b3b6c9ab9ac5d75c9ef3-guide-1','ds-guide-momentum','post:ds-starter-b3b6c9ab9ac5d75c9ef3',NULL,'Start with your existing knowledge and completed coursework, then budget study time honestly for what remains. Competency based progress can be valuable without making every student equally fast. The reviewed WGU pace model uses six month terms and a mentor process for acceleration; it is not an unlimited workload promise or a guaranteed number of terms. A good estimate includes a sustainable pace and a slower scenario alongside any ambitious goal.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b3b6c9ab9ac5d75c9ef3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b3b6c9ab9ac5d75c9ef3-guide-2','ds-guide-money','post:ds-starter-b3b6c9ab9ac5d75c9ef3',NULL,'Choose one concrete next action, such as finishing a useful outside course before enrollment or arranging an official transcript. Keep the full degree visible, but measure weekly progress against the work you can actually do. Revisit the estimate as real performance replaces assumptions. You can benefit from acceleration while choosing a steady routine, and a plan that survives ordinary life is more useful than an impressive timeline you cannot sustain.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b3b6c9ab9ac5d75c9ef3' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b5235e106bf241e53118','ds-guide-money','school:general','question','Are CLEP vouchers worth considering if I would rather avoid exams?','Example situation: I have seen Modern States mentioned as a way to reduce CLEP costs. That sounds helpful because my budget is tight, but I have not taken a timed exam in years and would usually prefer coursework. I do not want to choose an exam only because the price looks good. How should I compare this route with a self-paced course that fills the same requirement?','https://degreesteps.com/credit-sources/modern-states/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b5235e106bf241e53118-guide-1','ds-guide-courses','post:ds-starter-b5235e106bf241e53118',NULL,'Prepared guide answer: Use the Modern States source profile to understand its preparation and voucher role, then compare the specific CLEP exam with supported course alternatives in your degree plan. Preparation material and an exam credit award are different things. Keep the receiving school’s exam policy, required score, and duplicate-credit rules attached to the exact requirement. A voucher opportunity alone does not establish that a degree will use the exam.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b5235e106bf241e53118' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b5235e106bf241e53118-guide-2','ds-guide-money','post:ds-starter-b5235e106bf241e53118',NULL,'Prepared guide answer: Compare the full assessment arrangement as well as the possible saving. Exam preparation, scheduling, and testing conditions may be less attractive to you than assignments spread over time. Current voucher eligibility and any additional testing charges belong in the cost decision. You can choose a more expensive course when its format better fits your circumstances; the point is to make that tradeoff visible rather than treating the lowest headline price as compulsory.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b5235e106bf241e53118' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b5f80d00310aece492a4','ds-guide-planning','course:mapped-352676f14fe44101561e','question','Should I choose a science course for interest, general education or a future major?','Example situation: I’m drawn to Marine Biology, but I’m also considering degrees whose science requirements may be more general or more specialized. How should I decide whether to take an interesting course now or choose one that preserves more degree options? I don’t want to assume that every biology-related class satisfies the same laboratory, prerequisite or major requirement. I’d like a comparison that shows where the course would actually fit before I make it part of my intended route.','https://degreesteps.com/courses.html?provider=ASU%20Universal%20Learner',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b5f80d00310aece492a4-guide-1','ds-guide-courses','post:ds-starter-b5f80d00310aece492a4',NULL,'Compare the exact course against the open science rows in the degrees you are considering. A named major prerequisite, a laboratory requirement and a broad general education choice can allow different courses. The subject being biology is not enough to establish that all three are satisfied. Keep the original course identity and units visible, then use the supported receiving award to understand whether the course has the placement you need for each program.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b5f80d00310aece492a4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b5f80d00310aece492a4-guide-2','ds-guide-careers','post:ds-starter-b5f80d00310aece492a4',NULL,'Your interest still matters when more than one option has a supported fit. A course you are motivated to complete can be a sensible choice, provided the degree comparison makes its consequences clear. Note whether choosing it leaves another required science course open, and include that remaining work in the cost and time scenario. This helps you balance curiosity and progress without treating either the broad subject name or a generic transfer-credit limit as the final answer.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b5f80d00310aece492a4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-b967b5a00da95f6cf9c6','ds-guide-planning','school:general','question','How can I choose courses that work with my screen reader before I pay?','Example situation: I use a screen reader and want to complete a degree online. Course descriptions tell me about subjects and prices, but not always whether assignments, quizzes, documents, or required software will be usable. I would rather ask practical questions early than discover a problem halfway through a membership month. What should I look at while comparing course sources and the university work left in a plan?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b967b5a00da95f6cf9c6-guide-1','ds-guide-courses','post:ds-starter-b967b5a00da95f6cf9c6',NULL,'Prepared guide answer: Use the course library to identify a small number of applicable options, then investigate the actual platform and assessment tools before purchase. Look for accessible sample material, document formats, keyboard navigation, and the tools used for assignments or exams. A self-paced label does not establish accessibility. Keep the receiving university’s required platforms on the same list, because outside-course accessibility covers only part of the degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b967b5a00da95f6cf9c6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-b967b5a00da95f6cf9c6-guide-2','ds-guide-planning','post:ds-starter-b967b5a00da95f6cf9c6',NULL,'Prepared guide answer: Turn the uncertain items into specific questions, such as whether a required diagram has a text alternative or whether an exam tool works with your assistive setup. Save the course ideas while you evaluate them instead of committing to multiple memberships. A practical next step is testing one available sample lesson with your usual tools and recording the barriers, rather than collecting a generic promise that online study is accessible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-b967b5a00da95f6cf9c6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ba5a3abd13eff60a5fc6','ds-guide-planning','course:study-ab6479df1d7311cc0b','question','Can an outside management course replace a university capstone?','Example situation: I’m trying to minimize the courses left at the university and see an outside course with an advanced management title. The university also has a capstone or final business requirement, so I’m wondering whether the subjects could overlap enough to transfer. What should I look for in the plan? I want to maximize legitimate outside coursework while preserving any requirement the university specifically expects me to complete through its own program.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ba5a3abd13eff60a5fc6-guide-1','ds-guide-courses','post:ds-starter-ba5a3abd13eff60a5fc6',NULL,'Check whether the receiving requirement is marked as university coursework or otherwise restricted by a published program rule. A similar title or advanced subject is not enough to replace a capstone. The selected degree’s actual rule controls that decision. Use the outside management course where an exact supported award applies, then leave institution-only requirements in the university section so the plan does not promise an exemption that its evidence does not establish.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ba5a3abd13eff60a5fc6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ba5a3abd13eff60a5fc6-guide-2','ds-guide-transfers','post:ds-starter-ba5a3abd13eff60a5fc6',NULL,'A useful optimization shows both the transfer opportunities and the unavoidable institutional work. Compare the remaining university requirements, their prerequisites and their eligible pricing rather than aiming to make every row an outside course. If you change degree programs, review the capstone rule for that new program as well. Your saved source course remains available, but its usefulness depends on the current degree’s requirements and the receiving institution’s allocation rules.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ba5a3abd13eff60a5fc6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-bb4a4607797f797571c7','ds-guide-planning','school:umpi','question','Can one course satisfy several UMPI general education outcomes?','Example situation: UMPI''s new general education overview lists several outcomes, and some course subjects seem relevant to more than one. If a course fits two outcomes, does it count twice toward the total credits? I want the platform to handle this automatically, but I do not want an attractive looking worksheet that reaches forty credits by reusing the same original course without a rule allowing it.','https://www.umpi.edu/academics/general-education-curriculum/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bb4a4607797f797571c7-guide-1','ds-guide-courses','post:ds-starter-bb4a4607797f797571c7',NULL,'Separate satisfying a category from earning additional credits. A curriculum can permit a course to address more than one outcome without creating another set of original course credits. The reviewed new UMPI overview establishes forty total general education credits and eight outcomes, but it does not establish the exact overlap rules or named transfer placements. DegreeSteps cannot infer those rules simply because a subject appears relevant in two places.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bb4a4607797f797571c7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bb4a4607797f797571c7-guide-2','ds-guide-planning','post:ds-starter-bb4a4607797f797571c7',NULL,'Keep a single original course record and let each destination rule describe how it applies. Do not duplicate the course in your import or increase its credit quantity to make the categories add up. This matters especially when comparing older community sheets with the new curriculum. A sound map needs both the category coverage and the total credit arithmetic to work under the actual rules, with neither standing in for the other.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bb4a4607797f797571c7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-bc1613a6a4fbaba2b4ea','ds-guide-planning','course:study-e5dd2bab7be7a7e124','question','Should I finish my Study.com courses together or alternate providers each week?','Example situation: I’m considering a plan with courses from several providers and would like to keep subscription costs under control. My first instinct is to take whichever course looks most interesting each week, but that could leave multiple paid memberships running at once. How should I organize the plan around my available study time? I want a flexible sequence that accounts for prerequisites and unfinished work rather than just sorting the course list by provider name.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bc1613a6a4fbaba2b4ea-guide-1','ds-guide-courses','post:ds-starter-bc1613a6a4fbaba2b4ea',NULL,'Keep currently eligible courses from the same paid provider together when that fits your prerequisites and study needs. Continue an in-progress course before opening another membership simply to begin a different subject. This can reduce unnecessary overlap, but it is a scheduling strategy rather than a guaranteed number of billed months. Your plan should still show prerequisites, assessment availability and any course-specific workload that affects when you can reasonably move on.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bc1613a6a4fbaba2b4ea' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bc1613a6a4fbaba2b4ea-guide-2','ds-guide-money','post:ds-starter-bc1613a6a4fbaba2b4ea',NULL,'Build a small ready-to-start queue before paying for the next subscription. Check that the selected courses actually fill open degree requirements and that any prior courses have been completed as needed. Use your own weekly study budget as an assumption, then revisit it after you see your pace. A monthly membership is not automatically cheaper than another provider’s course purchase when your available time or assessment needs are different.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bc1613a6a4fbaba2b4ea' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-bca34882646755edfcc7','ds-guide-planning','school:liberty','question','Will changing my psychology concentration waste the courses I picked?','Example situation: I am considering Liberty psychology, but addictions and recovery also interests me. I do not want to lock myself into a concentration before I understand the careers. Can I keep one collection of courses and compare the two degree plans? I need to see which outside courses remain useful and which choices would be specific to the concentration I eventually choose.','https://degreesteps.com/degree-plans/liberty-psychology-addictions-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bca34882646755edfcc7-guide-1','ds-guide-transfers','post:ds-starter-bca34882646755edfcc7',NULL,'Use the published general psychology and addictions and recovery worksheets as separate destinations. Keep the same original course collection in both comparisons. A course can still be useful if it moves from one requirement group to another, but it should not be counted twice inside either degree. Pay particular attention to the concentration rows instead of assuming the shared psychology name makes the requirements identical.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bca34882646755edfcc7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-bca34882646755edfcc7-guide-2','ds-guide-careers','post:ds-starter-bca34882646755edfcc7',NULL,'Separate the academic choice from the career outcome. A psychology bachelor degree is not, by itself, a promise of eligibility to practice in a licensed clinical role. Compare the work you want to do and any later education it requires alongside the course differences. Start with clearly shared requirements while you decide, then choose specialized coursework when the career direction and degree requirements line up.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-bca34882646755edfcc7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-be0d7bd07f054e40f372','ds-guide-planning','school:general','question','How do I plan when my study time disappears every other week?','Example situation: I am a single parent, and my childcare schedule changes with my former partner’s work. Some weeks I could study twelve hours; other weeks I would barely have four. I want to make progress without feeling like one disrupted week ruins the entire degree plan. Would it make more sense to choose individual courses, a monthly membership, or a program with regular deadlines?','https://degreesteps.com/guides/finish-faster-without-wasting-credit/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-be0d7bd07f054e40f372-guide-1','ds-guide-planning','post:ds-starter-be0d7bd07f054e40f372',NULL,'Prepared guide answer: Compare the payment commitment with your less predictable weeks, not only your best weeks. In My plan, separate the outside courses you can take flexibly from university courses with term dates. A monthly membership may be attractive when you can finish several courses, while an individual course may reduce pressure during interruptions. Neither is automatically cheapest for a changing childcare schedule.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-be0d7bd07f054e40f372' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-be0d7bd07f054e40f372-guide-2','ds-guide-momentum','post:ds-starter-be0d7bd07f054e40f372',NULL,'Prepared guide answer: Give your plan two versions of a normal week: one with your usual childcare and one with a disruption. Use the lower number when choosing your next course. Keep a small next action ready, such as one reading or outlining an assignment, so a short session still helps. Avoid adding a second paid provider simply to feel busy during an uneven month.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-be0d7bd07f054e40f372' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c14bbeee72251f86cb1a','ds-guide-planning','school:general','question','Should withdrawn or unfinished classes go into My courses?','Example situation: I started more classes than I finished during a difficult year. My transcript shows completed courses, a withdrawal, and an incomplete that I never resolved. I am worried an upload will make my degree look further along than it really is. At the same time, I would like to remember subjects I studied and might want to take again. How should I separate those situations?','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c14bbeee72251f86cb1a-guide-1','ds-guide-transfers','post:ds-starter-c14bbeee72251f86cb1a',NULL,'Prepared guide answer: Review the upload before applying it and distinguish earned work from saved course ideas. A withdrawal or unresolved incomplete is not a finished course simply because it appears on the transcript. Keep the original grade and completion information visible in the review. If you want to revisit a subject, save an available course as a future option rather than changing the old record into completed learning.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c14bbeee72251f86cb1a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c14bbeee72251f86cb1a-guide-2','ds-guide-momentum','post:ds-starter-c14bbeee72251f86cb1a',NULL,'Prepared guide answer: Use the degree worksheet to identify what remains, then choose one realistic replacement or completion action. A school may have a process for resolving an incomplete, but that is a different task from taking a new transfer course. Preserve the original record while considering both options. A plan that accurately shows unfinished work is more useful than an impressive progress bar based on courses you did not complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c14bbeee72251f86cb1a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c2e45ae2848aec6272ca','ds-guide-planning','course:christianleadersinstitute-plan-the310','question','Does “timed, open-note quiz” mean there is no monitoring?','Example situation: I’m considering a theology course and see references to timed, open-note quizzes. That format sounds different from a conventional closed-book exam, but I’m not sure whether it also tells me anything about monitoring. How should I use the assessment filters when a course describes what resources I can consult but does not clearly establish the full monitoring process? I want an option that fits my preferences without assuming that every open-note assessment is automatically unproctored.','https://degreesteps.com/courses.html?provider=Christian%20Leaders%20Institute',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c2e45ae2848aec6272ca-guide-1','ds-guide-courses','post:ds-starter-c2e45ae2848aec6272ca',NULL,'Keep permitted resources and monitoring as separate facts. A timed, open-note quiz describes how the assessment works in some respects, but it does not by itself establish whether identity checks or monitoring are required. The reviewed Christian Leaders course descriptions retain that distinction. Use the assessment evidence for the exact course, and allow an unknown classification when the available source does not establish an unmonitored format rather than presenting an unsupported no-proctor badge.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c2e45ae2848aec6272ca' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c2e45ae2848aec6272ca-guide-2','ds-guide-transfers','post:ds-starter-c2e45ae2848aec6272ca',NULL,'Compare another supported source if a particular assessment condition is essential to your decision. You can save both options while checking their degree fit and documented format. The course with clearer evidence may be a more practical choice for your situation even when both subjects appear useful. Keep your intended source choice attached to the requirement, and update it through the plan controls if you decide to use a different eligible offering.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c2e45ae2848aec6272ca' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c3844edf9ba4a64ea2c2','ds-guide-money','school:general','question','What can I usefully do if my study budget is about $100 a month?','Example situation: I could set aside around $100 each month for school, but I cannot afford an unexpected university bill or several memberships at once. I am starting with no credit and want to make sure early courses are not a dead end. Is it better to save money until I can pay for a whole term, or can I begin with individual requirements while choosing a degree?','https://degreesteps.com/start.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3844edf9ba4a64ea2c2-guide-1','ds-guide-money','post:ds-starter-c3844edf9ba4a64ea2c2',NULL,'Prepared guide answer: Begin by exploring a small number of degree routes for free and identify where low-cost outside courses have documented use. Compare the remaining university charges as well as the first provider payment. A course that fits this month’s budget can still lead to a university phase that does not fit later. The useful first plan shows both stages, with uncertain fees or prices kept separate from known charges.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3844edf9ba4a64ea2c2' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3844edf9ba4a64ea2c2-guide-2','ds-guide-courses','post:ds-starter-c3844edf9ba4a64ea2c2',NULL,'Prepared guide answer: You do not need to open a paid membership just because you have started planning. Collect records, compare requirements, and save course options first. When you are ready to purchase, check the current eligible plan, renewal, assessment, and transcript charges. One provider at a time can make spending easier to control. Keep the full degree budget visible while choosing an affordable first course that actually moves it forward.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3844edf9ba4a64ea2c2' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c3a2294966c1ba4883f7','ds-guide-planning','school:general','question','Would competency-based study suit me if most of the subject is new?','Example situation: I like the idea of paying by a term or subscription, but I am changing careers and would be learning most of the material for the first time. I worry that examples of very fast completion come from students who already knew the subject. How should I compare a competency-based program with a more structured course schedule without assuming that one format is always faster or cheaper?','https://degreesteps.com/programs.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3a2294966c1ba4883f7-guide-1','ds-guide-planning','post:ds-starter-c3a2294966c1ba4883f7',NULL,'Prepared guide answer: Use Find a degree to compare competency-based format, pace, and billing as separate features. Then inspect the actual university work left after your applicable transfers. Competency-based study lets a program assess demonstrated learning, but unfamiliar material still requires learning time and support. A fixed-price term only becomes a personal cost estimate when you make realistic assumptions about what you can complete during that period.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3a2294966c1ba4883f7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3a2294966c1ba4883f7-guide-2','ds-guide-courses','post:ds-starter-c3a2294966c1ba4883f7',NULL,'Prepared guide answer: Look for a format that supports how you learn new material: examples, instruction, feedback, access to help, and clear assessments. Compare an extra term in your budget rather than relying on another student’s rapid completion. You may still prefer competency-based study for flexibility, but choosing it should not require pretending you already know the curriculum. Start with the route whose expectations and support you understand.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3a2294966c1ba4883f7' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c3ddd04186f0a9af3219','ds-guide-planning','school:general','question','My transcripts use different last names. Will that make importing harder?','Example situation: I attended college before and after changing my last name, so the documents do not all match my current account name. I want to organize them without putting identity documents into a public discussion or a course spreadsheet. I also worry about a receiving college failing to connect the records later. What should I do now in DegreeSteps, and which parts belong outside the app?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3ddd04186f0a9af3219-guide-1','ds-guide-transfers','post:ds-starter-c3ddd04186f0a9af3219',NULL,'Prepared guide answer: Use My courses to organize the academic rows, keeping the original school and course details intact. A course spreadsheet does not need your birth date, identification numbers, or copies of name-change documents. Review the imported courses before adding them and use your private account for your plan. Public community posts can describe the situation generally without showing your transcript or identity paperwork.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3ddd04186f0a9af3219' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c3ddd04186f0a9af3219-guide-2','ds-guide-planning','post:ds-starter-c3ddd04186f0a9af3219',NULL,'Prepared guide answer: Official identity matching happens through the institutions and transcript services handling your records. Keep a private list of the names used at each school so you can complete their delivery steps accurately. In the degree plan, the useful next action is collecting the correct original records, not publishing more personal information. A mismatch in names should not lead you to alter course titles, dates, or earned credit quantities.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c3ddd04186f0a9af3219' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c5c24c839716edd26c95','ds-guide-planning','course:upi-study-upis-0014','question','Does Advanced Technical Writing replace a first composition requirement?','Example situation: I’m interested in Advanced Technical Writing because I write reports at work and would like a course that feels relevant. My degree plan also has an introductory composition requirement. Can the advanced writing course satisfy that row just because both involve English and writing, or should I expect different placements? I want to choose useful learning without skipping a required writing sequence or taking a course whose supported award does not match the requirement I am trying to complete.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c5c24c839716edd26c95-guide-1','ds-guide-courses','post:ds-starter-c5c24c839716edd26c95',NULL,'Compare the exact receiving award rather than the general subject label. Advanced Technical Writing and a first composition course can serve different purposes in a degree. A source’s upper-division recommendation does not automatically replace an introductory composition requirement, and a receiving school may assign its own course and level. Keep the writing sequence intact unless the specific degree evidence supports another allocation for the exact outside course you are considering.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c5c24c839716edd26c95' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c5c24c839716edd26c95-guide-2','ds-guide-transfers','post:ds-starter-c5c24c839716edd26c95',NULL,'If technical writing fits a different required row or an allowed elective, save it there and leave introductory composition open. That can preserve the course’s career value without stretching its academic placement. When comparing degrees, check whether either program uses the technical-writing award more directly. The original course identity and credits remain the same; the supported application to each degree is what determines whether it helps you finish with less remaining coursework.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c5c24c839716edd26c95' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-c819f7696e1b79daab69','ds-guide-planning','school:wgu','question','What if a provider agreement shows a course title and identifier that disagree?','Example situation: I am using a community spreadsheet to choose a statistics course for WGU, and one referenced course code seems to belong to business law. Should I trust the course name, the code, or the fact that the entry appears in a partner agreement? I want the platform to catch this kind of inconsistency before it becomes an expensive course purchase or an incorrect completed requirement.','https://degreesteps.com/degree-plans/wgu-cybersecurity-and-information-assurance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c819f7696e1b79daab69-guide-1','ds-guide-courses','post:ds-starter-c819f7696e1b79daab69',NULL,'A contradiction should stop that exact option from being recommended until it is resolved. The current reviewed batch found a statistics row whose listed Study identifier belonged to Business 103 rather than the stated statistics related course. DegreeSteps held that contradictory option instead of treating a partnership table as infallible. A separate supported Statistics 101 identity remains distinct; the wrong law identity must not be repurposed to satisfy statistics.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c819f7696e1b79daab69' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-c819f7696e1b79daab69-guide-2','ds-guide-transfers','post:ds-starter-c819f7696e1b79daab69',NULL,'Keep the questionable entry as a research lead with its source, not as a selectable approved match. Use an independently supported option for the actual requirement if one exists in your exact program. This is why the app needs provider identity evidence as well as receiving agreement evidence: neither a familiar title nor a published code alone is enough when the two disagree. Catching the contradiction protects the student before money is spent.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-c819f7696e1b79daab69' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ca0650da999e7b845150','ds-guide-planning','school:liberty','question','Can extra introductory electives cover the upper level courses I still need?','Example situation: I have found a lot of inexpensive introductory courses and could finish several quickly. My Liberty plan still shows work in the major and at the upper level. Would taking more introductory electives move me closer to graduation anyway, or should I stop adding them? I want to understand when the easiest available course stops being the best next course.','https://degreesteps.com/degree-plans/liberty-business-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ca0650da999e7b845150-guide-1','ds-guide-transfers','post:ds-starter-ca0650da999e7b845150',NULL,'Follow the requirement groups in the exact worksheet. Free electives, upper level credit, and named major courses are not interchangeable buckets. Even a course with an advanced sounding title needs the receiving award and level shown for that option. If the elective space is already filled, another introductory course can add to your record without reducing the remaining work in this degree at all.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ca0650da999e7b845150' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ca0650da999e7b845150-guide-2','ds-guide-planning','post:ds-starter-ca0650da999e7b845150',NULL,'Sort the remaining work by the constraint it satisfies. Find supported outside choices for an open major or level requirement first, then use genuine free elective space for flexible credits. Where university coursework must remain, include it in your sequence and cost. The goal is the smallest useful set of courses that finishes all requirement groups, rather than the biggest number of inexpensive courses you can accumulate.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ca0650da999e7b845150' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cbf3355715508f6a5955','ds-guide-planning','school:tesu','question','Can one writing course cover every writing requirement in TESU English?','Example situation: I enjoy writing and am considering the TESU English degree. A provider''s composition course looks easy to begin, but the degree also contains advanced literature and writing work. Can I use one good composition course for several of those rows? I want to see how a general education match differs from the area of study before choosing a large bundle of courses.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-arts/ba-in-english/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cbf3355715508f6a5955-guide-1','ds-guide-courses','post:ds-starter-cbf3355715508f6a5955',NULL,'Treat each requirement as its own row. An introductory composition award does not automatically satisfy advanced English study, and one original course should not be reused to manufacture several completed requirements. The reviewed Study English 104 identity has a specific proposed ENC-1010 receiving match, with its own source version and conditional evidence. That narrow match is not a claim that the course covers an entire writing sequence or English major.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cbf3355715508f6a5955' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cbf3355715508f6a5955-guide-2','ds-guide-planning','post:ds-starter-cbf3355715508f6a5955',NULL,'Start with the named degree requirements and separate general education from the English area of study. Then compare outside options that actually meet the remaining level and subject requirements. If you are deciding between English and Liberal Studies, use the same original records in both audits and inspect where they land. A course can be valuable without satisfying the most advanced row that happens to contain a similar word.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cbf3355715508f6a5955' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cc7eb781641f7cbdb1dc','ds-guide-military','school:tesu','question','How should military training credit fit beside college courses in the same plan?','Example situation: I’m a military learner with training records and some college coursework, and I want to avoid treating them as though they are all the same kind of source. What should I keep separate when building a degree plan? I’d like the university to apply as much relevant learning as its rules support, while preserving the original military recommendation, any college-issued awards and the courses I still need. Funding eligibility is another part of the situation, not the credit itself.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cc7eb781641f7cbdb1dc-guide-1','ds-guide-military','post:ds-starter-cc7eb781641f7cbdb1dc',NULL,'Keep the military training identity, recommendation details and relevant dates alongside the actual original record. College coursework should retain its issuing institution, grade and credit units separately. A recommendation for military learning is not automatically an exact university course award, and the receiving institution decides how it applies to a particular degree. When an evaluation exists, attach that receiving result without replacing or duplicating the original training and college records.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cc7eb781641f7cbdb1dc' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cc7eb781641f7cbdb1dc-guide-2','ds-guide-transfers','post:ds-starter-cc7eb781641f7cbdb1dc',NULL,'Compare degrees using the same preserved learning history, then look at the remaining institutional, major and upper-level requirements. That shows where the evaluated training is useful instead of assuming every recommendation will fit an open elective. Add transcript delivery and evaluation steps to the checklist where needed. Keep service benefits and exam-funding eligibility in the financial planning side, so a funding advantage is not mistaken for proof of academic acceptance or a completed requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cc7eb781641f7cbdb1dc' AND p.user_id='ds-guide-military' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cd2fc2f1ec6c3da3801f','ds-guide-planning','school:general','question','My old college used quarter credits. Should I change the numbers before uploading?','Example situation: I have a transcript with four-credit and five-credit courses from a school that used quarters. The degrees I am browsing seem to use semester credits, and I am not sure whether I should convert everything in my spreadsheet first. I want an accurate comparison without accidentally turning one course into more credit than I earned. What should the uploaded file actually say?','https://degreesteps.com/guides/organize-transcripts-and-credits/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cd2fc2f1ec6c3da3801f-guide-1','ds-guide-transfers','post:ds-starter-cd2fc2f1ec6c3da3801f',NULL,'Prepared guide answer: Keep the original number and label its credit system as quarter. The spreadsheet template has a field for units, and the import review lets you inspect them before adding the courses. Do not rewrite four quarter credits as four semester credits. Original learning and the receiving degree’s allocation are different records, so preserving the starting facts makes later comparisons much more reliable.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cd2fc2f1ec6c3da3801f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cd2fc2f1ec6c3da3801f-guide-2','ds-guide-planning','post:ds-starter-cd2fc2f1ec6c3da3801f',NULL,'Prepared guide answer: When you open a plan, look at how much of each requirement the proposed placement actually satisfies, rather than simply adding all transcript numbers together. A receiving college may apply a course differently depending on its requirements. If a course leaves a shortfall, keep that visible in the comparison. You should not have to damage the original record to make the degree worksheet look balanced.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cd2fc2f1ec6c3da3801f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cdb3f1df1db6436cc5e0','ds-guide-planning','course:straighterline-aa4562f7b3ea0d6f4e','question','Does “no live proctor” mean there is no screen sharing or browser restriction?','Example situation: I’m considering an English Composition option and would prefer assessments without monitoring. Some descriptions discuss live proctors, while others mention screen sharing or browser restrictions. Those sound like different experiences, so I’m unsure which preference to choose in the course filters. How should I compare an unproctored course with a course that has no person watching live but still uses assessment technology or restricts what I can do during the exam?','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cdb3f1df1db6436cc5e0-guide-1','ds-guide-courses','post:ds-starter-cdb3f1df1db6436cc5e0',NULL,'Treat the assessment conditions separately. A provider can say there is no live proctor while still requiring screen sharing or browser restrictions for a final. The reviewed StraighterLine classifications distinguish those conditions from an unmonitored exam. Open the exact course’s assessment evidence and use the restriction labels that matter to you. A preference for no proctored exams should not silently classify every absence of a live person as an unrestricted assessment.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cdb3f1df1db6436cc5e0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cdb3f1df1db6436cc5e0-guide-2','ds-guide-transfers','post:ds-starter-cdb3f1df1db6436cc5e0',NULL,'Plan the necessary device and study environment before selecting the enrollment action. A course with writing assignments may still have an additional final or assessment rule, so the format cannot be inferred from the subject alone. If the current evidence is not specific enough to classify an offering, keep that uncertainty visible in the comparison. Your degree placement and your comfort with the assessment are both important, but they answer different questions.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cdb3f1df1db6436cc5e0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cdc882bd3892ca3db92d','ds-guide-planning','school:wgu','question','Why can three outside credits satisfy a WGU row with a different CU amount?','Example situation: My provider transcript shows semester credits, but the WGU worksheet uses competency units. Some receiving rows have a different number from the source course. Which number belongs in my course collection, and which belongs in the degree audit? I want a clear explanation so I do not accidentally change my original transcript or assume that every receiving quantity applies at other universities too.','https://degreesteps.com/degree-plans/wgu-health-science/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cdc882bd3892ca3db92d-guide-1','ds-guide-courses','post:ds-starter-cdc882bd3892ca3db92d',NULL,'Keep both quantities. The original source course retains its own credit system and amount; the WGU requirement retains its receiving competency units. A supported agreement connects those records for that exact destination. The receiving amount does not rewrite what the provider originally issued, and it does not travel automatically to another university. Preserving the distinction is essential for both accurate auditing and meaningful comparisons between different degree plans.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cdc882bd3892ca3db92d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cdc882bd3892ca3db92d-guide-2','ds-guide-planning','post:ds-starter-cdc882bd3892ca3db92d',NULL,'When saving a course, keep its original code, version, credits, and completion details intact. Then let each exact degree show the award and requirement it can use. If you later compare another school, reuse the source record rather than copying the WGU quantity into it. This avoids inflated totals and makes it clear why one completed course may advance different degrees by different amounts without becoming two separate original courses.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cdc882bd3892ca3db92d' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ce8df364ef2fbb0b62ac','ds-guide-planning','school:wgu','question','How do I combine several colleges and providers before WGU?','Example situation: My coursework is scattered across a community college, another university, and an outside provider. I want to see which WGU degree uses it best, but adding every entry by hand feels like another project. Should I combine the credits into one total, or preserve separate records? I need a simple upload workflow that keeps enough detail for a real comparison rather than only producing a large credit number.','https://degreesteps.com/degree-plans/wgu-human-resource-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ce8df364ef2fbb0b62ac-guide-1','ds-guide-transfers','post:ds-starter-ce8df364ef2fbb0b62ac',NULL,'Use transcript uploads or the course spreadsheet to collect the original records in batches. Preserve each issuing source, course code, title, credits, and completion details. Do not replace them with one combined total or rewrite provider courses as if the later college originally taught them. The audit needs source identity to evaluate matches, source limits, recency where applicable, and duplicate content across records.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ce8df364ef2fbb0b62ac' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ce8df364ef2fbb0b62ac-guide-2','ds-guide-momentum','post:ds-starter-ce8df364ef2fbb0b62ac',NULL,'Once the collection is organized, compare exact degree worksheets using that same input. Keep a checklist for the official records needed in WGU''s transfer process, separately from the course list you use to explore. A completed source course is not the same as a university awarded transfer row. This lets the plan become easier to use without losing the distinctions that make its recommendations accurate.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ce8df364ef2fbb0b62ac' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-cfa6bab56d91dee8c960','ds-guide-planning','course:saylor-plan-saya0013','question','Does Management Information Systems fill a major requirement or a general elective?','Example situation: I’m choosing technology-related courses for a business degree and noticed Management Information Systems in the library. The title sounds close to a course in the major, but it might also fit a general elective in another program. How should I decide whether it is worth taking now? I want to compare the actual placements and any level requirements rather than assuming an advanced-sounding title automatically gives me the most useful major credit.','https://degreesteps.com/courses.html?provider=Saylor',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cfa6bab56d91dee8c960-guide-1','ds-guide-courses','post:ds-starter-cfa6bab56d91dee8c960',NULL,'Open the requirement you are trying to satisfy and compare the exact receiving award for this source course. A course title alone cannot establish a named major match or an upper-level classification at the receiving school. The same source course might be useful in different ways across degrees. Keep its original identity and credit recommendation intact, then let the supported receiving allocation determine which requirement it actually contributes to in each plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cfa6bab56d91dee8c960' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-cfa6bab56d91dee8c960-guide-2','ds-guide-transfers','post:ds-starter-cfa6bab56d91dee8c960',NULL,'Look beyond the total number of credits applied. If one degree uses the course in its major and another uses it only in an elective block, the remaining university coursework may differ substantially. Compare those open rows, including any upper-level or major-residency conditions. This makes the decision more practical than asking whether the school accepts Saylor in general. The question is how this particular completed course would advance the specific degree you are considering.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-cfa6bab56d91dee8c960' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d1a92c1721b672b0ba1f','ds-guide-planning','course:straighterline-aa4562f7b3ea0d6f4e','question','I can finish the course before enrollment. What happens after the final result?','Example situation: I’m planning to complete English Composition I before starting at a university. Once the provider shows a final result, I’m not sure whether that automatically reaches the receiving school or whether I need to request another record. How should the plan separate finishing the course from sending and evaluating the credit? I want the next step to be clear without marking university requirements approved simply because I completed the outside course.','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d1a92c1721b672b0ba1f-guide-1','ds-guide-courses','post:ds-starter-d1a92c1721b672b0ba1f',NULL,'Record the source course’s actual completion, then follow the transcript route required for that provider and receiving school. The course result, transcript request, document delivery and college evaluation are separate events. Add the transcript request and any receiving deadline as checklist tasks. A completed source record can remain in your collection while its school-specific placement is still being evaluated; that is progress without an invented university award.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d1a92c1721b672b0ba1f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d1a92c1721b672b0ba1f-guide-2','ds-guide-transfers','post:ds-starter-d1a92c1721b672b0ba1f',NULL,'Keep the original provider, course code, credit units and completion date when the receiving result arrives. Add the university’s evaluated course and credit amount as the receiving award rather than overwriting the original record. This preserves a useful audit trail if another degree program applies the course differently. It also helps you diagnose a delay: you can tell whether the outstanding task is document delivery, evaluation or a remaining academic requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d1a92c1721b672b0ba1f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d254e50216f755ecde1b','ds-guide-money','school:general','question','Would paying for one course at a time be better with irregular income?','Example situation: I freelance, so some months are comfortable and others are tight. A subscription might be cheaper if I finish quickly, but I dislike having a charge continue during a month when work takes over. I would rather understand the tradeoff than chase the smallest advertised price. How should I compare an individual course purchase with a membership when I cannot promise the same study pace every month?','https://degreesteps.com/guides/compare-transfer-credit-sources/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d254e50216f755ecde1b-guide-1','ds-guide-money','post:ds-starter-d254e50216f755ecde1b',NULL,'Prepared guide answer: Compare the cost of the course you need under both payment arrangements, using a conservative completion scenario. Include access limits, renewal charges, assessment fees, and transcript costs where applicable. A one-time purchase can offer a different kind of flexibility from a monthly membership, but its terms still matter. First establish that the exact course fits the degree; a convenient payment method cannot make an unrelated course useful.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d254e50216f755ecde1b' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d254e50216f755ecde1b-guide-2','ds-guide-planning','post:ds-starter-d254e50216f755ecde1b',NULL,'Prepared guide answer: Try a longer completion scenario alongside your best case, such as an extra paid month or a pause caused by a large client project. Keep the result as an estimate rather than a personal deadline. Save your course ideas in My courses while deciding when to start paying. Predictable spending may be worth a slightly higher course price if it reduces the chance of paying through an interruption.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d254e50216f755ecde1b' AND p.user_id='ds-guide-money' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d58edb79bb6ebe5984e5','ds-guide-planning','school:tesu','question','Is TESU Psychology a good completion degree if I might pursue graduate study?','Example situation: I enjoy psychology and want to finish a bachelor degree efficiently, but graduate school might be part of my future. I do not want to reject inexpensive transfer options unnecessarily or assume that the quickest bachelor route satisfies every later admissions requirement. How should I compare the TESU psychology curriculum with my existing courses while keeping the future decision practical rather than overwhelming?','https://www.tesu.edu/admissions/methods-of-earning-credit/provider-directory.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d58edb79bb6ebe5984e5-guide-1','ds-guide-careers','post:ds-starter-d58edb79bb6ebe5984e5',NULL,'Separate the bachelor requirements from the graduate programs you may eventually target. A course can satisfy a bachelor requirement while a later program asks for a particular subject, grade, or kind of preparation. Bring a short list of real graduate prerequisites into the comparison rather than adding every possible advanced class. Use the same original course records to see both what the bachelor uses and what a later application may still need.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d58edb79bb6ebe5984e5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d58edb79bb6ebe5984e5-guide-2','ds-guide-planning','post:ds-starter-d58edb79bb6ebe5984e5',NULL,'Choose your next course where the two goals overlap, provided the receiving placement is supported. Keep any additional preparation distinct from what is required to graduate, so the degree estimate does not quietly expand into an indefinite project. A psychology bachelor degree also does not itself establish eligibility for licensed clinical practice. The useful plan makes the next degree decision easier without promising a professional outcome it cannot establish.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d58edb79bb6ebe5984e5' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d5bd2ebf350e39f5e372','ds-guide-planning','school:liberty','question','Can I build a Liberty plan around courses without proctored finals?','Example situation: I work irregular shifts and would prefer outside courses without proctored finals. I am comfortable writing papers, but arranging a remote exam adds stress. Can I use that preference to choose between courses without assuming that every provider works the same way? I also want to understand whether that preference means my entire Liberty degree could avoid proctored assessments.','https://degreesteps.com/degree-plans/liberty-psychology-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d5bd2ebf350e39f5e372-guide-1','ds-guide-courses','post:ds-starter-d5bd2ebf350e39f5e372',NULL,'Use assessment details at the course level. Self paced describes scheduling; it does not promise the absence of a proctor. For example, the reviewed UPI courses use remotely proctored finals, so they should not be presented as a no proctor alternative. Compare the exact outside options attached to a requirement, including assessment format and source version, before deciding which one fits your routine.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d5bd2ebf350e39f5e372' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d5bd2ebf350e39f5e372-guide-2','ds-guide-momentum','post:ds-starter-d5bd2ebf350e39f5e372',NULL,'Keep your preference visible while reviewing the university courses that remain. An outside course choice cannot establish the assessment rules for Liberty coursework, and some requirements may have no suitable outside option. You can still make a useful plan: prioritize compatible outside matches, identify the small set of assessment tradeoffs, and schedule any required exams deliberately instead of discovering them after paying for a membership.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d5bd2ebf350e39f5e372' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d5c492ef66dd55177028','ds-guide-planning','school:umpi','question','Can I explore YourPace without knowing exactly how many credits I have?','Example situation: I know I completed some college courses, but I do not have the transcripts in front of me. I want to understand whether YourPace might be realistic before spending a weekend gathering paperwork. Can the starting experience help me explore without demanding perfect records? I would like a provisional picture that becomes more precise later rather than a form that blocks me at the first missing course code.','https://www.umpi.edu/yourpace/academic_programs/liberal-studies/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d5c492ef66dd55177028-guide-1','ds-guide-momentum','post:ds-starter-d5c492ef66dd55177028',NULL,'Use approximate information for exploration and label it as provisional. Record the colleges attended and broad study areas, then collect the actual transcripts for a course level audit. Do not convert an estimated total into completed requirement rows. The original course identity and source credits matter when the plan later checks applicability, duplicates, and source limits. A quick first picture is useful only when its assumptions remain visible.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d5c492ef66dd55177028' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d5c492ef66dd55177028-guide-2','ds-guide-planning','post:ds-starter-d5c492ef66dd55177028',NULL,'Make the next action small: request the most relevant transcript or upload a record you already have. Meanwhile, compare delivery style and the reviewed session billing model against your schedule. DegreeSteps does not currently publish a fully ready UMPI course plan, so the exploration should not pretend otherwise. It can still help you define the goal and organize records without authorizing a speculative provider purchase.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d5c492ef66dd55177028' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d6547a683b135e0296b9','ds-guide-planning','school:wgu','question','Does the WGU transfer ceiling mean I can bring in ninety credits for any bachelor degree?','Example situation: I keep seeing advice to transfer ninety credits before starting WGU. I am comparing more than one bachelor degree and their totals do not all look the same. Should I treat ninety as a universal target, or does the limit depend on the program? I want to maximize useful outside coursework without buying extra classes just to reach a number repeated in community discussions.','https://degreesteps.com/degree-plans/wgu-business-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d6547a683b135e0296b9-guide-1','ds-guide-transfers','post:ds-starter-d6547a683b135e0296b9',NULL,'Use the exact program''s competency unit total. The reviewed undergraduate WGU models apply an overall seventy five percent ceiling to that total; it is not a universal ninety credit allowance. That ceiling also does not approve any particular provider course. The exact receiving matches and required active program coursework can leave less room for outside credit than the headline percentage suggests, so the named requirement worksheet still governs the plan.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d6547a683b135e0296b9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d6547a683b135e0296b9-guide-2','ds-guide-planning','post:ds-starter-d6547a683b135e0296b9',NULL,'Compare how many remaining requirements each supported outside option actually closes. Stop when the next outside course would duplicate content, exceed the applicable limit, or leave required WGU work untouched. More accepted credit is helpful only when it reduces useful remaining coursework. A route with a smaller transfer number may still fit your career and schedule better, especially if its remaining assessments are work you can realistically complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d6547a683b135e0296b9' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d6b21be443df3ebb698e','ds-guide-planning','course:mapped-92088accacaebb71c248','question','When does a Universal Learner course become an official college-credit record?','Example situation: I’m interested in ASU Universal Learner because I want to study before committing to a larger degree plan. I’m unsure how the learning experience, final result and choice to obtain academic credit relate to one another. Which steps should I track before counting the course as an original college-credit record? I want the flexibility to explore while keeping any credit-election, payment and transcript requirements separate from simply opening the lessons or beginning the course material.','https://degreesteps.com/courses.html?provider=ASU%20Universal%20Learner',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d6b21be443df3ebb698e-guide-1','ds-guide-courses','post:ds-starter-d6b21be443df3ebb698e',NULL,'Read the current terms for the exact Universal Learner offering and identify the steps required to obtain its academic credit. Learning access, completing assessments and arranging the eligible credit record are distinct events. Keep any credit-election or payment conditions in your checklist rather than assuming lesson access already creates a transcript entry. The original record should reflect the issuer, course, actual result, credits and units once the applicable credit-bearing process is complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d6b21be443df3ebb698e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d6b21be443df3ebb698e-guide-2','ds-guide-transfers','post:ds-starter-d6b21be443df3ebb698e',NULL,'Compare the resulting course with your intended receiving degree before deciding what to purchase or transcribe. An ASU-issued course can be evaluated by a different receiving institution, which controls its own award and placement. If you plan to pursue an ASU degree, the program’s admission and academic requirements still apply separately. Keep your original completion and the degree-specific evaluation visible so exploring a course does not accidentally imply admission or an automatic completed degree requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d6b21be443df3ebb698e' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d70722141be5069f16e2','ds-guide-planning','course:straighterline-62b9791095371acfac','question','How should I budget for a science lecture and a separately purchased lab?','Example situation: I’m considering a chemistry requirement and see separate lecture and lab listings. The prices and credit amounts make it hard to tell whether I am comparing a complete science route or only one component. What should I put into the plan before deciding which provider is cheaper? I want a comparison that includes the required learning and materials, rather than choosing a low course price that leaves a necessary lab or other charge outside the estimate.','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d70722141be5069f16e2-guide-1','ds-guide-money','post:ds-starter-d70722141be5069f16e2',NULL,'List the actual source components required by the receiving award, then price those components together. A separate lab has its own identity, credit amount and possible materials or delivery requirements. It should not disappear into the lecture’s price just because both cover chemistry. Look for the supported receiving allocation first, and keep any course, membership, laboratory and transcript charges identified so the comparison describes the route you would actually complete.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d70722141be5069f16e2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d70722141be5069f16e2-guide-2','ds-guide-transfers','post:ds-starter-d70722141be5069f16e2',NULL,'Keep the original lecture and lab records separate when the provider issues them separately. If your receiving program groups them into one science requirement, the degree plan can show that combined placement without erasing the individual completions. Check whether an existing lecture already satisfies part of the requirement before purchasing both components again. This can reveal a smaller remaining task while preserving the source facts needed if you later change schools.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d70722141be5069f16e2' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-d81d04af6ae1306a9bbc','ds-guide-planning','school:general','question','Should I choose the fastest bachelor’s if I might want a master’s later?','Example situation: I could choose a broad bachelor’s degree with lots of electives, but I am also considering a future master’s in data analytics. I do not want to finish quickly and then discover I am missing mathematics or programming prerequisites. My graduate goal is not final yet, so I also do not want to pay for a long list of unnecessary advanced courses. How can I compare these options sensibly?','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d81d04af6ae1306a9bbc-guide-1','ds-guide-careers','post:ds-starter-d81d04af6ae1306a9bbc',NULL,'Prepared guide answer: Compare the bachelor’s routes using your current courses, but keep a separate list of the graduate programs you might actually apply to. Look at their published admission prerequisites, not just the name of the undergraduate major. A bachelor’s that finishes sooner may still leave preparation to complete later. The comparison should show both the degree requirements and any additional coursework needed for your next realistic goal.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d81d04af6ae1306a9bbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-d81d04af6ae1306a9bbc-guide-2','ds-guide-transfers','post:ds-starter-d81d04af6ae1306a9bbc',NULL,'Prepared guide answer: Choose a small set of prerequisites shared by your serious graduate targets, then see whether they can also satisfy requirements in a bachelor’s plan. Avoid treating an introductory course as a substitute for a named advanced prerequisite solely because the titles sound related. If your graduate direction changes, My courses preserves the original records so you can reassess their use without rewriting what you completed.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-d81d04af6ae1306a9bbc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-db84530b0844a9f1d989','ds-guide-planning','school:wgu','question','How should a WGU plan handle OR choices and multi course combinations?','Example situation: A WGU spreadsheet lists two provider courses next to one requirement, sometimes with an OR and sometimes without explanation. I cannot tell when I need both. How should the app make that decision obvious before I enroll? I want to benefit from community research without having to decode spreadsheet shorthand or accidentally pay for two courses when either one would have been enough.','https://degreesteps.com/degree-plans/wgu-business-management/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-db84530b0844a9f1d989-guide-1','ds-guide-courses','post:ds-starter-db84530b0844a9f1d989',NULL,'Represent the receiving rule explicitly. An OR means alternatives when the source establishes that choice; a required bundle means every named part is needed. A sequence may also have an order that matters. Those are different instructions, not formatting preferences. The exact provider course identities and the WGU receiving requirement should stay attached to the rule so the credit and price calculations use the same selected combination.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-db84530b0844a9f1d989' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-db84530b0844a9f1d989-guide-2','ds-guide-planning','post:ds-starter-db84530b0844a9f1d989',NULL,'Choose one supported path for each row and keep other options available for comparison. If you replace an option, remove the superseded candidate from the paid basket rather than adding another completed requirement. Never infer a bundle from two adjacent spreadsheet cells alone. A good course plan translates the evidence into a concrete action, while preserving enough detail to explain why one course or the whole combination is required.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-db84530b0844a9f1d989' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-dc584b2b3b0069be0b57','ds-guide-planning','school:general','question','How should I compare writing-heavy courses when English is not my first language?','Example situation: I am comfortable speaking English at work, but academic writing takes me longer because I check wording and citations carefully. I want to earn a degree without avoiding writing entirely or paying for a subscription that assumes I will finish several essays every month. How can I compare suitable course options and leave room to improve my writing while still making useful progress toward a degree?','https://degreesteps.com/courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-dc584b2b3b0069be0b57-guide-1','ds-guide-courses','post:ds-starter-dc584b2b3b0069be0b57',NULL,'Prepared guide answer: Use the course library to compare the actual writing, reading, and assessment requirements of options that fit your degree. A writing-heavy course may suit your goals, but its calendar demands can differ from an exam-based option. Save a small number of relevant choices, then inspect the requirement they would satisfy in My plan. Do not buy a general language or writing course assuming it automatically replaces a named composition requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-dc584b2b3b0069be0b57' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-dc584b2b3b0069be0b57-guide-2','ds-guide-money','post:ds-starter-dc584b2b3b0069be0b57',NULL,'Prepared guide answer: Budget time for drafting, feedback, and revisions rather than only the number of lessons. Starting with one applicable writing course can help you learn your pace before committing to multiple paid months. Keep any support or tutoring terms visible in the cost comparison. Your existing language skills and your original college records remain separate facts; neither should be reduced to an assumed completion speed or an invented credit award.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-dc584b2b3b0069be0b57' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ddadb2465fe9bab0c200','ds-guide-planning','school:tesu','question','Should I convert quarter credits to semester credits before importing my transcript?','Example situation: I’m bringing together records from colleges that used different credit systems. One transcript lists quarter credits, while a degree I’m considering uses semester credits or competency units. Should I change the original numbers before uploading a spreadsheet, or keep what each issuing college recorded? I want the plan to calculate receiving credit correctly without losing the original values, especially if I compare more than one school and their evaluation rules are not identical.','https://degreesteps.com/import-courses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ddadb2465fe9bab0c200-guide-1','ds-guide-courses','post:ds-starter-ddadb2465fe9bab0c200',NULL,'Keep each source record’s original credit quantity and unit system. A four-quarter-credit course should stay identified that way in your collection rather than being rewritten as a guessed semester value. The receiving school’s conversion or evaluated award is a separate part of the match. When importing the spreadsheet, use the appropriate unit label for each row and review the preview before saving, especially if the file combines records from more than one institution.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ddadb2465fe9bab0c200' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ddadb2465fe9bab0c200-guide-2','ds-guide-transfers','post:ds-starter-ddadb2465fe9bab0c200',NULL,'Compare degrees using those unchanged original records. Each plan can apply its supported receiving policy without forcing the first school’s conversion into every later comparison. If a unit system is not known, leave it unknown until the source record establishes it. An apparent numeric match is not enough: credits, competency units and academic requirements have distinct meanings, and the degree progress should follow the documented receiving allocation instead of a convenient copied number.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ddadb2465fe9bab0c200' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e01727fb73d77aaa4813','ds-guide-planning','school:liberty','question','Does the quickest healthcare administration plan fit the job I want?','Example situation: I work in a healthcare setting and want a bachelor degree that helps me move into administration. I am attracted to the shortest transfer route, but I do not want a degree choice that misses an employer requirement. How should I use the Liberty healthcare administration plan to balance speed with the kinds of roles I actually hope to apply for?','https://degreesteps.com/degree-plans/liberty-healthcare-administration-bs-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e01727fb73d77aaa4813-guide-1','ds-guide-careers','post:ds-starter-e01727fb73d77aaa4813',NULL,'Bring a few real job descriptions into the comparison. Identify whether they request a bachelor degree generally, a particular field, experience, or a separate credential. Then look at the published healthcare administration worksheet and see how much of your existing coursework applies. The degree title is a useful starting point, but a lower course count alone does not establish that the route fits the role.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e01727fb73d77aaa4813' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e01727fb73d77aaa4813-guide-2','ds-guide-planning','post:ds-starter-e01727fb73d77aaa4813',NULL,'Keep required university coursework, projects, and any stated program obligations visible while choosing outside classes. Those parts may matter to your preparation even when they cannot be replaced cheaply. Compare this route with other genuinely relevant degrees using remaining work and total cost, then choose the next course that advances the selected plan. You are buying a path toward a goal, not simply collecting the fastest available credits.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e01727fb73d77aaa4813' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e025b109311f51ec9987','ds-guide-campus','school:liberty','question','For Liberty, should I compare the residential degree separately from the online one?','Example situation: I am considering Liberty and would prefer living on campus. I found online course-transfer discussions that seem promising, but many examples do not say whether they concern the residential or online program. I would like to save money before arriving without picking courses for the wrong degree version. What should I compare first, and which parts of the plan should stay specific to the format?','https://degreesteps.com/blog/liberty-criminal-justice-online-vs-residential/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e025b109311f51ec9987-guide-1','ds-guide-campus','post:ds-starter-e025b109311f51ec9987',NULL,'Prepared guide answer: Choose the residential route explicitly and keep its exact degree title and catalog in view. The Liberty comparison article explains why online and residential versions deserve separate planning. Use My courses for original learning records, then inspect how they apply to the selected route. A course match discussed for an online degree should not silently become a residential requirement placement just because the university name is the same.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e025b109311f51ec9987' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e025b109311f51ec9987-guide-2','ds-guide-transfers','post:ds-starter-e025b109311f51ec9987',NULL,'Prepared guide answer: Look at what remains at Liberty after the proposed outside coursework: major courses, university-specific requirements, residency, and any sequence that could affect your time on campus. Add housing and other campus costs to the practical decision. A shorter remaining credit list is helpful, but it is not a guarantee that all classes fit into the same year or that a reported community example applies to your situation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e025b109311f51ec9987' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e072bf18ac092035aadc','ds-guide-planning','school:general','question','Will computer courses from years ago still help with a technology degree?','Example situation: I took programming and networking classes about twelve years ago, then worked in customer support instead of finishing college. I would now like an IT degree. Some of the subjects still feel familiar, but the technology has changed a lot. I want to avoid repeating useful learning while also being ready for advanced classes. How should I judge whether those older courses belong in my plan?','https://degreesteps.com/blog/do-old-college-credits-still-count/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e072bf18ac092035aadc-guide-1','ds-guide-transfers','post:ds-starter-e072bf18ac092035aadc',NULL,'Prepared guide answer: Import the courses with their actual completion dates and original codes, then compare specific degree requirements. Do not assume every old course expires, or that every technology course stays current forever. Some programs apply recency rules to particular subjects. The degree comparison is useful because the same older learning may satisfy a requirement in one route while leaving a different requirement open in another.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e072bf18ac092035aadc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e072bf18ac092035aadc-guide-2','ds-guide-courses','post:ds-starter-e072bf18ac092035aadc',NULL,'Prepared guide answer: Separate credit applicability from your own readiness. An older course might count while you still want a short refresher before an advanced topic. Conversely, knowing a current tool does not automatically award credit for a prior course you never completed. Use the remaining course list to spot genuine knowledge gaps, then choose preparation that helps you succeed without paying twice for unnecessary college credit.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e072bf18ac092035aadc' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e4ebe1d029f2fe5df0eb','ds-guide-planning','course:sophia-2572898d05a607b7c4','question','Does today’s Business Law listing apply to an older completion?','Example situation: I have an older Business Law course in my records and see a current Sophia listing with a familiar title. I’m comparing a new degree plan and would like to reuse what I already completed. Should I select the current listing, or keep my original course details? I’m especially unsure what happens when a course has a new recommendation period or version but the name still looks almost the same in a search.','https://degreesteps.com/courses.html?provider=Sophia',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e4ebe1d029f2fe5df0eb-guide-1','ds-guide-courses','post:ds-starter-e4ebe1d029f2fe5df0eb',NULL,'Keep the completed course as its original record, including the code, completion date, credit units and any version shown on your documents. Today’s listing describes the current offering; it should not overwrite a historical completion. A course can keep a similar title while its recommendation period or version changes. Matching should use the record you earned, with the receiving school’s dated award evidence where one is already available.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e4ebe1d029f2fe5df0eb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e4ebe1d029f2fe5df0eb-guide-2','ds-guide-transfers','post:ds-starter-e4ebe1d029f2fe5df0eb',NULL,'If you already have a formal evaluation from a college, preserve that result as an evaluation for that college and degree context. It does not automatically establish acceptance elsewhere, but it is useful evidence for your existing plan. Save the current course separately only if you are genuinely considering taking it now. Comparing a current option with an older earned record should never silently replace the earned record’s identity or date.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e4ebe1d029f2fe5df0eb' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e56f463176bcf70c1245','ds-guide-planning','school:tesu','question','How should employer reimbursement change the order of a TESU plan?','Example situation: My employer may reimburse some college coursework, but inexpensive outside providers could still help me finish faster. Should I use employer money first, or finish alternative courses before enrollment? I do not want to lose a reimbursement opportunity or pay for a duplicate. I need a sequence that distinguishes what the degree accepts from what my workplace is actually willing to fund.','https://www.tesu.edu/tuition-financial-aid/tuition-fees/undergraduate.php',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e56f463176bcf70c1245-guide-1','ds-guide-money','post:ds-starter-e56f463176bcf70c1245',NULL,'Treat employer payment rules and academic transfer rules as separate inputs. A provider course may be inexpensive and academically useful without being reimbursable; a university course may be reimbursable but duplicate something you already hold. First audit the existing records and identify genuinely open requirements. Then attach the employer''s documented eligibility, timing, grade, and payment conditions to the options you are seriously comparing.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e56f463176bcf70c1245' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e56f463176bcf70c1245-guide-2','ds-guide-planning','post:ds-starter-e56f463176bcf70c1245',NULL,'Build the cash flow timeline alongside the course sequence. Reimbursement after completion is different from an upfront payment, and a capped benefit can make scheduling matter. The standard TESU tuition estimate is not an employer agreement or a corporate rate. Keep those assumptions visible so a lower out of pocket route reflects your actual arrangement rather than automatically treating every eligible course as free to take.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e56f463176bcf70c1245' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e5ca81b76dd8d0c5320a','ds-guide-planning','school:umpi','question','Why do the UMPI outcome minima not add up to the published general education total?','Example situation: I read the new UMPI general education overview and tried to turn the outcome list into a course spreadsheet. Some categories have a plus sign beside their credit amount, so my sum does not match the stated total. Should I simply add another three credit elective somewhere? I want a plan that handles the requirement structure correctly instead of filling a gap with a plausible guess.','https://www.umpi.edu/academics/general-education-curriculum/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e5ca81b76dd8d0c5320a-guide-1','ds-guide-courses','post:ds-starter-e5ca81b76dd8d0c5320a',NULL,'Use the explicit forty credit general education total as a separate requirement. The reviewed student overview lists eight outcomes, with several category amounts marked as three or more. Its printed minima sum to thirty seven, but that does not identify a particular extra course or authorize an arbitrary allocation. The overview is useful evidence of the structure, not a complete named course list or a transfer placement agreement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e5ca81b76dd8d0c5320a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e5ca81b76dd8d0c5320a-guide-2','ds-guide-planning','post:ds-starter-e5ca81b76dd8d0c5320a',NULL,'A sound worksheet must connect the current approved courses, any permitted overlap, and the total without inventing the missing allocation. That is a research task for DegreeSteps before publishing an executable UMPI route. Keep your existing course records intact, but do not buy a random elective to repair the arithmetic. A convincing looking spreadsheet is not enough when the governing course and overlap details have not been established.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e5ca81b76dd8d0c5320a' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e7233dfe834b8affe877','ds-guide-planning','course:saylor-plan-saya0037','question','Can a practice-exam certificate replace the monitored credit final?','Example situation: I’m using Business Statistics material to see whether I’m ready for a credit-bearing assessment. The practice activities help me understand the subject, but I’m not sure what their completion record means for a degree plan. If I finish the practice work or receive a general certificate, can I mark the source course as earned credit? I would like a simple way to track my preparation without confusing it with the particular assessment needed for the college-credit route.','https://degreesteps.com/courses.html?provider=Saylor',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e7233dfe834b8affe877-guide-1','ds-guide-courses','post:ds-starter-e7233dfe834b8affe877',NULL,'Treat practice performance as preparation for the credit-bearing assessment. The current reviewed Saylor policy identifies a monitored credit exam, and a practice or general certificate result does not replace it. Keep the degree course in progress while you prepare. When you complete the actual credit route, retain the original course identifier, completion date, credit recommendation and official record instead of transferring a practice score into the earned-credit fields.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e7233dfe834b8affe877' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e7233dfe834b8affe877-guide-2','ds-guide-momentum','post:ds-starter-e7233dfe834b8affe877',NULL,'Use your checklist to record the readiness steps you have completed, such as reviewing a weak topic or checking assessment requirements. Those tasks can be motivating without increasing the degree’s earned-credit total. Then use the actual credit final as the next academic milestone. If you change providers after practicing, keep your learning notes while evaluating the new source course separately; preparation does not automatically create an original transcript award at either provider.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e7233dfe834b8affe877' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-e73516586270d9754113','ds-guide-campus','school:general','question','How do I compare a cheaper tuition plan when living on campus changes the total?','Example situation: I could commute to one university or live on campus at another. The second school has a generous transfer policy, so the tuition left might be lower, but housing and meals could make it more expensive overall. I want a real college experience and do not want to reduce everything to the lowest tuition number. How can I make this a useful comparison instead of guessing?','https://degreesteps.com/compare-plans.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e73516586270d9754113-guide-1','ds-guide-money','post:ds-starter-e73516586270d9754113',NULL,'Prepared guide answer: Compare the degree plans using the same courses, then keep campus living costs alongside the academic estimate. A tuition saving is not the same as a saving on the full cost of attendance. For each route, identify required university credits, expected term structure, and charges not included in the published plan range. Then add your realistic commuting or housing situation rather than treating either one as free.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e73516586270d9754113' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-e73516586270d9754113-guide-2','ds-guide-campus','post:ds-starter-e73516586270d9754113',NULL,'Prepared guide answer: Make the tradeoff explicit: what part of the campus experience matters enough to pay for, and what could you get while commuting? Compare the same number of realistic university terms, not just one semester of housing against an entire online degree. If a required course sequence adds a term, that may also add living expenses. Keeping those decisions visible helps you choose for both your budget and your experience.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-e73516586270d9754113' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ee0f41d5c3b3aa3b2092','ds-guide-planning','course:straighterline-dc85139a52ba417213','question','How do I compare a course price with a subscription price fairly?','Example situation: I’m comparing Introduction to Business across providers, but the advertised prices use different formats. One may involve a course purchase and membership, while another is described as a monthly plan. What should I include so the cheaper-looking option does not become more expensive for my situation? I’m happy to estimate study time, but I want the estimate to show which parts are known charges and which parts depend on how long I take.','https://degreesteps.com/courses.html?provider=StraighterLine',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ee0f41d5c3b3aa3b2092-guide-1','ds-guide-money','post:ds-starter-ee0f41d5c3b3aa3b2092',NULL,'Compare the full eligible purchase scenario for the courses your degree can use. Include the relevant membership, separate course charges, required lab materials or assessment charges, and transcript costs where they apply. Keep taxes and other unknown items identified instead of treating them as zero. A headline course price and a monthly subscription are different products, so the plan should explain the assumptions behind either total rather than comparing those two numbers directly.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ee0f41d5c3b3aa3b2092' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ee0f41d5c3b3aa3b2092-guide-2','ds-guide-transfers','post:ds-starter-ee0f41d5c3b3aa3b2092',NULL,'Use more than one plausible study-duration scenario when a membership is involved. Your own available hours and the course’s actual requirements should shape that range. Then check whether another planned course could use the same membership without overlapping an unnecessary second provider. The cheapest route for one student can differ from the cheapest route for another, even when both choose the same degree and the same supported receiving requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ee0f41d5c3b3aa3b2092' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-eef84acd63af5bef02e0','ds-guide-planning','course:studycom-plan-sdcm0212','question','How do I choose between two database courses accepted for the same requirement?','Example situation: I’m considering a technology degree and have found more than one possible Study.com database course. One sounds focused on databases while another appears under analytics. If both are presented as alternatives for a foundation requirement, what should drive my choice? I’d like to avoid choosing only by the shortest-looking syllabus, especially if one course would help with later programming or data work and another might fit a different degree better.','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-eef84acd63af5bef02e0-guide-1','ds-guide-courses','post:ds-starter-eef84acd63af5bef02e0',NULL,'First establish that each option is supported for the same exact receiving requirement and current program. Similar subject matter does not establish that result by itself. Once the alternatives are established, compare their published learning objectives, assignments and assessment format with the work you expect to do next. The course you choose should remain attached to the foundation row, while the other course stays a saved alternative rather than becoming an extra requirement.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-eef84acd63af5bef02e0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-eef84acd63af5bef02e0-guide-2','ds-guide-transfers','post:ds-starter-eef84acd63af5bef02e0',NULL,'Use your other likely degrees as a second comparison. A database course might fill a named requirement in one degree and only an elective in another. Saving both alternatives before deciding lets you compare those consequences using the same original-course facts. When you select a route, keep one source choice active for the receiving row and retain your notes about the decision. That makes a later change of major much easier to assess.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-eef84acd63af5bef02e0' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-ef5589dd29060ab524f8','ds-guide-campus','school:asu','question','I want the ASU campus experience. How do I avoid confusing online transfer options with campus eligibility?','Example situation: I like Arizona State University because of its campus environment and the wider recognition of the school. I am open to completing some lower-cost coursework first, but my goal is an on-campus degree rather than simply any online bachelor’s. I see many providers talk broadly about transfer credit. How should I compare options while keeping the exact campus program and its rules at the center?','https://degreesteps.com/campuses.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ef5589dd29060ab524f8-guide-1','ds-guide-transfers','post:ds-starter-ef5589dd29060ab524f8',NULL,'Prepared guide answer: Start with the intended ASU campus and degree, not with a provider’s general list of schools. Use Find a campus for the college shortlist and keep original institutional coursework separate from ACE or NCCRS recommendations in My courses. These credit origins can have different receiving rules. An online course being available, or a university appearing on a provider page, does not establish its use in your exact campus degree.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ef5589dd29060ab524f8' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-ef5589dd29060ab524f8-guide-2','ds-guide-campus','post:ds-starter-ef5589dd29060ab524f8',NULL,'Prepared guide answer: Compare the academic work that would remain on campus, including any admission, residency, major, and course-sequence conditions relevant to that program. If DegreeSteps does not yet have a complete researched route for the exact choice, use its official degree link for a specific research request instead of buying a generic basket of outside courses. Brand and campus experience can remain priorities without making unsupported assumptions about transfer.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-ef5589dd29060ab524f8' AND p.user_id='ds-guide-campus' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-f0e659a467a47f471d71','ds-guide-planning','school:tesu','question','Why are my easy electives not closing the TESU upper level requirements?','Example situation: I have enough credits to make the TESU total look close, but the audit still shows upper level work. I thought extra electives would fill any leftover space. How should I decide which outside courses are actually worth taking next? I would like to avoid reaching the overall credit total and then discovering that the major still needs several specific advanced courses.','https://tesu.smartcatalogiq.com/en/current/undergraduate-catalog/degree-programs-and-certificates/bachelor-of-science-in-business-administration/bsba-in-accounting/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f0e659a467a47f471d71-guide-1','ds-guide-courses','post:ds-starter-f0e659a467a47f471d71',NULL,'A degree total and its internal requirements are separate checks. The reviewed TESU models retain an eighteen credit upper level minimum, and individual degrees can constrain how those credits are distributed. In Accounting, the modeled area and business core have their own upper level minimums. A lower level elective can increase total credits while doing nothing for those groups, even if its title sounds specialized or difficult.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f0e659a467a47f471d71' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f0e659a467a47f471d71-guide-2','ds-guide-planning','post:ds-starter-f0e659a467a47f471d71',NULL,'Look at the still open requirement groups before shopping by provider price. Choose an option with an established receiving level and a placement in the relevant group, then check the source identity and workload. Do not infer upper level status from a high course number alone. Once those constrained groups have a workable route, use the genuine free elective space for flexible courses rather than letting cheap electives crowd out essential work.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f0e659a467a47f471d71' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-f1bd1391760ecea2ae2c','ds-guide-planning','school:wgu','question','Should a career changer choose WGU Finance or Business Management for speed?','Example situation: I work outside business and want a bachelor degree that helps me change careers. Finance interests me, but Business Management looks broader. I have some general education credit and little specialized coursework. Should I choose the route with the fastest estimated completion, or the degree that sounds closer to my ideal job? I want the plan to help me weigh both rather than rank only by price.','https://degreesteps.com/degree-plans/wgu-finance/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f1bd1391760ecea2ae2c-guide-1','ds-guide-careers','post:ds-starter-f1bd1391760ecea2ae2c',NULL,'Begin with a few realistic target roles and note whether they request a specific major, general business preparation, or a separate credential. Then compare the published Finance and Business Management worksheets using the same original course collection. Look at the specialized requirements that remain, not just the courses both degrees can accept. A faster route is valuable only if it still supports the job direction you are choosing.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f1bd1391760ecea2ae2c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f1bd1391760ecea2ae2c-guide-2','ds-guide-money','post:ds-starter-f1bd1391760ecea2ae2c',NULL,'Use time and cost as tradeoffs after the career constraint is clear. If either degree works for the role, the better fit may be the one with a more manageable remaining workload. If Finance is specifically important, extra study may be worthwhile rather than wasted. Start with a supported course shared by the serious alternatives while deciding, and keep specialized purchases for when the destination is sufficiently clear.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f1bd1391760ecea2ae2c' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-f4abbf4e4e492ead8ac6','ds-guide-planning','school:general','question','I struggle with open-ended study. Can a flexible degree still give me enough structure?','Example situation: I have ADHD and tend to do better with clear, short tasks than with a distant deadline and unlimited material. A self-paced program sounds appealing because my work schedule changes, but I worry that I would keep postponing everything. I want to compare formats without assuming that more freedom is always better. What could a realistic first course and weekly routine look like?','https://degreesteps.com/plan.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f4abbf4e4e492ead8ac6-guide-1','ds-guide-planning','post:ds-starter-f4abbf4e4e492ead8ac6',NULL,'Prepared guide answer: Use the degree plan’s next action to narrow the work to one real course or task, then compare the structure of the course itself. Look at assignment checkpoints, feedback, and any scheduled support alongside pace and price. Self-paced access does not provide the same structure for everyone. Choosing a course with visible milestones may be more useful for you than selecting the route with the boldest speed claim.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f4abbf4e4e492ead8ac6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f4abbf4e4e492ead8ac6-guide-2','ds-guide-momentum','post:ds-starter-f4abbf4e4e492ead8ac6',NULL,'Prepared guide answer: Set a small weekly commitment around your actual schedule and keep a clear stopping point for each session. You can record course progress and use the plan’s checklist to make the next task visible. If you need formal accommodations, arrange them through the relevant support process separately. Study preferences should guide your choices, but the app should not treat a diagnosis as evidence of how quickly you will finish.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f4abbf4e4e492ead8ac6' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-f68ad7c89bd89ad7d132','ds-guide-planning','course:studycom-plan-sdcm0068','question','Are current Study.com credit exams unproctored, or am I reading an old policy?','Example situation: I’m considering Statistics 101 and finding conflicting advice about webcams, proctors and final exams. Some posts seem to describe a different version of the membership or an older process. I would prefer an unproctored option, but I can complete reasonable identity checks. How should I distinguish the actual current exam format from general comments about the provider, and what equipment should I plan to have available before starting the course?','https://degreesteps.com/courses.html?provider=Study.com',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f68ad7c89bd89ad7d132-guide-1','ds-guide-courses','post:ds-starter-f68ad7c89bd89ad7d132',NULL,'For the exact reviewed Study.com courses, the current College Saver and College Saver Pro policy describes open-book, unproctored exams. It also requires identity verification before finals, and a camera-enabled device may be needed for that check. The reviewed policy says finals use a desktop or laptop. Those conditions should appear together: unproctored does not mean there are no identity or device requirements at any stage of the process.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f68ad7c89bd89ad7d132' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f68ad7c89bd89ad7d132-guide-2','ds-guide-transfers','post:ds-starter-f68ad7c89bd89ad7d132',NULL,'Use the course’s assessment evidence and its review date when comparing it with another provider. An older forum post can still describe someone’s experience accurately while reflecting a previous policy. Keep your preference for unproctored assessments in the plan, then review the exact course conditions before the enrollment action. A general provider reputation should not override a documented course exception or substitute for the current credit-bearing product’s published assessment requirements.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f68ad7c89bd89ad7d132' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-f6b3140a31265cb48db4','ds-guide-planning','course:upi-study-upis-0010','question','Are all UPI courses ACE-recommended, or do I need to distinguish its credit routes?','Example situation: I’m browsing UPI because its catalog includes subjects that could help my degree plan. I see references to both ACE and NCCRS and don’t want to assume those labels describe every course in exactly the same way. How should I use the courses currently listed in DegreeSteps? I want to save useful options while understanding which recommendation has actually been reviewed and how that differs from acceptance by my chosen university and exact degree program.','https://degreesteps.com/courses.html?provider=UPI%20Study',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f6b3140a31265cb48db4-guide-1','ds-guide-courses','post:ds-starter-f6b3140a31265cb48db4',NULL,'Keep the recommendation system attached to the individual course. The current reviewed UPI library contains twenty-two ACE course identities matched to independent exhibits, recommendation periods and current provider offerings. That does not establish that every UPI catalog item is an ACE course. NCCRS-only courses require their own independent records, and their current coverage should not be inferred from a provider-wide statement or from the presence of an ACE recommendation on another course.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f6b3140a31265cb48db4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-f6b3140a31265cb48db4-guide-2','ds-guide-transfers','post:ds-starter-f6b3140a31265cb48db4',NULL,'Save the exact course you are considering, then examine its supported fit within the selected degree. The recommendation describes the original source learning; a receiving-school award and its placement in a degree are separate facts. Keeping those layers visible lets the library expand without overstating transfer coverage. A course can be available to browse and save before it has a fully established placement in every college program that interests you.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-f6b3140a31265cb48db4' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-fb1ba6543a057ff72d8f','ds-guide-planning','school:general','question','Is a degree still worth starting if I only have six hours a week?','Example situation: I have two part-time jobs and can protect about six hours a week for school. I keep seeing stories about finishing an entire degree in a few months, which makes my schedule feel hopeless. My employer would value a bachelor’s degree, and I am comfortable starting slowly if the courses will still help later. What should a realistic first plan look like for me?','https://degreesteps.com/start.html',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fb1ba6543a057ff72d8f-guide-1','ds-guide-planning','post:ds-starter-fb1ba6543a057ff72d8f',NULL,'Prepared guide answer: Start with the time you can keep, not somebody else’s finish date. Use the guided setup to describe your goal, existing learning, and preferred study format. Open a route that fits and focus on its next course rather than its entire credit total. A useful first plan protects your limited hours and avoids buying courses that do not serve the degree you would actually pursue.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fb1ba6543a057ff72d8f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fb1ba6543a057ff72d8f-guide-2','ds-guide-momentum','post:ds-starter-fb1ba6543a057ff72d8f',NULL,'Prepared guide answer: Your first milestone could be completing one applicable course and learning how much effort it takes alongside both jobs. Choose a payment arrangement that remains affordable at that pace, including grading time and possible revisions. Keep finished courses in My courses so progress is retained if your major or school changes. Slow, consistent progress can be a better fit than paying for an aggressive schedule you cannot sustain.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fb1ba6543a057ff72d8f' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-fc51e74413e78e69dc29','ds-guide-planning','school:liberty','question','How should a military learner combine training credits with outside courses?','Example situation: I am exploring Liberty and have military training plus some civilian college coursework. I do not know which records overlap, and I do not want to spend education benefits on a class that my training might already cover. What should I collect first, and how can I compare outside courses while keeping military credit and benefit eligibility from getting mixed together?','https://degreesteps.com/degree-plans/liberty-criminal-justice-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fc51e74413e78e69dc29-guide-1','ds-guide-military','post:ds-starter-fc51e74413e78e69dc29',NULL,'Start with the military training transcript and each original civilian college record. Keep the issuing source, course or training identifier, and the credit information separate. Training credit is not automatically a placement in a particular Liberty requirement, and duplicate content should not be counted twice. Build the initial audit from those records before selecting a new provider course for a potentially covered subject.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fc51e74413e78e69dc29' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fc51e74413e78e69dc29-guide-2','ds-guide-money','post:ds-starter-fc51e74413e78e69dc29',NULL,'Make benefit funding a separate decision from academic transfer. The fact that a course might transfer does not establish that a particular benefit will pay for it, or that using the benefit is your best option. Compare the uncovered requirements, out of pocket cost, and your intended delivery format. That creates a concrete funding question for the benefits process instead of assuming one rule covers both decisions.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fc51e74413e78e69dc29' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_posts (id,user_id,context,kind,title,body,url,plan_json,created_at,updated_at) VALUES ('ds-starter-fea021e8de645fc54d04','ds-guide-planning','school:liberty','question','Why does a high transfer limit not mean every requirement is replaceable?','Example situation: The transfer limit sounds generous, so I expected to take almost everything through outside providers. My criminal justice worksheet still has university courses left even before I reach the maximum. Is the plan leaving savings on the table, or do major requirements work differently from general education? I want to understand the difference before I buy more elective courses.','https://degreesteps.com/degree-plans/liberty-criminal-justice-online/',NULL,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,url=excluded.url,updated_at=excluded.updated_at WHERE community_posts.user_id=excluded.user_id AND community_posts.context=excluded.context AND community_posts.kind='question' AND community_posts.plan_json IS NULL AND community_posts.deleted_at IS NULL AND (community_posts.title IS NOT excluded.title OR community_posts.body IS NOT excluded.body OR community_posts.url IS NOT excluded.url);
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fea021e8de645fc54d04-guide-1','ds-guide-transfers','post:ds-starter-fea021e8de645fc54d04',NULL,'There are two separate questions: how much outside credit the degree permits, and which remaining requirements a particular outside course satisfies. The reviewed Liberty models also preserve major, level, and university coursework constraints. An unused part of the overall limit is not evidence that any elective can replace those rows. Read the remaining requirement first, then inspect its actual outside options rather than starting with the ceiling.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fea021e8de645fc54d04' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
INSERT INTO community_comments (id,user_id,context,parent_id,body,created_at,updated_at) SELECT 'ds-starter-fea021e8de645fc54d04-guide-2','ds-guide-planning','post:ds-starter-fea021e8de645fc54d04',NULL,'Look for supported alternatives on each open row before adding free electives. If an exact major requirement has no established outside match, record it as university coursework in your budget. Filling every possible transfer slot is useful only when the coursework advances this degree. A lower transfer total with all requirements satisfied can be better than a larger pile of accepted credits that does not shorten graduation.',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000 FROM community_posts p WHERE p.id='ds-starter-fea021e8de645fc54d04' AND p.user_id='ds-guide-planning' AND p.deleted_at IS NULL ON CONFLICT(id) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at WHERE community_comments.user_id=excluded.user_id AND community_comments.context=excluded.context AND community_comments.parent_id IS NULL AND community_comments.deleted_at IS NULL AND community_comments.body IS NOT excluded.body;
